$$;


--
-- Name: deal_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_detail(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE; v_roles text[];
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  -- visibility mirrors the RLS policy: staff in-org, or a party to the deal
  IF NOT (has_staff_access() AND v_deal.org_id = current_org())
     AND NOT EXISTS (SELECT 1 FROM contract_parties cp
                      WHERE cp.contract_id = v_deal.contract_id
                        AND cp.contact_id = current_contact_id()) THEN
    RAISE EXCEPTION 'not authorized for this deal';
  END IF;

  v_roles := deal_party_roles(v_deal.deal_type);

  RETURN jsonb_build_object(
    'id', v_deal.id,
    'display_code', v_deal.display_code,
    'deal_type', v_deal.deal_type,
    'status', v_deal.status,
    'completed_at', v_deal.completed_at,
    'notes', v_deal.notes,
    'contract_id', v_deal.contract_id,
    'created_at', v_deal.created_at,
    'roles', to_jsonb(v_roles),
    'parties', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'party_role', cp.party_role,
               'contact_id', cp.contact_id,
               'name', nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''),
               'email', c.email,
               'display_code', c.display_code)
             ORDER BY array_position(v_roles, cp.party_role), cp.signer_order, cp.id)
        FROM contract_parties cp JOIN contacts c ON c.id = cp.contact_id
       WHERE cp.contract_id = v_deal.contract_id), '[]'::jsonb),
    'consideration', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', dc.id, 'party_role', dc.party_role, 'kind', dc.kind,
               'horse_id', dc.horse_id,
               'horse_name', (SELECT coalesce(nullif(h.registered_name,''), h.nickname)
                                FROM horses h WHERE h.id = dc.horse_id),
               'amount', dc.amount, 'detail', dc.detail)
             ORDER BY array_position(v_roles, dc.party_role), dc.sort_order)
        FROM deal_consideration dc WHERE dc.deal_id = v_deal.id), '[]'::jsonb),
    'documents', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'document_id', d.id, 'title', d.title, 'display_code', d.display_code,
               'template_key', t.template_key, 'status', d.status,
               'workflow_state', d.workflow_state, 'created_at', d.created_at)
             ORDER BY d.created_at)
        FROM documents d JOIN contract_templates t ON t.id = d.template_id
       WHERE d.contract_id = v_deal.contract_id AND d.deleted_at IS NULL), '[]'::jsonb)
  );
END;
$$;


--
-- Name: deal_document_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_document_status(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'template_key', o.template_key,
             'title', o.title,
             'required', o.required,
             'present', EXISTS (
               SELECT 1 FROM documents d
                 JOIN contract_templates t ON t.id = d.template_id
                WHERE d.contract_id = v_deal.contract_id
                  AND d.deleted_at IS NULL AND d.workflow_state <> 'void'
                  AND t.template_key = o.template_key),
             'executed', EXISTS (
               SELECT 1 FROM documents d
                 JOIN contract_templates t ON t.id = d.template_id
                WHERE d.contract_id = v_deal.contract_id
                  AND d.deleted_at IS NULL AND d.status = 'EXECUTED'
                  AND t.template_key = o.template_key))
           ORDER BY o.sort_order)
      FROM deal_template_options(v_deal.deal_type) o), '[]'::jsonb);
END;
$$;


--
-- Name: deal_party_roles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_party_roles(p_deal_type text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  -- [party A (the giving/owning side), party B (the receiving side)]
  SELECT CASE p_deal_type
           WHEN 'SALE'  THEN ARRAY['SELLER','BUYER']
           WHEN 'LEASE' THEN ARRAY['LESSOR','LESSEE']
         END;
$$;


--
-- Name: FUNCTION deal_party_roles(p_deal_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.deal_party_roles(p_deal_type text) IS 'The party designations a deal type uses. The type is chosen FIRST precisely so the two sides can be labelled before members are added (deal plan L2).';


--
-- Name: deal_record_export(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_record_export(p_deal_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal  deals%ROWTYPE;
  v_roles text[];
  v_out   text[] := '{}';
  v_role  text;
  r       record;
  v_any   boolean;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  IF NOT (has_staff_access() AND v_deal.org_id = current_org())
     AND NOT EXISTS (SELECT 1 FROM contract_parties cp
                      WHERE cp.contract_id = v_deal.contract_id
                        AND cp.contact_id = current_contact_id()) THEN
    RAISE EXCEPTION 'not authorized for this deal';
  END IF;

  v_roles := deal_party_roles(v_deal.deal_type);

  v_out := v_out || ('DEAL RECORD — ' || initcap(lower(v_deal.deal_type)));
  v_out := v_out || ('Reference: ' || coalesce(v_deal.display_code, v_deal.id::text));
  v_out := v_out || ('Opened: ' || to_char(v_deal.created_at, 'FMMonth FMDD, YYYY'));
  v_out := v_out || ('Status: ' || CASE v_deal.status
                                     WHEN 'pending'  THEN 'Pending'
                                     WHEN 'complete' THEN 'Complete'
                                     ELSE 'Void' END);
  IF v_deal.completed_at IS NOT NULL THEN
    v_out := v_out || ('Completed: ' || to_char(v_deal.completed_at, 'FMMonth FMDD, YYYY'));
  END IF;

  -- each side: who they are, and what they give
  FOREACH v_role IN ARRAY v_roles LOOP
    v_out := v_out || ''::text;
    v_out := v_out || (upper(coalesce(initcap(lower(v_role)), v_role)));

    v_any := false;
    FOR r IN
      SELECT nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), '') AS nm,
             c.email, c.phone_display AS phone, c.address_composed AS addr
        FROM contract_parties cp JOIN contacts c ON c.id = cp.contact_id
       WHERE cp.contract_id = v_deal.contract_id AND cp.party_role = v_role
       ORDER BY cp.signer_order NULLS LAST, cp.id
    LOOP
      v_any := true;
      v_out := v_out || ('  ' || coalesce(r.nm, r.email, 'Unnamed')
                         || coalesce(' · ' || r.email, '')
                         || coalesce(' · ' || r.phone, ''));
      IF nullif(btrim(coalesce(r.addr,'')),'') IS NOT NULL THEN
        v_out := v_out || ('    ' || r.addr);
      END IF;
    END LOOP;
    IF NOT v_any THEN v_out := v_out || '  (nobody named yet)'::text; END IF;

    v_out := v_out || '  Gives:'::text;
    v_any := false;
    FOR r IN
      SELECT dc.kind, dc.amount, dc.detail,
             (SELECT coalesce(nullif(h.registered_name,''), h.nickname) FROM horses h WHERE h.id = dc.horse_id) AS horse
        FROM deal_consideration dc
       WHERE dc.deal_id = p_deal_id AND dc.party_role = v_role
       ORDER BY dc.sort_order
    LOOP
      v_any := true;
      v_out := v_out || ('    ' || CASE r.kind
        WHEN 'HORSE'    THEN 'Horse: ' || coalesce(r.horse, 'unnamed')
        WHEN 'PAYMENT'  THEN 'Payment: ' || coalesce(fmt_money(r.amount), '')
                             || coalesce(' — ' || r.detail, '')
        WHEN 'GOODS'    THEN 'Goods: ' || coalesce(r.detail, '')
        WHEN 'SERVICES' THEN 'Services: ' || coalesce(r.detail, '')
        ELSE r.kind || ': ' || coalesce(r.detail, '') END);
    END LOOP;
    IF NOT v_any THEN v_out := v_out || '    (nothing listed yet)'::text; END IF;
  END LOOP;

  -- documents and where each stands
  v_out := v_out || ''::text;
  v_out := v_out || 'DOCUMENTS'::text;
  v_any := false;
  FOR r IN
    SELECT d.id, coalesce(d.title, t.template_key) AS title, d.display_code, d.status,
           d.workflow_state, d.effective_date,
           (SELECT count(*) FROM signatures s
             WHERE s.document_id = d.id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL) AS signed,
           (SELECT count(*) FROM document_parties dp
             WHERE dp.document_id = d.id AND dp.is_signer) AS signers
      FROM documents d JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contract_id = v_deal.contract_id AND d.deleted_at IS NULL
       -- a voided document is not part of the record of the deal
       AND coalesce(d.workflow_state, '') <> 'void'
     ORDER BY d.created_at
  LOOP
    v_any := true;
    v_out := v_out || ('  ' || r.title
                       || coalesce(' (' || r.display_code || ')', '')
                       || ' — ' || CASE WHEN r.status = 'EXECUTED' THEN 'signed by all parties'
                                        ELSE r.signed || ' of ' || r.signers || ' signatures' END
                       || coalesce(', effective ' || to_char(r.effective_date, 'FMMonth FMDD, YYYY'), ''));
  END LOOP;
  IF NOT v_any THEN v_out := v_out || '  (none yet)'::text; END IF;

  IF nullif(btrim(coalesce(v_deal.notes,'')),'') IS NOT NULL THEN
    v_out := v_out || ''::text;
    v_out := v_out || 'NOTES'::text;
    v_out := v_out || ('  ' || v_deal.notes);
  END IF;

  RETURN array_to_string(v_out, E'\n');
END;
$$;


--
-- Name: deal_template_options(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_template_options(p_deal_type text) RETURNS TABLE(template_key text, title text, required boolean, sort_order integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT t.template_key, t.title, t.required, t.sort_order
    FROM (VALUES
      ('SALE',  'HORSE_BILL_OF_SALE', 'Equine Bill of Sale',               true,  10),
      ('SALE',  'HORSE_SALE_V2',      'Horse Sale and Purchase Agreement', false, 20),
      ('LEASE', 'HORSE_LEASE_V2',     'Horse Lease Agreement',             true,  10)
    ) AS t(deal_type, template_key, title, required, sort_order)
   WHERE t.deal_type = p_deal_type;
$$;


--
-- Name: decide_booking_change(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_booking_change(p_change_id uuid, p_approve boolean, p_waive_fee boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cr    booking_change_requests%ROWTYPE;
  v_b     bookings%ROWTYPE;
  v_when  text;
  v_delta interval;
  v_scope text;
  v_ids   uuid[];
  v_n     int;
  rid     uuid;
  r       bookings%ROWTYPE;
  v_freed int := 0;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_cr FROM booking_change_requests WHERE id = p_change_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'change request not found'; END IF;
  IF v_cr.status <> 'pending' THEN RAISE EXCEPTION 'already decided'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = v_cr.booking_id;
  v_scope := coalesce(v_cr.scope, 'one');

  IF NOT p_approve THEN
    UPDATE booking_change_requests SET status='rejected', decided_by=auth.uid(), decided_at=now() WHERE id=p_change_id;
    UPDATE bookings SET status = CASE WHEN kind='lesson' THEN 'scheduled' ELSE 'confirmed' END, updated_at=now()
      WHERE id = v_cr.booking_id AND status='pending';
    IF v_b.account_user_id IS NOT NULL AND booking_notifies_client(v_b) THEN
      INSERT INTO notifications (org_id, user_id, kind, title, link)
        VALUES (v_b.org_id, v_b.account_user_id, 'booking_change_rejected',
                initcap(v_cr.request_kind) || ' request declined — please reach out', '/app/calendar');
    END IF;
    RETURN jsonb_build_object('status','rejected');
  END IF;

  -- resolve the affected occurrences by scope
  IF v_b.series_id IS NULL OR v_scope = 'one' THEN
    v_ids := ARRAY[v_b.id];
  ELSIF v_scope = 'all' THEN
    SELECT array_agg(id) INTO v_ids FROM bookings WHERE series_id = v_b.series_id;
  ELSIF v_scope = 'future' THEN
    SELECT array_agg(id) INTO v_ids FROM bookings WHERE series_id = v_b.series_id AND starts_at >= v_b.starts_at;
  ELSIF v_scope LIKE 'weeks:%' THEN
    v_n := nullif(split_part(v_scope, ':', 2), '')::int;
    SELECT array_agg(id) INTO v_ids FROM (
      SELECT id FROM bookings WHERE series_id = v_b.series_id AND starts_at >= v_b.starts_at
      ORDER BY starts_at LIMIT coalesce(v_n, 1)) x;
  ELSE
    v_ids := ARRAY[v_b.id];
  END IF;

  IF v_cr.request_kind = 'reschedule' THEN
    v_delta := v_cr.proposed_starts_at - v_b.starts_at;
    FOREACH rid IN ARRAY v_ids LOOP
      SELECT * INTO r FROM bookings WHERE id = rid;
      UPDATE bookings SET starts_at = r.starts_at + v_delta, ends_at = r.ends_at + v_delta,
        status = CASE WHEN kind='lesson' THEN 'scheduled' ELSE 'confirmed' END,
        reminder_1h_sent_at = NULL, reminder_2h_sent_at = NULL, updated_at=now()
      WHERE id = rid;
    END LOOP;
    v_when := to_char(v_cr.proposed_starts_at, 'FMMon FMDD, HH12:MI AM');
  ELSE
    FOREACH rid IN ARRAY v_ids LOOP
      SELECT * INTO r FROM bookings WHERE id = rid;
      UPDATE bookings SET status='cancelled', updated_at=now() WHERE id = rid;
      IF (v_cr.request_kind = 'defer' OR r.kind = 'lesson') AND r.client_id IS NOT NULL THEN
        INSERT INTO lesson_credits (org_id, client_id, package_key, credits_total, credits_remaining, purchased_at)
          VALUES (r.org_id, r.client_id, 'change_credit', 1, 1, now());
        v_freed := v_freed + 1;
      END IF;
    END LOOP;
    v_when := to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM');
  END IF;

  UPDATE booking_change_requests
    SET status='approved', fee_waived = p_waive_fee, decided_by=auth.uid(), decided_at=now()
    WHERE id=p_change_id;

  IF v_b.account_user_id IS NOT NULL AND booking_notifies_client(v_b) THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_b.org_id, v_b.account_user_id, 'booking_' || v_cr.request_kind || '_approved',
              CASE v_cr.request_kind
                WHEN 'reschedule' THEN 'Your lesson is now ' || v_when
                WHEN 'defer' THEN 'Lesson deferred — a credit is on your account'
                ELSE 'Your booking on ' || v_when || ' is cancelled' END,
              '/app/calendar');
  END IF;

  RETURN jsonb_build_object('status','approved', 'kind', v_cr.request_kind, 'affected', coalesce(array_length(v_ids,1),1));
END;
$$;


--
-- Name: decline_contract_termination(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decline_contract_termination(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_title text; v_requester uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, title, termination_requested_by INTO v_org, v_title, v_requester
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL
      AND termination_requested_at IS NOT NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'no pending termination request'; END IF;
  IF NOT caller_is_document_party_or_staff(p_document_id) THEN RAISE EXCEPTION 'not authorized'; END IF;

  UPDATE documents SET termination_requested_at = NULL, termination_requested_by = NULL,
         termination_request_reason = NULL, updated_at = now()
   WHERE id = p_document_id;

  -- ITEM 5d: same as approve — the request is answered, so it resolves.
  PERFORM resolve_notifications_for_link(
    '/app/contracts/' || p_document_id::text, auth.uid(), 'contract_termination_requested');

  -- tell the requester it was declined
  IF v_requester IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    SELECT v_org, pr.user_id, 'contract_termination_declined',
           coalesce(v_title,'A contract') || ' — termination declined',
           'The other party declined the request to terminate. The contract remains in force.',
           '/app/contracts/' || p_document_id::text
      FROM profiles pr WHERE pr.contact_id = v_requester AND pr.user_id IS NOT NULL;
  END IF;
END;
$$;


--
-- Name: delete_calendar_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_calendar_item(p_id uuid, p_scope text DEFAULT 'one'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_row bookings%ROWTYPE;
  v_n   integer;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_row FROM bookings WHERE id = p_id AND org_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'item not found in this org'; END IF;

  IF p_scope = 'one' OR v_row.series_id IS NULL THEN
    DELETE FROM bookings WHERE id = p_id;
    v_n := 1;
  ELSIF p_scope = 'future' THEN
    DELETE FROM bookings WHERE series_id = v_row.series_id AND starts_at >= v_row.starts_at;
    GET DIAGNOSTICS v_n = ROW_COUNT;
  ELSE
    DELETE FROM bookings WHERE series_id = v_row.series_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
  END IF;
  RETURN v_n;
END;
$$;


--
-- Name: delete_contract_comment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_contract_comment(p_comment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_author uuid; v_me uuid; v_sub timestamptz; v_parent uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT document_id, author_contact_id, submitted_at, parent_request_id
    INTO v_doc, v_author, v_sub, v_parent
    FROM contract_change_requests WHERE id = p_comment_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown comment'; END IF;
  SELECT contact_id INTO v_me FROM comment_author_identity(v_doc);
  IF v_me IS NULL OR v_me <> v_author THEN RAISE EXCEPTION 'only the author may delete this comment'; END IF;
  IF v_parent IS NULL AND v_sub IS NOT NULL THEN
    RAISE EXCEPTION 'this request was submitted for review and can no longer be withdrawn';
  END IF;
  DELETE FROM contract_change_requests WHERE id = p_comment_id OR parent_request_id = p_comment_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: deliver_evaluation_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_evaluation_report(p_report_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_org     uuid;
  v_user    uuid;
  v_consistent boolean;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT contact_id, org_id INTO v_contact, v_org FROM evaluation_reports
   WHERE id = p_report_id AND org_id = current_org();
  IF v_contact IS NULL THEN RAISE EXCEPTION 'report not found'; END IF;

  SELECT EXISTS (SELECT 1 FROM groups g
                  WHERE g.contact_id = v_contact AND g.group_type IN ('RIDER','HORSE_OWNER'))
    INTO v_consistent;

  UPDATE evaluation_reports
     SET status = 'delivered', delivered_at = now(),
         available_until = CASE WHEN v_consistent THEN NULL ELSE now() + interval '90 days' END
   WHERE id = p_report_id;

  -- ALERT the client (their account), not just staff. notifications.user_id is
  -- the account; resolve it from the report's contact.
  SELECT user_id INTO v_user FROM profiles WHERE contact_id = v_contact LIMIT 1;
  IF v_user IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    VALUES (v_org, v_user, 'evaluation_report_ready',
            'Your horse evaluation report is ready',
            'Your evaluation report is available to review, download, or share.',
            '/app/evaluations');
  END IF;
  PERFORM notify_staff(v_org, 'evaluation_report_delivered',
    'An evaluation report was delivered', '/app/ops/oversight');

  RETURN jsonb_build_object('ok', true, 'consistent_client', v_consistent);
END;
$$;


--
-- Name: derive_affiliations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_affiliations(p_contact_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ex AS (
    SELECT bool_or(t.template_key = 'RELEASE_PARTICIPANT') AS sig_rider,
           bool_or(t.template_key = 'RELEASE_HORSE_CARE')  AS sig_care,
           bool_or(t.template_key = 'HORSE_EMERGENCY_VET') AS sig_vet
      FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contact_id = p_contact_id AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
  )
  SELECT (
    SELECT array_agg(g ORDER BY g) FROM (
      SELECT 'RIDER'::text AS g WHERE (SELECT sig_rider FROM ex)
      UNION
      SELECT 'HORSE_OWNER' WHERE (SELECT (sig_care AND sig_vet) FROM ex)
         OR EXISTS (SELECT 1 FROM horses h WHERE h.current_owner_contact_id = p_contact_id AND h.deleted_at IS NULL)
      UNION
      SELECT 'PARENT_GUARDIAN' WHERE EXISTS (
        SELECT 1 FROM document_parties dp
         WHERE dp.contact_id = p_contact_id AND dp.party_role = 'GUARDIAN')
    ) s
  );
$$;


--
-- Name: derive_request_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_request_status(p_request_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v_active int; v_total int;
BEGIN
  SELECT count(*) FILTER (WHERE state NOT IN ('declined','not_a_booking','withdrawn','expired','confirmed')),
         count(*)
    INTO v_active, v_total
    FROM request_selections WHERE request_id = p_request_id;
  IF v_total = 0 THEN RETURN 'new'; END IF;
  IF v_active > 0 THEN RETURN 'open'; END IF;
  RETURN 'closed';
END;
$$;


--
-- Name: dm_delete_message(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_delete_message(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE direct_messages
     SET deleted_at = now(), body = ''
   WHERE id = p_message_id AND sender_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'not your message'; END IF;
END;
$$;


--
-- Name: dm_edit_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_edit_message(p_message_id uuid, p_body text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF btrim(coalesce(p_body,'')) = '' THEN RAISE EXCEPTION 'empty message'; END IF;
  UPDATE direct_messages
     SET body = p_body, edited_at = now()
   WHERE id = p_message_id AND sender_id = auth.uid() AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'not your message'; END IF;
END;
$$;


--
-- Name: dm_hide_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_hide_conversation(p_other_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO dm_hidden_conversations (user_id, other_id, hidden_before)
  VALUES (auth.uid(), p_other_id, now())
  ON CONFLICT (user_id, other_id) DO UPDATE SET hidden_before = now();
END;
$$;


--
-- Name: dm_list_conversations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_list_conversations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_out jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  WITH pairs AS (
    SELECT dm.*,
           CASE WHEN dm.sender_id = v_uid THEN dm.recipient_id ELSE dm.sender_id END AS other_id
      FROM direct_messages dm
     WHERE (dm.sender_id = v_uid OR dm.recipient_id = v_uid)
  ),
  visible AS (
    SELECT p.*
      FROM pairs p
      LEFT JOIN dm_hidden_conversations h
        ON h.user_id = v_uid AND h.other_id = p.other_id
     WHERE h.hidden_before IS NULL OR p.created_at > h.hidden_before
  ),
  latest AS (
    SELECT DISTINCT ON (other_id) other_id, id, body, deleted_at, created_at, sender_id
      FROM visible
     ORDER BY other_id, created_at DESC
  ),
  unread AS (
    SELECT other_id, count(*) AS n
      FROM visible
     WHERE recipient_id = v_uid AND read_at IS NULL AND deleted_at IS NULL
     GROUP BY other_id
  )
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.last_at DESC), '[]'::jsonb) INTO v_out
    FROM (
      SELECT l.other_id                                   AS user_id,
             pr.display_name, pr.first_name, pr.avatar_url,
             CASE WHEN l.deleted_at IS NOT NULL THEN NULL ELSE l.body END AS last_body,
             (l.sender_id = v_uid)                        AS last_mine,
             l.created_at                                 AS last_at,
             coalesce(u.n, 0)                             AS unread
        FROM latest l
        LEFT JOIN profiles pr ON pr.user_id = l.other_id
        LEFT JOIN unread u ON u.other_id = l.other_id
    ) t;

  RETURN v_out;
END;
$$;


--
-- Name: dm_mark_conversation_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_mark_conversation_read(p_other_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE direct_messages
     SET read_at = now()
   WHERE recipient_id = auth.uid() AND sender_id = p_other_id AND read_at IS NULL;
END;
$$;


--
-- Name: dm_unread_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_unread_total() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(count(*), 0)::int
    FROM direct_messages dm
    LEFT JOIN dm_hidden_conversations h
      ON h.user_id = auth.uid() AND h.other_id = dm.sender_id
   WHERE dm.recipient_id = auth.uid()
     AND dm.read_at IS NULL
     AND dm.deleted_at IS NULL
     AND (h.hidden_before IS NULL OR dm.created_at > h.hidden_before);
$$;


--
-- Name: doc_status_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.doc_status_code(p_status text, p_workflow text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status = 'EXECUTED' THEN 'signed'
    WHEN p_status = 'VOID'     THEN 'void'
    WHEN p_workflow = 'in_review' THEN 'sent_for_review'
    WHEN p_workflow = 'locked'    THEN 'ready_to_sign'
    WHEN p_workflow IN ('editing') THEN 'in_progress'
    WHEN p_status = 'AWAITING_SIGNATURE' THEN 'ready_to_sign'
    ELSE 'assigned' END;
$$;


--
-- Name: document_changes_frozen(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_changes_frozen(p_document_id uuid, p_author_contact_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Nothing freezes a document that nobody has signed. The old rule froze on a
  -- counterparty OPENING it, which made a normal joint review lock the author
  -- out of their own draft.
  SELECT EXISTS (
    SELECT 1 FROM documents d
     WHERE d.id = p_document_id
       AND d.status = 'EXECUTED');
$$;


--
-- Name: FUNCTION document_changes_frozen(p_document_id uuid, p_author_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.document_changes_frozen(p_document_id uuid, p_author_contact_id uuid) IS 'TRUE only once the document is fully EXECUTED. Reading a document never freezes it — the previous rule locked the author out as soon as any counterparty opened the draft. A partial signature does not freeze either; it is VOIDED by the edit instead (see void_signatures_on_edit), because a signature attests to a specific text.';


--
-- Name: document_changes_since_signature(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_changes_since_signature(p_document_id uuid, p_contact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target uuid := coalesce(p_contact_id, current_contact_id());
  v_since  timestamptz;
BEGIN
  -- when this party's signature last came off (the withdrawal event), else when
  -- they last signed. Nothing before that is "new" to them.
  SELECT max(l.created_at) INTO v_since
    FROM contract_change_log l
   WHERE l.document_id = p_document_id
     AND l.change_kind = 'signature_removed'
     AND (l.detail ->> 'by_contact_id')::uuid = v_target;

  IF v_since IS NULL THEN
    SELECT max(signed_at) INTO v_since
      FROM signatures
     WHERE document_id = p_document_id AND signer_contact_id = v_target;
  END IF;
  IF v_since IS NULL THEN RETURN '[]'::jsonb; END IF;

  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'id', l.id,
             'change_kind', l.change_kind,
             'field_key', l.field_key,
             'field_label', l.field_label,
             'old_value', l.old_value,
             'new_value', l.new_value,
             'actor', l.actor_label,
             'at', l.created_at)
           ORDER BY l.created_at)
      FROM contract_change_log l
     WHERE l.document_id = p_document_id
       AND l.created_at > v_since
       AND l.change_kind = 'field_value'), '[]'::jsonb);
END;
$$;


--
-- Name: document_horse_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_horse_ids(p_document_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT array_agg(dh.horse_id ORDER BY dh.position, dh.created_at)
       FROM document_horses dh WHERE dh.document_id = p_document_id),
    (SELECT CASE WHEN d.horse_id IS NULL THEN NULL ELSE ARRAY[d.horse_id] END
       FROM documents d WHERE d.id = p_document_id));
$$;


--
-- Name: FUNCTION document_horse_ids(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.document_horse_ids(p_document_id uuid) IS 'Ordered horses a document names (join table, else the legacy horse_id column).';


--
-- Name: document_parties_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_parties_summary(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_horse uuid;
BEGIN
  SELECT org_id, horse_id INTO v_org, v_horse FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT ((has_staff_access() AND v_org = current_org()) OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  RETURN jsonb_build_object(
    'parties', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'party_role', dp.party_role,
          'contact_id', dp.contact_id,
          'name',  nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
          'email', nullif(btrim(coalesce(c.email,'')), ''),
          'phone', nullif(btrim(coalesce(c.phone,'')), ''),
          'address', nullif(btrim(coalesce(
                       nullif(btrim(coalesce(c.address_composed,'')),''),
                       compose_address(c.address_line1, c.address_line2, c.city, c.state, c.postal_code)
                     ,'')), ''),
          -- component fields so the modal can edit the address in parts
          'address_line1', c.address_line1, 'address_line2', c.address_line2,
          'city', c.city, 'state', c.state, 'postal_code', c.postal_code,
          'first_name', c.first_name, 'last_name', c.last_name,
          -- required-field completeness (name+address+email+phone)
          'missing', (
            SELECT coalesce(jsonb_agg(m), '[]'::jsonb) FROM (
              SELECT 'name'    AS m WHERE nullif(btrim(coalesce(c.first_name,'')||' '||coalesce(c.last_name,'')),'') IS NULL
              UNION ALL SELECT 'email'   WHERE nullif(btrim(coalesce(c.email,'')),'') IS NULL
              UNION ALL SELECT 'phone'   WHERE nullif(btrim(coalesce(c.phone,'')),'') IS NULL
              UNION ALL SELECT 'address' WHERE nullif(btrim(coalesce(
                         nullif(btrim(coalesce(c.address_composed,'')),''),
                         compose_address(c.address_line1,c.address_line2,c.city,c.state,c.postal_code)
                       ,'')),'') IS NULL
            ) q
          ))
        ORDER BY dp.party_role, dp.signer_order NULLS LAST, dp.id)
      FROM document_parties dp
      LEFT JOIN contacts c ON c.id = dp.contact_id
      WHERE dp.document_id = p_document_id
        AND dp.party_role IN ('LESSEE','LESSOR','BUYER','SELLER')), '[]'::jsonb),
    'horse_id', v_horse,
    'horse_name', (SELECT coalesce(nullif(registered_name,''), nickname) FROM horses WHERE id = v_horse),
    'horse_missing', CASE WHEN v_horse IS NULL THEN jsonb_build_array('horse')
      ELSE coalesce((SELECT jsonb_agg(m) FROM (
        SELECT 'identity' AS m FROM horses h WHERE h.id = v_horse
         AND nullif(btrim(coalesce(h.registered_name,'')),'') IS NULL
         AND nullif(btrim(coalesce(h.nickname,'')),'') IS NULL
      ) q), '[]'::jsonb) END
  );
END;
$$;


--
-- Name: document_signature_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_signature_state(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_me uuid := current_contact_id();
BEGIN
  RETURN jsonb_build_object(
    'signed_count', (SELECT count(*) FROM signatures
                      WHERE document_id = p_document_id AND signed_at IS NOT NULL AND deleted_at IS NULL),
    'locked_by_signature', EXISTS (SELECT 1 FROM signatures
                      WHERE document_id = p_document_id AND signed_at IS NOT NULL AND deleted_at IS NULL),
    'i_have_signed', EXISTS (SELECT 1 FROM signatures
                      WHERE document_id = p_document_id AND signer_contact_id = v_me
                        AND signed_at IS NOT NULL AND deleted_at IS NULL),
    'signers', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'contact_id', s.signer_contact_id,
               'party_role', s.party_role,
               'name', coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email),
               'signed_at', s.signed_at)
             ORDER BY s.signed_at)
        FROM signatures s LEFT JOIN contacts c ON c.id = s.signer_contact_id
       WHERE s.document_id = p_document_id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL), '[]'::jsonb));
END;
$$;


--
-- Name: documents_sync_workflow_on_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_sync_workflow_on_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'EXECUTED' THEN
    NEW.workflow_state := 'executed';
  ELSIF NEW.status = 'VOID' AND NEW.workflow_state NOT IN ('void','executed') THEN
    NEW.workflow_state := 'void';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: edit_change_request_entry(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_change_request_entry(p_request_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_org uuid; v_author uuid; v_state text; v_cid uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF coalesce(trim(p_body),'') = '' THEN RAISE EXCEPTION 'a body is required'; END IF;

  SELECT document_id, org_id, author_contact_id
    INTO v_doc, v_org, v_author
    FROM contract_change_requests WHERE id = p_request_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown change request'; END IF;

  IF NOT ((has_staff_access() AND v_org = current_org()) OR caller_is_document_party(v_doc)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  v_cid := current_contact_id();
  IF v_author IS DISTINCT FROM v_cid THEN
    RAISE EXCEPTION 'only the author may edit this entry';
  END IF;

  SELECT workflow_state INTO v_state FROM documents WHERE id = v_doc AND deleted_at IS NULL;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this document is % — it is no longer open to change requests', v_state;
  END IF;

  IF change_request_is_frozen(p_request_id) THEN
    RAISE EXCEPTION 'the other party has already seen this entry — it can no longer be edited';
  END IF;

  UPDATE contract_change_requests
     SET body = trim(p_body), edited_at = now(), updated_at = now()
   WHERE id = p_request_id;

  RETURN jsonb_build_object('id', p_request_id, 'edited', true);
END;
$$;


--
-- Name: edit_contract_comment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_contract_comment(p_comment_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_author uuid; v_me uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF coalesce(trim(p_body),'') = '' THEN RAISE EXCEPTION 'comment body required'; END IF;

  SELECT document_id, author_contact_id INTO v_doc, v_author
    FROM contract_change_requests WHERE id = p_comment_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown comment'; END IF;

  v_me := current_contact_id();
  IF v_me IS NULL OR v_me <> v_author THEN
    RAISE EXCEPTION 'only the author may edit this comment';
  END IF;

  -- THE ONE EDITABILITY RULE. Being NOTIFIED does not freeze an entry; being
  -- SEEN by the other party does. Same predicate as upsert_change_request and
  -- edit_change_request_entry, and the same promise the Notify modal makes.
  IF change_request_is_frozen(p_comment_id) THEN
    RAISE EXCEPTION 'the other party has already seen this entry — it can no longer be edited';
  END IF;

  UPDATE contract_change_requests
     SET body = trim(p_body), edited_at = now(), updated_at = now()
   WHERE id = p_comment_id;

  RETURN jsonb_build_object('id', p_comment_id, 'edited', true);
END;
$$;


--
-- Name: ensure_contact_for_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_contact_for_profile(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_denied_users constant uuid[] := ARRAY[
    'b45a5503-89bc-489a-b012-c7fbf5c09632',  -- admin@fhequestrian.com
    'fdbdfe89-76d7-486b-b734-8e23b09e0353',  -- hello@fhequestrian.com
    '3c5d6af1-ce10-45c0-afbb-1ddbdfc77bd5'   -- admin@cactai.io (platform)
  ]::uuid[];
  v_profile    profiles%ROWTYPE;
  v_contact_id uuid;
  v_first text;
  v_last  text;
  v_org   uuid;
BEGIN
  SELECT * INTO v_profile FROM profiles WHERE user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_profile.contact_id IS NOT NULL THEN
    RETURN v_profile.contact_id;
  END IF;

  -- D1: protected identities never regrow a tenant bridge through this path.
  IF p_user_id = ANY(c_denied_users) THEN
    RETURN NULL;
  END IF;

  v_org := coalesce(v_profile.org_id, current_org());
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  v_first := NULLIF(trim(coalesce(v_profile.first_name, '')), '');
  v_last  := NULLIF(trim(coalesce(v_profile.last_name,  '')), '');
  IF v_first IS NULL AND v_last IS NULL THEN
    v_first := coalesce(v_profile.email, 'Unnamed Contact');
  END IF;

  IF v_profile.email IS NOT NULL THEN
    SELECT c.id INTO v_contact_id
    FROM contacts c
    WHERE lower(c.email) = lower(v_profile.email)
      AND c.org_id = v_org
      AND c.deleted_at IS NULL
      AND NOT c.is_company
      AND NOT EXISTS (SELECT 1 FROM profiles p2 WHERE p2.contact_id = c.id AND p2.user_id <> p_user_id)
    ORDER BY c.created_at
    LIMIT 1;
  END IF;

  IF v_contact_id IS NULL THEN
    -- profiles has no address columns — a contact seeded from a bare
    -- profile starts with name/email/phone only. Address, if any, lives on
    -- contacts already and is untouched by this path.
    INSERT INTO contacts (org_id, first_name, last_name, email)
    VALUES (v_org, v_first, v_last, v_profile.email)
    RETURNING id INTO v_contact_id;
  END IF;

  PERFORM promote_contact_to_account(p_user_id, v_contact_id);
  RETURN v_contact_id;
END;
$$;


--
-- Name: ensure_gift_buyer_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_gift_buyer_account(p_gift_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_g      gifts%ROWTYPE;
  v_res    jsonb;
  v_fn     text;
  v_ln     text;
BEGIN
  SELECT * INTO v_g FROM gifts WHERE id = p_gift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'gift not found'; END IF;
  IF v_g.org_id IS NULL OR nullif(btrim(coalesce(v_g.buyer_email,'')),'') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing org or buyer email');
  END IF;

  v_fn := nullif(split_part(coalesce(v_g.buyer_name,''), ' ', 1), '');
  v_ln := nullif(btrim(substr(coalesce(v_g.buyer_name,''),
            coalesce(nullif(position(' ' in coalesce(v_g.buyer_name,'')), 0),
                     length(coalesce(v_g.buyer_name,''))+1))), '');

  -- THE SPINE, with the commercial marker. Categories empty → no service docs.
  v_res := _ensure_client_account(v_g.org_id, lower(btrim(v_g.buyer_email)),
                                  v_fn, v_ln, ARRAY[]::text[], ARRAY[]::text[], 'CUSTOMER');
  RETURN jsonb_build_object('ok', true, 'contact_id', v_res->>'contact_id');
END;
$$;


--
-- Name: ensure_horse_documents(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_horse_documents(p_horse_id uuid, p_contract_id uuid DEFAULT NULL::uuid, p_include_care boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org       uuid := current_org();
  v_horse     horses%ROWTYPE;
  v_owner     uuid;
  v_contact   uuid := current_contact_id();
  v_templates text[] := ARRAY['HORSE_EMERGENCY_VET'];
  v_tpl       text;
  v_doc       uuid;
  v_voided    int := 0;
  v_rc        int := 0;
  v_gen       jsonb := '[]'::jsonb;
  v_may       boolean;
  v_seq       int;
BEGIN
  SELECT * INTO v_horse FROM horses WHERE id = p_horse_id AND org_id = v_org AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'horse not found in this org'; END IF;

  v_may := has_staff_access()
    OR v_horse.current_owner_contact_id = v_contact
    OR v_horse.lessee_contact_id = v_contact
    OR EXISTS (SELECT 1 FROM horse_relationships hr WHERE hr.horse_id = p_horse_id AND hr.party_contact_id = v_contact AND hr.active);
  IF NOT v_may THEN RAISE EXCEPTION 'not authorized for this horse'; END IF;

  v_owner := coalesce(v_horse.current_owner_contact_id, v_contact);
  IF v_owner IS NULL THEN RAISE EXCEPTION 'horse has no owner on record to authorize'; END IF;

  IF p_include_care IS TRUE
     OR (p_include_care IS NULL AND owner_has_executed_template(v_owner, 'RELEASE_HORSE_CARE')) THEN
    v_templates := array_append(v_templates, 'RELEASE_HORSE_CARE');
  END IF;

  FOREACH v_tpl IN ARRAY v_templates LOOP
    WITH tmpl AS (SELECT id FROM contract_templates WHERE template_key = v_tpl)
    UPDATE documents d
       SET deleted_at = now(), deleted_by = auth.uid()
     WHERE d.contact_id = v_owner
       AND d.template_id = (SELECT id FROM tmpl)
       AND d.deleted_at IS NULL
       AND (d.horse_id IS NULL
            OR (d.horse_id = p_horse_id AND d.merged_body LIKE '%{{HORSE.REGISTERED_NAME}}%'));
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    v_voided := v_voided + v_rc;

    IF EXISTS (
      SELECT 1 FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
      WHERE d.contact_id = v_owner AND t.template_key = v_tpl
        AND d.horse_id = p_horse_id AND d.deleted_at IS NULL
        AND d.merged_body NOT LIKE '%{{HORSE.REGISTERED_NAME}}%'
    ) THEN
      CONTINUE;
    END IF;

    -- OWNER is the sole party/signer; coverage of FHE + any active-term lessee is
    -- a standing clause in the body, not a named party.
    SELECT gd.document_id INTO v_doc FROM generate_document(
      v_owner, v_tpl, p_contract_id, p_horse_id,
      jsonb_build_array(jsonb_build_object(
        'contact_id', v_owner, 'role', 'CLIENT', 'is_signer', true, 'signer_order', 1)),
      'horse'::text) gd;

    v_seq := CASE WHEN p_contract_id IS NULL THEN NULL
                  WHEN v_tpl = 'HORSE_EMERGENCY_VET' THEN 2
                  WHEN v_tpl = 'RELEASE_HORSE_CARE'  THEN 3 END;
    UPDATE documents SET status = 'AWAITING_SIGNATURE', sign_sequence = v_seq
      WHERE id = v_doc AND status = 'DRAFT';
    v_gen := v_gen || jsonb_build_object('template_key', v_tpl, 'document_id', v_doc);
  END LOOP;

  IF p_contract_id IS NOT NULL THEN
    UPDATE documents d SET sign_sequence = 1
      FROM contract_templates t
     WHERE d.template_id = t.id AND is_horse_lease_template(t.template_key)
       AND d.contract_id = p_contract_id AND d.deleted_at IS NULL
       AND d.sign_sequence IS DISTINCT FROM 1;
  END IF;

  RETURN jsonb_build_object('owner_contact_id', v_owner, 'generated', v_gen, 'voided', v_voided);
END;
$$;


--
-- Name: ensure_my_member_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_my_member_access() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid;
  v_status  text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;

  SELECT status INTO v_status FROM members WHERE user_id = auth.uid();
  IF v_status = 'active' THEN RETURN true; END IF;

  -- D8: any org-attached account holds community access. Resolve the org from
  -- the profile first, falling back to the contact's client record.
  SELECT p.org_id INTO v_org FROM profiles p WHERE p.user_id = auth.uid();
  IF v_org IS NULL THEN
    SELECT cl.org_id INTO v_org FROM clients cl
     WHERE cl.contact_id = current_contact_id() AND cl.deleted_at IS NULL
     ORDER BY cl.created_at DESC LIMIT 1;
  END IF;
  IF v_org IS NULL THEN RETURN false; END IF;

  IF v_status IS NULL THEN
    INSERT INTO members (user_id, status, org_id)
      VALUES (auth.uid(), 'active', v_org)
      ON CONFLICT (user_id) DO UPDATE SET status = 'active';
    RETURN true;
  ELSIF v_status = 'paused' THEN
    UPDATE members SET status = 'active' WHERE user_id = auth.uid();
    RETURN true;
  END IF;
  RETURN false;
END;
$$;


--
-- Name: ensure_my_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_my_membership() RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT public.ensure_my_member_access(); $$;


--
-- Name: FUNCTION ensure_my_membership(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_my_membership() IS 'Self-heal for provisioned clients whose invitation token was lost/consumed: grants (or reactivates a paused) community membership when the caller''s contact has a live client row. Cancelled/suspended memberships are never overridden.';


--
-- Name: ensure_staff_profile(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_staff_profile(p_user_id uuid, p_title text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile profiles%ROWTYPE;
BEGIN
  SELECT * INTO v_profile FROM profiles WHERE user_id = p_user_id;
  IF NOT FOUND OR v_profile.org_id IS NULL THEN RETURN; END IF;
  IF NOT (v_profile.role IN ('ADMIN','MANAGER','EMPLOYEE','SUPER_ADMIN') OR v_profile.is_admin) THEN RETURN; END IF;
  PERFORM set_config('app.allow_profile_link', '1', true);
  UPDATE profiles
     SET title = coalesce(p_title, title),
         staff_active = true
   WHERE user_id = p_user_id;
END;
$$;


--
-- Name: entity_status_log(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_status_log(p_entity_type text, p_entity_id uuid) RETURNS TABLE(status text, display_name text, is_true_status boolean, is_terminal boolean, detail text, actor_user_id uuid, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.status, v.display_name, v.is_true_status, v.is_terminal, e.detail, e.actor_user_id, e.created_at
    FROM status_events e
    JOIN status_events_vocab v ON v.entity_type = e.entity_type AND v.code = e.status
   WHERE e.entity_type = p_entity_type AND e.entity_id = p_entity_id
     AND has_staff_access() AND e.org_id = current_org()
   ORDER BY e.created_at DESC;
$$;


--
-- Name: expand_horse_blocks(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expand_horse_blocks(p_body text, p_horse_ids uuid[]) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lines   text[];
  v_out     text[] := '{}';
  v_run     text[] := '{}';
  v_line    text;
  v_i       integer;
  v_n       integer := coalesce(array_length(p_horse_ids, 1), 0);
  v_h       integer;
  v_horse   horses%ROWTYPE;
  v_copy    text;
  v_runline text;
  v_tok     text;
  v_toks    text[];
BEGIN
  IF p_body IS NULL THEN RETURN NULL; END IF;

  -- No horses bound: hand the body back untouched. generate_document's existing
  -- token loop then blanks the HORSE.* tokens exactly as it does today, so the
  -- "no horse named" document is unchanged.
  IF v_n = 0 THEN RETURN p_body; END IF;

  v_lines := string_to_array(p_body, E'\n');

  -- Local helper as an inline block: flush the accumulated run into v_out.
  -- (Written out longhand because plpgsql has no nested functions.)
  FOR v_i IN 1 .. coalesce(array_length(v_lines, 1), 0) LOOP
    v_line := v_lines[v_i];

    IF v_line ~ '\{\{HORSE\.[A-Z0-9_]+\}\}' THEN
      v_run := v_run || v_line;
      CONTINUE;
    END IF;

    -- non-horse line: flush any pending run first
    IF coalesce(array_length(v_run, 1), 0) > 0 THEN
      FOR v_h IN 1 .. v_n LOOP
        SELECT * INTO v_horse FROM horses WHERE id = p_horse_ids[v_h];
        -- caption + blank-line separator ONLY when there is more than one horse,
        -- so the single-horse body is byte-identical to the pre-change output.
        IF v_n > 1 THEN
          -- ''::text, not '': bare '' concatenated to a text[] is read as an
          -- array literal and raises "malformed array literal".
          IF v_h > 1 THEN v_out := v_out || ''::text; END IF;
          v_out := v_out || horse_block_caption(v_horse, v_h);
        END IF;
        FOREACH v_runline IN ARRAY v_run LOOP
          v_copy := v_runline;
          v_toks := ARRAY(SELECT (regexp_matches(v_copy, '\{\{(HORSE\.[A-Z0-9_]+)\}\}', 'g'))[1]);
          FOREACH v_tok IN ARRAY v_toks LOOP
            v_copy := replace(v_copy, '{{' || v_tok || '}}',
              coalesce(horse_field_token_value(v_horse, split_part(v_tok, '.', 2)), ''));
          END LOOP;
          v_out := v_out || v_copy;
        END LOOP;
      END LOOP;
      v_run := '{}';
    END IF;

    v_out := v_out || v_line;
  END LOOP;

  -- trailing run (a body ending on horse lines)
  IF coalesce(array_length(v_run, 1), 0) > 0 THEN
    FOR v_h IN 1 .. v_n LOOP
      SELECT * INTO v_horse FROM horses WHERE id = p_horse_ids[v_h];
      IF v_n > 1 THEN
        IF v_h > 1 THEN v_out := v_out || ''::text; END IF;
        v_out := v_out || horse_block_caption(v_horse, v_h);
      END IF;
      FOREACH v_runline IN ARRAY v_run LOOP
        v_copy := v_runline;
        v_toks := ARRAY(SELECT (regexp_matches(v_copy, '\{\{(HORSE\.[A-Z0-9_]+)\}\}', 'g'))[1]);
        FOREACH v_tok IN ARRAY v_toks LOOP
          v_copy := replace(v_copy, '{{' || v_tok || '}}',
            coalesce(horse_field_token_value(v_horse, split_part(v_tok, '.', 2)), ''));
        END LOOP;
        v_out := v_out || v_copy;
      END LOOP;
    END LOOP;
  END IF;

  RETURN array_to_string(v_out, E'\n');
END;
$$;


--
-- Name: FUNCTION expand_horse_blocks(p_body text, p_horse_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.expand_horse_blocks(p_body text, p_horse_ids uuid[]) IS 'Expand each contiguous run of HORSE.*-token lines into one filled copy per bound horse. One horse in = byte-identical to single-horse substitution.';


--
-- Name: feed_get(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_get(p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := current_org();
  v_shape text;
  v_posts jsonb;
  v_items jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT shape::text INTO v_shape FROM feed_view_pref WHERE user_id = v_uid;
  v_shape := coalesce(v_shape, 'blended');

  SELECT coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_posts FROM (
    SELECT p.id, p.post_type, p.media_url, p.media_kind, p.body, p.source_link,
           p.subject_horse_id, p.visibility, p.publish_at, p.as_company,
           p.author_id,
           ap.author_name,
           ap.author_avatar,
           coalesce(ap.author_is_company, false) AS author_is_company,
           (s.user_id IS NOT NULL) AS seen,
           sh.from_name AS shared_by
      FROM feed_posts p
      LEFT JOIN feed_seen s ON s.post_id = p.id AND s.user_id = v_uid
      LEFT JOIN LATERAL (
        SELECT
          CASE WHEN p.as_company
            THEN coalesce(
                   nullif(btrim((SELECT value_text FROM config_values
                                  WHERE org_id = p.org_id AND namespace = 'BRAND' AND key = 'NAME')), ''),
                   'French Heritage Equestrian')
            ELSE coalesce(nullif(btrim(pr.display_name), ''),
                          nullif(btrim(coalesce(pr.first_name,'') || ' ' || coalesce(pr.last_name,'')), ''),
                          'Member')
          END AS author_name,
          -- a company post shows the brand mark; a personal post keeps the avatar
          CASE WHEN p.as_company THEN NULL ELSE pr.avatar_url END AS author_avatar,
          p.as_company AS author_is_company
          FROM profiles pr
         WHERE pr.user_id = p.author_id
        LIMIT 1
      ) ap ON true
      LEFT JOIN LATERAL (
        SELECT trim(coalesce(pr.first_name,'') || ' ' || coalesce(pr.last_name,'')) AS from_name
          FROM feed_shares fsh
          JOIN contacts pr ON pr.id = (SELECT contact_id FROM profiles WHERE user_id = fsh.from_user_id)
         WHERE fsh.post_id = p.id AND fsh.to_user_id = v_uid
         ORDER BY fsh.created_at DESC LIMIT 1
      ) sh ON true
     WHERE p.org_id = v_org
       AND p.published AND p.publish_at <= now() AND NOT p.pulled_down AND p.scan_state = 'clean'
       AND (p_before IS NULL OR p.publish_at < p_before)
       AND (
         p.visibility IN ('members','both')  -- authed member sees member+both
         OR EXISTS (SELECT 1 FROM feed_shares fsh WHERE fsh.post_id = p.id AND fsh.to_user_id = v_uid)
       )
     ORDER BY p.publish_at DESC
     LIMIT p_limit
  ) t;

  SELECT coalesce(jsonb_agg(row_to_json(a)), '[]'::jsonb) INTO v_items FROM (
    SELECT id, kind, title, body, payload, resolved, publish_at
      FROM feed_account_items
     WHERE user_id = v_uid AND publish_at <= now() AND NOT resolved
     ORDER BY publish_at DESC
  ) a;

  RETURN jsonb_build_object('shape', v_shape, 'posts', v_posts, 'account_items', v_items);
END;
$$;


--
-- Name: feed_mark_seen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_mark_seen(p_post_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO feed_seen (user_id, post_id) VALUES (auth.uid(), p_post_id)
  ON CONFLICT (user_id, post_id) DO NOTHING;
$$;


--
-- Name: feed_moderate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_moderate(p_post_id uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_action = 'approve' THEN
    UPDATE feed_posts SET scan_state='clean', published=true, pulled_down=false, updated_at=now() WHERE id=p_post_id;
  ELSIF p_action = 'affirm' THEN
    UPDATE feed_posts SET scan_state='blocked', published=false, updated_at=now() WHERE id=p_post_id;
  ELSIF p_action = 'pull_down' THEN
    UPDATE feed_posts SET pulled_down=true, updated_at=now() WHERE id=p_post_id;
  ELSE RAISE EXCEPTION 'unknown moderation action: %', p_action;
  END IF;
END;
$$;


--
-- Name: feed_my_posts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_my_posts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC), '[]'::jsonb)
  FROM (
    SELECT p.id, p.post_type, p.media_url, p.media_kind, p.body, p.source_link,
           p.visibility, p.as_company, p.published, p.publish_at, p.pulled_down,
           p.created_at, p.updated_at
      FROM feed_posts p
     WHERE p.author_id = auth.uid()
  ) t;
$$;


--
-- Name: feed_post_create(public.feed_post_type, text, public.feed_media_kind, text, text, uuid, boolean, public.feed_visibility, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_post_create(p_type public.feed_post_type, p_media_url text, p_media_kind public.feed_media_kind, p_body text DEFAULT NULL::text, p_source_link text DEFAULT NULL::text, p_subject_horse_id uuid DEFAULT NULL::uuid, p_as_company boolean DEFAULT false, p_visibility public.feed_visibility DEFAULT 'members'::public.feed_visibility, p_publish_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_org uuid := current_org(); v_scan feed_scan_state;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  -- only operators may post as the company
  IF p_as_company AND NOT is_admin() THEN RAISE EXCEPTION 'only operators may post as the company'; END IF;
  -- H.9 LISTING ELIGIBILITY: a horse-record-backed post may only be created by
  -- someone entitled to list that horse (owner; lessee only with sublease rights;
  -- staff unrestricted). Enforced server-side, not just in the picker.
  -- Listing integrity: a horse/gear LISTING must be backed by a horse the poster
  -- may list. Without this, a NULL subject skips the eligibility check entirely.
  IF p_type IN ('horse','gear') AND p_subject_horse_id IS NULL THEN
    RAISE EXCEPTION 'a horse or gear listing must reference a horse you are entitled to list';
  END IF;
  IF p_subject_horse_id IS NOT NULL
     AND NOT (can_list_horse(p_subject_horse_id, 'sale')
              OR can_list_horse(p_subject_horse_id, 'lease')) THEN
    RAISE EXCEPTION 'you are not authorized to list this horse';
  END IF;
  -- MODERATION SEAM: run the scan (returns clean at launch; NudeNet/vision later).
  v_scan := feed_scan_media(p_media_url, p_media_kind);
  INSERT INTO feed_posts (org_id, author_id, as_company, post_type, media_url, media_kind,
                          body, source_link, subject_horse_id, visibility, scan_state,
                          published, publish_at)
    VALUES (v_org, auth.uid(), p_as_company, p_type, p_media_url, p_media_kind,
            p_body, p_source_link, p_subject_horse_id, p_visibility, v_scan,
            v_scan = 'clean',                       -- clean posts go live; blocked stay unpublished
            coalesce(p_publish_at, now()))
    RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: feed_post_delete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_post_delete(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_author uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT author_id INTO v_author FROM feed_posts WHERE id = p_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_author <> auth.uid() AND NOT is_admin() THEN
    RAISE EXCEPTION 'not your post';
  END IF;

  DELETE FROM feed_posts WHERE id = p_id;
  RETURN true;
END;
$$;


--
-- Name: feed_post_update(uuid, text, text, public.feed_visibility); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_post_update(p_id uuid, p_body text DEFAULT NULL::text, p_source_link text DEFAULT NULL::text, p_visibility public.feed_visibility DEFAULT NULL::public.feed_visibility) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_author uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT author_id INTO v_author FROM feed_posts WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'post not found'; END IF;
  IF v_author <> auth.uid() AND NOT is_admin() THEN
    RAISE EXCEPTION 'not your post';
  END IF;

  UPDATE feed_posts SET
    body        = nullif(btrim(coalesce(p_body, body)), ''),
    source_link = nullif(btrim(coalesce(p_source_link, source_link)), ''),
    visibility  = coalesce(p_visibility, visibility),
    updated_at  = now()
   WHERE id = p_id;
  RETURN true;
END;
$$;


--
-- Name: feed_report_post(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_report_post(p_post_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE feed_posts SET scan_state = 'disputed', reported_reason = p_reason, updated_at = now()
   WHERE id = p_post_id AND author_id = auth.uid() AND scan_state = 'blocked';
END;
$$;


--
-- Name: feed_scan_media(text, public.feed_media_kind); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_scan_media(p_media_url text, p_media_kind public.feed_media_kind) RETURNS public.feed_scan_state
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 'clean'::feed_scan_state $$;


--
-- Name: feed_seed_welcome(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_seed_welcome() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := current_org();
  v_pu  purchases%ROWTYPE;
  v_has boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;

  SELECT EXISTS (SELECT 1 FROM feed_account_items WHERE user_id = v_uid AND kind = 'welcome') INTO v_has;
  IF v_has THEN RETURN; END IF;

  INSERT INTO feed_account_items (org_id, user_id, kind, title, body, payload)
    VALUES (v_org, v_uid, 'welcome', 'Welcome to your feed',
      'This is your home — new horses, gear, and moments from the barn land here. Choose how you''d like to see it; you can change it anytime.',
      jsonb_build_object('chooser', true));

  INSERT INTO feed_account_items (org_id, user_id, kind, title, body, payload)
    VALUES (v_org, v_uid, 'orientation', 'Getting around',
      'Tap the horse to Ask about it, Share a post with another rider, or start a service. Your library, schedule, and account live in the menu under your avatar.',
      '{}'::jsonb);

  -- tailored purchase card from the caller's latest spine purchase
  SELECT pu.* INTO v_pu
    FROM purchases pu
    JOIN profiles p ON p.contact_id = pu.buyer_contact_id
   WHERE p.user_id = v_uid AND pu.deleted_at IS NULL
   ORDER BY pu.created_at DESC LIMIT 1;
  IF FOUND THEN
    INSERT INTO feed_account_items (org_id, user_id, kind, title, body, payload)
      VALUES (v_org, v_uid, 'purchase_card',
        coalesce((SELECT pi.label FROM purchase_items pi WHERE pi.purchase_id = v_pu.id ORDER BY pi.created_at DESC LIMIT 1), 'Your booking'),
        CASE WHEN v_pu.payment_status = 'paid' THEN 'You''re all set. Here''s what to know before your first session.'
             ELSE 'Almost there — complete payment to confirm. Here''s what to know before your first session.' END,
        jsonb_build_object('purchase_id', v_pu.id, 'paid', v_pu.payment_status = 'paid'));
  END IF;
END;
$$;


