--
-- Name: lease_edit_guard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_edit_guard(p_document_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_ws text;
BEGIN
  SELECT org_id, workflow_state INTO v_org, v_ws FROM documents WHERE id = p_document_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'document not found'; END IF;
  IF NOT (has_staff_access() OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to edit this lease';
  END IF;
  IF v_ws = 'executed' THEN RAISE EXCEPTION 'the lease is executed and cannot be changed'; END IF;
  RETURN v_org;
END;
$$;


--
-- Name: lease_expiry_nudge(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_expiry_nudge(p_days_ahead integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN lease_reminder_sweep();
END;
$$;


--
-- Name: lease_participants_for_doc(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_participants_for_doc(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (has_staff_access() OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'contact_id', lp.contact_id,
        'name', trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')),
        'days_used', lp.days_used, 'hours', lp.hours,
        'usage_pct', lp.usage_pct, 'payment_pct', lp.payment_pct) ORDER BY lp.created_at), '[]'::jsonb)
    FROM lease_participants lp JOIN contacts c ON c.id = lp.contact_id
    WHERE lp.document_id = p_document_id);
END;
$$;


--
-- Name: lease_payment_options_for_doc(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_payment_options_for_doc(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (has_staff_access() OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'amount', amount, 'describe', describe) ORDER BY created_at), '[]'::jsonb)
    FROM lease_payment_options WHERE document_id = p_document_id);
END;
$$;


--
-- Name: lease_reminder_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_reminder_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d record;
  u uuid;
  v_kind text; v_title text; v_body text; v_link text; v_window interval;
  v_n int := 0;
BEGIN
  -- every executed lease with a start (â¤7d) or expiry (â¤30d) coming up
  FOR d IN
    SELECT dc.id AS doc_id, dc.org_id,
           coalesce(h.nickname, h.registered_name, 'the horse') AS hname,
           h.lease_start, h.lease_end
    FROM documents dc
    JOIN contract_templates t ON t.id = dc.template_id
    JOIN horses h ON h.id = dc.horse_id
    WHERE is_horse_lease_template(t.template_key) AND dc.status = 'EXECUTED'
      AND dc.deleted_at IS NULL AND h.deleted_at IS NULL
      AND (
        (h.lease_start IS NOT NULL AND h.lease_start BETWEEN current_date AND current_date + 7)
        OR (h.lease_end IS NOT NULL AND h.lease_end BETWEEN current_date AND current_date + 30)
      )
  LOOP
    IF d.lease_start IS NOT NULL AND d.lease_start BETWEEN current_date AND current_date + 7 THEN
      v_kind := 'lease_start'; v_window := interval '3 days';
      v_title := 'Lease start approaching';
      v_body := d.hname || ' â lease starts ' || to_char(d.lease_start, 'FMMonth FMDD') || '.';
    ELSE
      v_kind := 'lease_expiry'; v_window := interval '7 days';
      v_title := 'Lease expiring soon';
      v_body := d.hname || ' â lease ends ' || to_char(d.lease_end, 'FMMonth FMDD, YYYY') || '.';
    END IF;
    v_link := '/app/contracts/' || d.doc_id;

    -- recipients: every party of the lease + all staff/admin in the org
    FOR u IN
      SELECT pr.user_id
        FROM document_parties dp JOIN profiles pr ON pr.contact_id = dp.contact_id
       WHERE dp.document_id = d.doc_id AND pr.user_id IS NOT NULL
      UNION
      SELECT pr2.user_id FROM profiles pr2
       WHERE pr2.org_id = d.org_id
         AND coalesce(pr2.role,'USER') IN ('SUPER_ADMIN','ADMIN','MANAGER','EMPLOYEE')
         AND pr2.user_id IS NOT NULL
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.user_id = u AND n.kind = v_kind AND n.link = v_link
          AND n.created_at > now() - v_window
      ) THEN
        PERFORM notify_user(u, v_kind, v_title, v_body, v_link);
        v_n := v_n + 1;
      END IF;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('notifications_created', v_n);
END;
$$;


--
-- Name: lease_sublease_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_sublease_allowed(p_horse_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    coalesce((SELECT sublease_allowed FROM horses WHERE id = p_horse_id), false)
    OR coalesce((
      SELECT lower(btrim(cf.value)) IN ('true','yes','1','checked','on')
      FROM documents dc
      JOIN contract_templates t ON t.id = dc.template_id
      JOIN contract_fields cf ON cf.document_id = dc.id AND cf.field_key = 'TXN.SUBLEASE_ALLOWED'
      WHERE dc.horse_id = p_horse_id AND is_horse_lease_template(t.template_key)
        AND dc.status = 'EXECUTED' AND dc.deleted_at IS NULL
      ORDER BY dc.effective_date DESC NULLS LAST, dc.created_at DESC
      LIMIT 1
    ), false)
$$;


--
-- Name: line_item_hold_expired(public.line_item_state, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.line_item_hold_expired(p_state public.line_item_state, p_hold_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_state = 'approved_awaiting_claim'
     AND p_hold_expires_at IS NOT NULL
     AND p_hold_expires_at < now();
$$;


--
-- Name: link_contract_to_purchase(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_contract_to_purchase(p_contract_id uuid, p_purchase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_buyer uuid;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM contracts WHERE id = p_contract_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'contract not found';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM purchases WHERE id = p_purchase_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'purchase not found';
  END IF;
  SELECT buyer_contact_id INTO v_buyer FROM purchases WHERE id = p_purchase_id;
  UPDATE contracts
     SET purchase_id = p_purchase_id,
         originator_contact_id = coalesce(originator_contact_id, current_contact_id())
   WHERE id = p_contract_id;
END;
$$;


--
-- Name: list_deals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_deals() RETURNS TABLE(id uuid, display_code text, deal_type text, status text, created_at timestamp with time zone, party_summary text, horse_summary text, document_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d.id, d.display_code, d.deal_type, d.status, d.created_at,
    (SELECT string_agg(DISTINCT coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email), ', ')
       FROM contract_parties cp JOIN contacts c ON c.id = cp.contact_id
      WHERE cp.contract_id = d.contract_id),
    (SELECT string_agg(DISTINCT coalesce(nullif(h.registered_name,''), h.nickname), ', ')
       FROM deal_consideration dc JOIN horses h ON h.id = dc.horse_id
      WHERE dc.deal_id = d.id AND dc.kind = 'HORSE'),
    (SELECT count(*) FROM documents doc
      WHERE doc.contract_id = d.contract_id AND doc.deleted_at IS NULL)
  FROM deals d
  WHERE d.deleted_at IS NULL
    AND ((has_staff_access() AND d.org_id = current_org())
      OR EXISTS (SELECT 1 FROM contract_parties cp
                  WHERE cp.contract_id = d.contract_id AND cp.contact_id = current_contact_id()))
  ORDER BY d.created_at DESC;
$$;


--
-- Name: list_service_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_service_types() RETURNS TABLE(code text, display_name text, description text, segment text, requires_horse boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT st.code, st.display_name, st.description, st.segment, st.requires_horse
  FROM service_types st
  WHERE st.active AND st.code <> 'ONBOARDING' AND has_staff_access()
  ORDER BY st.sort_order, st.display_name
$$;


--
-- Name: location_full_label(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_full_label(p_location_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    nullif(btrim(CASE
      -- structured address present: always "name — street, city, ST postal"
      WHEN nullif(compose_address(l.address_line1, NULL, l.city, l.state, l.postal), '') IS NOT NULL
        THEN concat_ws(' — ', nullif(btrim(l.name), ''),
                       compose_address(l.address_line1, NULL, l.city, l.state, l.postal))
      -- freeform address that already leads with the name: use it as-is
      WHEN nullif(btrim(l.address), '') IS NOT NULL
       AND lower(btrim(l.address)) LIKE lower(btrim(l.name)) || '%'
        THEN btrim(l.address)
      -- freeform address that does not name the facility: compose both
      WHEN nullif(btrim(l.address), '') IS NOT NULL
        THEN concat_ws(' — ', nullif(btrim(l.name), ''), btrim(l.address))
      ELSE btrim(coalesce(l.name, ''))
    END), ''),
    ''
  )
  FROM locations l WHERE l.id = p_location_id
$$;


--
-- Name: FUNCTION location_full_label(p_location_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.location_full_label(p_location_id uuid) IS 'U2.5: a facility name plus its address. "FHE Main Barn Stall 12" is not an address on a legal instrument.';


--
-- Name: lock_and_sign_contract(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_and_sign_contract(p_document_id uuid, p_party_role text, p_typed_name text, p_esign_consent boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state text; v_open int; v_missing int;
  v_horse_confirmed timestamptz; v_needs_horse boolean; v_signed boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT workflow_state, horse_section_confirmed_at INTO v_state, v_horse_confirmed
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF v_state NOT IN ('locked','editable','executed') THEN
    RAISE EXCEPTION 'document is not ready to sign (workflow_state=%); lock it first', v_state;
  END IF;
  IF v_state IN ('editable') THEN
    SELECT count(*) INTO v_open FROM contract_change_requests
      WHERE document_id = p_document_id
        AND parent_request_id IS NULL AND submitted_at IS NOT NULL AND resolved_at IS NULL;
    IF v_open > 0 THEN
      RAISE EXCEPTION 'cannot sign: % open change request(s) remain; resolve or lock first', v_open;
    END IF;
    SELECT count(*) INTO v_missing FROM contract_fields
      WHERE document_id = p_document_id AND required
        AND nullif(trim(coalesce(value, '')), '') IS NULL;
    IF v_missing > 0 THEN
      RAISE EXCEPTION 'cannot sign: % required field(s) still empty', v_missing;
    END IF;
    IF EXISTS (
      SELECT 1 FROM contract_fields cf
        JOIN documents d2 ON d2.id = cf.document_id
        JOIN contract_parties cp2 ON cp2.contract_id = d2.contract_id AND cp2.party_role = 'LESSEE'
        JOIN contacts c2 ON c2.id = cp2.contact_id
       WHERE cf.document_id = p_document_id AND cf.field_key = 'LESSEE.PARTY_TYPE'
         AND ((cf.value = 'INDIVIDUAL' AND coalesce(c2.is_company,false))
           OR (cf.value = 'ENTITY' AND NOT coalesce(c2.is_company,false)))
    ) THEN
      RAISE EXCEPTION 'cannot sign: LESSEE.PARTY_TYPE contradicts the Lessee party record (person vs company) — correct the field or the contact record';
    END IF;
    v_needs_horse := EXISTS (
      SELECT 1 FROM contract_fields
      WHERE document_id = p_document_id
        AND owner_role = 'LESSOR' AND field_key LIKE 'HORSE.%');
    IF v_needs_horse AND v_horse_confirmed IS NULL THEN
      RAISE EXCEPTION 'cannot sign: the horse information has not been confirmed by the Lessor';
    END IF;
    SELECT EXISTS (SELECT 1 FROM signatures
                   WHERE document_id = p_document_id AND deleted_at IS NULL
                     AND signed_at IS NOT NULL) INTO v_signed;
    IF NOT v_signed THEN
      PERFORM remerge_contract_from_fields(p_document_id);
    END IF;
  END IF;

  RETURN record_signature(p_document_id, p_party_role, p_typed_name, NULL, NULL,
                          coalesce(p_esign_consent, false));
END;
$$;


--
-- Name: FUNCTION lock_and_sign_contract(p_document_id uuid, p_party_role text, p_typed_name text, p_esign_consent boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lock_and_sign_contract(p_document_id uuid, p_party_role text, p_typed_name text, p_esign_consent boolean) IS 'Thin bridge to the reused signing engine: asserts the document is ready to sign (workflow_state locked, or editable with no open change requests — the owner''s "last to approve signs first" rule) then delegates to record_signature v6, which seals/hashes/EXECUTED-flips (and sets workflow_state=''executed'') once all signer parties have signed. Never reimplements signing.';


--
-- Name: log_contract_change(uuid, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_contract_change(p_document_id uuid, p_change_kind text, p_field_key text DEFAULT NULL::text, p_field_label text DEFAULT NULL::text, p_owner_role text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid;
  v_label  text;
  v_roles  text[];
  v_staff  boolean;
  v_cid    uuid;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RETURN; END IF;   -- unknown/deleted doc: skip silently

  v_cid   := current_contact_id();
  v_staff := has_staff_access() AND v_org = current_org();
  BEGIN
    v_roles := ARRAY(SELECT r FROM caller_party_roles(p_document_id) r);
  EXCEPTION WHEN OTHERS THEN v_roles := '{}';
  END;
  SELECT nullif(trim(concat_ws(' ', first_name, last_name)), '')
    INTO v_label FROM contacts WHERE id = v_cid;

  INSERT INTO contract_change_log (
    org_id, document_id, change_kind, field_key, field_label, owner_role,
    old_value, new_value, detail, actor_contact_id, actor_label, actor_roles, actor_is_staff)
  VALUES (
    v_org, p_document_id, p_change_kind, p_field_key, p_field_label, p_owner_role,
    p_old_value, p_new_value, coalesce(p_detail,'{}'::jsonb),
    v_cid, coalesce(v_label, CASE WHEN v_staff THEN 'Staff' ELSE 'A party' END),
    coalesce(v_roles,'{}'), coalesce(v_staff,false));
EXCEPTION WHEN OTHERS THEN
  -- logging must never break a contract edit
  NULL;
END;
$$;


--
-- Name: log_evaluation_report_access(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_evaluation_report_access(p_report_id uuid, p_action text, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM evaluation_reports WHERE id = p_report_id;
  IF v_org IS NULL THEN RETURN; END IF;
  INSERT INTO evaluation_report_access (org_id, report_id, actor_user_id, action, detail)
    VALUES (v_org, p_report_id, auth.uid(), p_action, p_detail);
END;
$$;


--
-- Name: log_mirror_delivery(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_mirror_delivery(p_document_id uuid, p_channel text, p_copy_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- document_deliveries has no org_id column; the document carries the org.
  INSERT INTO document_deliveries (document_id, recipient_contact_id, channel, copy_url, is_mirror)
  VALUES (p_document_id, company_contact_id(), p_channel, p_copy_url, true)
  ON CONFLICT DO NOTHING;
END;
$$;


--
-- Name: log_receipt_send(uuid, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_receipt_send(p_purchase_id uuid, p_key text, p_recipient text, p_succeeded boolean, p_error text DEFAULT NULL::text, p_message_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM purchases WHERE id = p_purchase_id;
  INSERT INTO receipt_sends (org_id, purchase_id, idempotency_key, recipient_email,
                             succeeded, error, message_id)
  VALUES (v_org, p_purchase_id, p_key, p_recipient, p_succeeded, p_error, p_message_id)
  ON CONFLICT (idempotency_key) DO NOTHING;
END;
$$;


--
-- Name: log_status_event(text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_status_event(p_entity_type text, p_entity_id uuid, p_status text, p_detail text DEFAULT NULL::text, p_org uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := p_org;
  v_true boolean;
  v_id   uuid;
BEGIN
  -- validate vocab + true/sub classification
  SELECT is_true_status INTO v_true FROM status_events_vocab
   WHERE entity_type = p_entity_type AND code = p_status;
  IF v_true IS NULL THEN
    RAISE EXCEPTION 'unknown status % for entity %', p_status, p_entity_type;
  END IF;

  -- resolve org from the entity when not supplied
  IF v_org IS NULL THEN
    v_org := CASE p_entity_type
      WHEN 'document' THEN (SELECT org_id FROM documents   WHERE id = p_entity_id)
      WHEN 'order'    THEN (SELECT org_id FROM purchases   WHERE id = p_entity_id)
      WHEN 'offering' THEN (SELECT org_id FROM bookings    WHERE id = p_entity_id)
      WHEN 'account'  THEN (SELECT org_id FROM invitations WHERE id = p_entity_id)
    END;
  END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'could not resolve org for status event'; END IF;

  INSERT INTO status_events (org_id, entity_type, entity_id, status, detail, actor_user_id)
    VALUES (v_org, p_entity_type, p_entity_id, p_status, p_detail, auth.uid())
    RETURNING id INTO v_id;

  IF v_true THEN
    IF    p_entity_type = 'document' THEN UPDATE documents   SET current_status = p_status WHERE id = p_entity_id;
    ELSIF p_entity_type = 'order'    THEN UPDATE purchases   SET current_status = p_status WHERE id = p_entity_id;
    ELSIF p_entity_type = 'offering' THEN UPDATE bookings    SET current_status = p_status WHERE id = p_entity_id;
    ELSIF p_entity_type = 'account'  THEN UPDATE invitations SET current_status = p_status WHERE id = p_entity_id;
    END IF;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: mark_change_fee_paid(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_change_fee_paid(p_change_id uuid, p_paid boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  UPDATE booking_change_requests SET fee_paid = p_paid
   WHERE id = p_change_id AND org_id = current_org();
END;
$$;


--
-- Name: mark_change_request_seen(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_change_request_seen(p_request_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cid uuid; v_doc uuid; v_n int := 0; v_ins int; r record;
  v_role text; v_label text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF p_request_ids IS NULL OR array_length(p_request_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('seen', 0);
  END IF;

  v_cid := current_contact_id();
  IF v_cid IS NULL THEN RETURN jsonb_build_object('seen', 0); END IF;

  FOR r IN
    SELECT cr.id, cr.org_id, cr.document_id, cr.author_contact_id, cr.submitted_at
      FROM contract_change_requests cr
     WHERE cr.id = ANY(p_request_ids)
  LOOP
    -- authorisation, per document (a batch could in principle span documents)
    IF NOT ((has_staff_access() AND r.org_id = current_org())
            OR caller_is_document_party(r.document_id)) THEN
      CONTINUE;
    END IF;
    -- never self-seen: viewing your own entry must not freeze it
    IF r.author_contact_id = v_cid THEN CONTINUE; END IF;
    -- a draft is not visible to anyone else and cannot be "seen"
    IF r.submitted_at IS NULL THEN CONTINUE; END IF;

    IF v_doc IS DISTINCT FROM r.document_id THEN
      v_doc := r.document_id;
      SELECT role, label INTO v_role, v_label FROM comment_author_identity(v_doc);
    END IF;

    -- FIRST VIEW WINS — a later re-open never moves the stamp
    INSERT INTO contract_change_request_seen (request_id, contact_id, org_id, seen_role, seen_label)
    VALUES (r.id, v_cid, r.org_id, v_role, coalesce(v_label, 'A party'))
    ON CONFLICT (request_id, contact_id) DO NOTHING;

    GET DIAGNOSTICS v_ins = ROW_COUNT;
    v_n := v_n + v_ins;
  END LOOP;

  RETURN jsonb_build_object('seen', v_n);
END;
$$;


--
-- Name: mark_comment_review(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_comment_review(p_comment_id uuid, p_on boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT document_id INTO v_doc FROM contract_change_requests WHERE id = p_comment_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown comment'; END IF;
  IF NOT ((has_staff_access() AND (SELECT org_id FROM documents WHERE id=v_doc) = current_org())
          OR caller_is_document_party(v_doc)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;
  UPDATE contract_change_requests SET needs_review = coalesce(p_on,true), updated_at = now()
   WHERE id = p_comment_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: mark_comment_stale(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_comment_stale(p_comment_id uuid, p_stale boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_org uuid;
BEGIN
  SELECT document_id, org_id INTO v_doc, v_org FROM contract_change_requests WHERE id = p_comment_id;
  IF v_doc IS NULL THEN RETURN; END IF;
  IF NOT ((has_staff_access() AND v_org = current_org()) OR caller_is_document_party(v_doc)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;
  UPDATE contract_change_requests SET is_stale = p_stale, updated_at = now() WHERE id = p_comment_id;
END;
$$;


--
-- Name: mark_document_opened(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_document_opened(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_cid uuid; v_role text; v_label text; v_ins int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF NOT ((has_staff_access() AND v_org = current_org())
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  v_cid := current_contact_id();
  IF v_cid IS NULL THEN RETURN jsonb_build_object('opened', 0); END IF;

  SELECT role, label INTO v_role, v_label FROM comment_author_identity(p_document_id);

  -- FIRST OPEN WINS — a later visit never moves the stamp.
  INSERT INTO document_opened (document_id, contact_id, org_id, opened_role, opened_label)
  VALUES (p_document_id, v_cid, v_org, v_role, coalesce(v_label, 'A party'))
  ON CONFLICT (document_id, contact_id) DO NOTHING;
  GET DIAGNOSTICS v_ins = ROW_COUNT;

  RETURN jsonb_build_object('opened', v_ins);
END;
$$;


--
-- Name: mark_notification_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_read(p_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE notifications SET read_at = now()
    WHERE id = p_id AND user_id = auth.uid() AND read_at IS NULL
  RETURNING true
$$;


--
-- Name: FUNCTION mark_notification_read(p_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mark_notification_read(p_id uuid) IS 'Mark one of the CALLER''s notifications read (owner-only; someone else''s id is a silent no-op returning NULL).';


--
-- Name: mark_purchase_paid(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_purchase_paid(p_purchase_id uuid, p_amount numeric, p_reference text DEFAULT NULL::text, p_method text DEFAULT 'zelle'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur purchases%ROWTYPE;
  v_user  uuid;
  v_label text;
  v_paid  text;
BEGIN
  SELECT * INTO v_pur FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown purchase: %', p_purchase_id;
  END IF;
  IF v_pur.payment_status = 'paid' THEN
    RETURN 'already_paid';
  END IF;

  UPDATE purchases p
     SET payment_status    = 'paid',
         status            = 'paid',
         paid_at           = now(),
         amount_paid       = COALESCE(p.amount, 0),
         payment_method    = p_method,
         payment_reference = COALESCE(p.payment_reference, p_reference)
   WHERE p.id = p_purchase_id;

  -- U3: the payment-side producer. Every route (Stripe webhook, Zelle
  -- reconcile, manual mark-paid) converges on this function, so this fires
  -- exactly once per payment and cannot be duplicated per-route.
  SELECT string_agg(pi.label, ', ' ORDER BY pi.created_at) INTO v_label
    FROM purchase_items pi WHERE pi.purchase_id = p_purchase_id;
  v_label := coalesce(nullif(btrim(v_label), ''), 'Your order');
  v_paid  := fmt_money(coalesce(v_pur.amount, p_amount, 0));

  -- the standing "payment due" condition has ENDED — resolve both alerts.
  -- Kind-scoped (U1 item 5a) so nothing else on those links is disturbed.
  PERFORM resolve_notifications_for_link('/app/orders', NULL, 'purchase_unpaid');
  PERFORM resolve_notifications_for_link('/app/ops/payments/review', NULL, 'purchase_unpaid');

  SELECT pr.user_id INTO v_user
    FROM profiles pr WHERE pr.contact_id = v_pur.buyer_contact_id LIMIT 1;
  IF v_user IS NOT NULL THEN
    PERFORM notify_user(v_user, 'payment_received',
      'Payment received — ' || v_label,
      'We received your payment of ' || v_paid || '. Thank you.',
      '/app/orders');
  END IF;

  PERFORM notify_staff(v_pur.org_id, 'payment_received',
    'Payment received — ' || v_label || ' (' || v_paid || ')',
    '/app/ops/payments/review');

  RETURN 'paid';
END;
$$;


--
-- Name: mark_tour_seen(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_tour_seen(p_form_factor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN; END IF;
  -- app.allow_profile_link lets this pass the role guard: the member is
  -- writing their own presentational marker, not an identity/employment field.
  PERFORM set_config('app.allow_profile_link', '1', true);
  IF p_form_factor = 'mobile' THEN
    UPDATE profiles
       SET tour_seen_mobile_at = coalesce(tour_seen_mobile_at, now()),
           tour_seen_at        = coalesce(tour_seen_at, now())
     WHERE user_id = auth.uid();
  ELSE
    UPDATE profiles
       SET tour_seen_desktop_at = coalesce(tour_seen_desktop_at, now()),
           tour_seen_at         = coalesce(tour_seen_at, now())
     WHERE user_id = auth.uid();
  END IF;
END;
$$;


--
-- Name: med_party_who(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.med_party_who(p_party text, p_note text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN upper(coalesce(p_party,'')) = 'OTHER'
              THEN coalesce(nullif(btrim(p_note),''), 'Other')
              ELSE party_label(p_party) END;
$$;


--
-- Name: member_display_name(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.member_display_name(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    nullif(btrim(coalesce(first_name,'')), ''),
    nullif(btrim(coalesce(display_name,'')), ''),
    'A member'
  ) FROM profiles WHERE user_id = p_user_id;
$$;


--
-- Name: member_horses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.member_horses(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'name', coalesce(nullif(btrim(h.nickname),''), h.registered_name),
      'home_location', (SELECT name FROM locations WHERE id = h.home_location_id))
      ORDER BY h.created_at), '[]'::jsonb)
  FROM horses h
  JOIN profiles p ON p.contact_id = h.current_owner_contact_id
  WHERE p.user_id = p_user_id AND h.deleted_at IS NULL;
$$;


--
-- Name: members_post_join_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.members_post_join_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'active' THEN RETURN NEW; END IF;

  v_org := coalesce(NEW.org_id, (SELECT org_id FROM profiles WHERE user_id = NEW.user_id));
  IF v_org IS NULL THEN RETURN NEW; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM feed_posts
    WHERE author_id = NEW.user_id AND post_type = 'member_joined'
  ) THEN
    INSERT INTO feed_posts (org_id, author_id, post_type, body, visibility, published)
    VALUES (v_org, NEW.user_id, 'member_joined',
            member_display_name(NEW.user_id) || ' just joined the community.',
            'members', true);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: mirror_admin_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_admin_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- only mirror org/client events, and only when the recipient is themselves an
  -- admin/owner (so client-facing alerts to clients are never copied to staff).
  IF notification_is_personal(NEW.kind) THEN RETURN NEW; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles p
     WHERE p.user_id = NEW.user_id AND p.org_id = NEW.org_id
       AND coalesce(p.role,'USER') IN ('ADMIN','MANAGER','EMPLOYEE','OWNER','SUPERADMIN')
  ) THEN RETURN NEW; END IF;

  -- fan out to every OTHER admin/owner in the org, skipping any who already have
  -- this exact alert (keeps it idempotent and prevents trigger recursion loops).
  INSERT INTO notifications (org_id, user_id, kind, title, body, link)
  SELECT NEW.org_id, p.user_id, NEW.kind, NEW.title, NEW.body, NEW.link
    FROM profiles p
   WHERE p.org_id = NEW.org_id
     AND p.user_id <> NEW.user_id
     AND coalesce(p.role,'USER') IN ('ADMIN','MANAGER','EMPLOYEE','OWNER','SUPERADMIN')
     AND NOT EXISTS (
       SELECT 1 FROM notifications n2
        WHERE n2.user_id = p.user_id AND n2.org_id = NEW.org_id
          AND n2.kind = NEW.kind
          AND coalesce(n2.link,'') = coalesce(NEW.link,'')
          AND n2.created_at > now() - interval '1 minute'
     );
  RETURN NEW;
END $$;


--
-- Name: money_numeric(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.money_numeric(p_raw text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_raw IS NULL THEN NULL
    WHEN btrim(regexp_replace(p_raw, '[^0-9.\-]', '', 'g')) IN ('', '-', '.', '-.') THEN NULL
    ELSE btrim(regexp_replace(p_raw, '[^0-9.\-]', '', 'g'))::numeric
  END
$$;


--
-- Name: FUNCTION money_numeric(p_raw text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.money_numeric(p_raw text) IS 'Extracts the numeric value from any money-shaped string. NULL when no number is present. Paired with fmt_money for render.';


--
-- Name: money_shape_violation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.money_shape_violation(p_format text, p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE v jsonb;
BEGIN
  IF p_value IS NULL OR btrim(p_value) = '' THEN RETURN NULL; END IF;  -- unset is always legal

  IF p_format = 'currency' THEN
    -- canonical: a bare numeric. '$45,000.00' and '1,200' are rejected so the
    -- symbol and separators can only ever come from fmt_money at render.
    IF btrim(p_value) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN RETURN NULL; END IF;
    RETURN format('currency fields store a bare number (e.g. 45000), not %L — the $ and separators are applied at render', p_value);

  ELSIF p_format = 'fee_schedule' THEN
    -- canonical: the {initial_due, initial_terms?, options[], selected} object.
    BEGIN
      v := p_value::jsonb;
    EXCEPTION WHEN OTHERS THEN
      RETURN format('fee_schedule fields store a JSON object, not %L — a bare amount or rendered prose is not a valid value', p_value);
    END;
    IF jsonb_typeof(v) <> 'object' THEN
      RETURN format('fee_schedule fields store a JSON object, not a %s', jsonb_typeof(v));
    END IF;
    -- a rendered-prose round-trip is the specific defect this guard exists for
    IF p_value ~ 'Initial payment due:' THEN
      RETURN 'that is rendered output, not a stored value — save the fee schedule, not its rendering';
    END IF;
    RETURN NULL;
  END IF;

  RETURN NULL;
END;
$_$;


--
-- Name: FUNCTION money_shape_violation(p_format text, p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.money_shape_violation(p_format text, p_value text) IS 'U2.1c door guard: NULL when a money value is canonical for its format_type, else the rejection reason.';


--
-- Name: my_acquisition_intake_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_acquisition_intake_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_pending jsonb;
BEGIN
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('pending', '[]'::jsonb, 'needs_intake', false);
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'purchase_item_id', pi.id,
           'offering_id', pi.offering_id,
           'label', pi.label,
           'config_kind', o.config_kind
         ) ORDER BY pu.created_at), '[]'::jsonb)
    INTO v_pending
    FROM purchases pu
    JOIN purchase_items pi ON pi.purchase_id = pu.id
    JOIN offerings o ON o.id = pi.offering_id
   WHERE (pu.buyer_contact_id = v_contact OR pu.buyer_user_id = auth.uid())
     AND coalesce(pu.status, '') <> 'void'
     AND pu.deleted_at IS NULL
     AND o.config_kind IN ('intake_finder', 'intake_evaluation')
     -- "not yet filled": no meaningful keys captured on the line config
     AND (pi.config IS NULL OR pi.config = '{}'::jsonb OR NOT (pi.config ? 'submitted_at'));

  RETURN jsonb_build_object(
    'pending', v_pending,
    'needs_intake', jsonb_array_length(v_pending) > 0);
END;
$$;


--
-- Name: my_contract_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_contract_documents() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me    uuid := current_contact_id();
  v_staff boolean := has_staff_access();
  v_org   uuid := current_org();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  IF v_staff AND v_org IS NOT NULL THEN
    RETURN coalesce((
      SELECT jsonb_agg(row_to_json(t) ORDER BY t.generated_at DESC)
      FROM (
        SELECT DISTINCT
          d.id AS document_id, d.title, d.status, d.workflow_state,
          d.recipient_editing, d.execution_hash, d.generated_at, d.sent_at,
          d.archived_at, d.voided_at, d.void_reason,
          (SELECT dpa.archived_at FROM document_party_archives dpa
            WHERE dpa.document_id = d.id AND dpa.contact_id = v_me) AS my_archived_at,
          (SELECT dph.hidden_at FROM document_party_hidden dph
            WHERE dph.document_id = d.id AND dph.contact_id = v_me) AS my_hidden_at,
          (d.originator_contact_id = v_me) AS is_originator,
          (SELECT string_agg(dp.party_role, ',' ORDER BY dp.party_role)
             FROM document_parties dp
            WHERE dp.document_id = d.id AND dp.contact_id = v_me) AS my_roles,
          (SELECT count(*) FROM contract_change_requests cr
            WHERE cr.document_id = d.id AND cr.parent_request_id IS NULL
              AND cr.submitted_at IS NOT NULL AND cr.resolved_at IS NULL) AS open_change_requests
        FROM documents d
        WHERE d.deleted_at IS NULL
          AND d.org_id = v_org
          AND EXISTS (SELECT 1 FROM contract_fields cf WHERE cf.document_id = d.id)
      ) t
    ), '[]'::jsonb);
  END IF;

  IF v_me IS NULL THEN RETURN '[]'::jsonb; END IF;

  RETURN coalesce((
    SELECT jsonb_agg(row_to_json(t) ORDER BY t.generated_at DESC)
    FROM (
      SELECT DISTINCT
        d.id AS document_id, d.title, d.status, d.workflow_state,
        d.recipient_editing, d.execution_hash, d.generated_at, d.sent_at,
        d.archived_at, d.voided_at, d.void_reason,
        (SELECT dpa.archived_at FROM document_party_archives dpa
          WHERE dpa.document_id = d.id AND dpa.contact_id = v_me) AS my_archived_at,
        NULL::timestamptz AS my_hidden_at,
        (d.originator_contact_id = v_me) AS is_originator,
        (SELECT string_agg(dp.party_role, ',' ORDER BY dp.party_role)
           FROM document_parties dp
          WHERE dp.document_id = d.id AND dp.contact_id = v_me) AS my_roles,
        (SELECT count(*) FROM contract_change_requests cr
          WHERE cr.document_id = d.id AND cr.parent_request_id IS NULL
            AND cr.submitted_at IS NOT NULL AND cr.resolved_at IS NULL) AS open_change_requests
      FROM documents d
      JOIN document_parties dp2 ON dp2.document_id = d.id
      WHERE d.deleted_at IS NULL
        AND dp2.contact_id = v_me
        AND EXISTS (SELECT 1 FROM contract_fields cf WHERE cf.document_id = d.id)
        AND NOT EXISTS (SELECT 1 FROM document_party_hidden dph
                         WHERE dph.document_id = d.id AND dph.contact_id = v_me)
    ) t
  ), '[]'::jsonb);
END;
$$;


--
-- Name: FUNCTION my_contract_documents(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_contract_documents() IS 'The caller''s contract documents (those carrying structured contract_fields where they are a party): document_id, title, status, workflow_state, recipient_editing, execution_hash, is_originator, my_roles (csv), open_change_requests. jsonb array, newest first. The list read model a UI binds to.';


--
-- Name: my_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_documents() RETURNS TABLE(document_id uuid, template_key text, title text, kind text, signed_at timestamp with time zone, current_status text, superseded boolean, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- pending (generated but unsigned)
  SELECT d.id, ct.template_key, ct.title, 'pending'::text,
         NULL::timestamptz, d.current_status, false, d.created_at
    FROM documents d JOIN contract_templates ct ON ct.id = d.template_id
   WHERE d.contact_id = current_contact_id() AND d.deleted_at IS NULL
     AND d.status <> 'EXECUTED' AND coalesce(d.current_status,'') <> 'void'
  UNION ALL
  -- assigned but not yet generated
  SELECT NULL::uuid, crd.template_key, ct.title, 'assigned'::text,
         NULL::timestamptz, 'assigned', false, now()
    FROM contact_required_documents crd
    JOIN contract_templates ct ON ct.template_key = crd.template_key AND ct.active AND ct.deleted_at IS NULL
     AND ct.version = (SELECT max(x.version) FROM contract_templates x
                        WHERE x.template_key = ct.template_key AND x.active AND x.deleted_at IS NULL)
   WHERE crd.contact_id = current_contact_id()
     AND NOT EXISTS (SELECT 1 FROM documents d JOIN contract_templates ct2 ON ct2.id = d.template_id
                      WHERE d.contact_id = crd.contact_id AND d.deleted_at IS NULL
                        AND ct2.template_key = crd.template_key
                        AND (d.status <> 'EXECUTED' OR (d.status = 'EXECUTED' AND coalesce(d.current_status,'') <> 'superseded')))
  UNION ALL
  -- executed, signing order (newest last → FE may reverse per page convention)
  SELECT d.id, ct.template_key, ct.title, 'executed'::text,
         (SELECT max(s.signed_at) FROM signatures s WHERE s.document_id = d.id AND s.deleted_at IS NULL),
         d.current_status, (d.current_status = 'superseded'), d.created_at
    FROM documents d JOIN contract_templates ct ON ct.id = d.template_id
   WHERE d.contact_id = current_contact_id() AND d.deleted_at IS NULL
     AND d.status = 'EXECUTED'
   ORDER BY 4 DESC, 8;
$$;


--
-- Name: my_evaluation_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_evaluation_reports() RETURNS TABLE(id uuid, title text, horse_label text, body text, delivered_at timestamp with time zone, available_until timestamp with time zone, is_shared boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT r.id, r.title, r.horse_label, r.body, r.delivered_at, r.available_until,
         (r.contact_id <> current_contact_id()) AS is_shared
    FROM evaluation_reports r
   WHERE r.deleted_at IS NULL
   ORDER BY r.delivered_at DESC NULLS LAST;
$$;


--
-- Name: my_fulfillment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_fulfillment() RETURNS TABLE(purchase_id uuid, label text, unit_kind text, total integer, open integer, consumed integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT u.purchase_id,
         coalesce(min(u.label), 'Purchase'),
         u.unit_kind,
         count(*)::int,
         count(*) FILTER (WHERE u.current_status IN ('open','scheduled'))::int,
         count(*) FILTER (WHERE u.current_status IN ('consumed','delivered'))::int
    FROM fulfillment_units u
    JOIN purchases p ON p.id = u.purchase_id
   WHERE u.deleted_at IS NULL
     AND (p.buyer_user_id = auth.uid() OR p.buyer_contact_id = current_contact_id())
   GROUP BY u.purchase_id, u.unit_kind;
$$;


--
-- Name: my_gifts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_gifts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(g ORDER BY g.created_at DESC), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'id', gf.id, 'code', gf.code, 'item_type', gf.item_type, 'item_label', gf.item_label,
      'amount', gf.amount, 'status', gf.status, 'gift_message', gf.gift_message,
      'buyer_name', gf.buyer_name, 'recipient_name', gf.recipient_name,
      'unlocked', gf.unlocked, 'opened_at', gf.opened_at, 'redeemed_at', gf.redeemed_at,
      'expires_at', gf.expires_at, 'created_at', gf.created_at,
      'direction', CASE WHEN gf.buyer_user_id = auth.uid() THEN 'given' ELSE 'received' END
    ) AS g, gf.created_at
    FROM gifts gf
    WHERE gf.buyer_user_id = auth.uid()
       OR gf.redeemed_user_id = auth.uid()
       OR lower(gf.recipient_email) = lower((SELECT email FROM auth.users WHERE id = auth.uid()))
  ) g;
$$;


--
-- Name: my_horse_onboarding_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_horse_onboarding_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_pending jsonb;
  v_care_unsigned boolean;
  v_care_purchase boolean;
  v_needs_horse boolean;
BEGIN
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('pending_horse_docs','[]'::jsonb,'needs_horse',false,'service_blocked',false);
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'document_id', d.id, 'template_key', t.template_key,
           'title', d.title, 'link', '/app/contracts/' || d.id) ORDER BY d.created_at), '[]'::jsonb)
    INTO v_pending
    FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
    JOIN contract_templates t ON t.id = d.template_id
    WHERE dp.contact_id = v_contact
      AND t.template_key IN ('HORSE_EMERGENCY_VET','RELEASE_HORSE_CARE')
      AND d.status <> 'EXECUTED'
      AND NOT EXISTS (SELECT 1 FROM signatures sg
                       WHERE sg.document_id = d.id AND sg.signer_contact_id = v_contact
                         AND sg.deleted_at IS NULL);

  SELECT EXISTS (
    SELECT 1 FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
    JOIN contract_templates t ON t.id = d.template_id
    WHERE dp.contact_id = v_contact AND t.template_key = 'RELEASE_HORSE_CARE'
      AND d.status <> 'EXECUTED'
  ) INTO v_care_unsigned;

  -- a non-cancelled horse (care) purchase by this buyer — contact OR user grain.
  SELECT EXISTS (
    SELECT 1 FROM purchases pu
    JOIN purchase_items pi ON pi.purchase_id = pu.id
    JOIN offerings o ON o.id = pi.offering_id
    WHERE (pu.buyer_contact_id = v_contact OR pu.buyer_user_id = auth.uid())
      AND o.segment = 'horse'
      AND coalesce(pu.status, '') <> 'cancelled'
  ) INTO v_care_purchase;

  -- has a paid care service but no booking yet carrying a horse (booking grain).
  SELECT v_care_purchase AND NOT EXISTS (
    SELECT 1 FROM bookings b
    WHERE b.client_id = current_client_id()
      AND b.kind = 'care' AND b.horse_id IS NOT NULL
      AND b.status NOT IN ('cancelled','available')
  ) INTO v_needs_horse;

  RETURN jsonb_build_object(
    'pending_horse_docs', v_pending,
    'needs_horse', v_needs_horse,
    'service_blocked', v_care_purchase AND v_care_unsigned
  );
END;
$$;


--
-- Name: my_lesson_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_lesson_progress() RETURNS TABLE(session_id uuid, starts_at timestamp with time zone, status text, location text, note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT b.id, b.starts_at, upper(b.status), b.location, b.notes
  FROM bookings b
  WHERE b.kind = 'lesson'
    AND b.client_id = current_client_id()
    AND b.notes IS NOT NULL
    AND btrim(b.notes) <> ''
  ORDER BY b.starts_at DESC
$$;


--
-- Name: my_lesson_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_lesson_reports() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(r ORDER BY r.starts_at DESC), '[]'::jsonb)
  FROM (
    SELECT
      b.starts_at,
      jsonb_build_object(
        'booking_id',   b.id,
        'starts_at',    b.starts_at,
        'ends_at',      b.ends_at,
        'status',       upper(b.status),
        'location',     b.location,
        'activity_log', b.activity_log,
        'report',       b.notes,
        'notes', coalesce((
          SELECT jsonb_agg(jsonb_build_object(
              'author_role', n.author_role, 'author_name', n.author_name,
              'phase', n.phase, 'body', n.body, 'created_at', n.created_at)
            ORDER BY (n.phase = 'pre') DESC, n.created_at)
          FROM booking_notes n WHERE n.booking_id = b.id), '[]'::jsonb)
      ) AS r
    FROM bookings b
    WHERE b.kind = 'lesson'
      AND b.client_id = current_client_id()
      AND (
        (b.notes IS NOT NULL AND btrim(b.notes) <> '')
        OR b.activity_log IS NOT NULL
        OR EXISTS (SELECT 1 FROM booking_notes n WHERE n.booking_id = b.id)
      )
    ORDER BY b.starts_at DESC
    LIMIT 50
  ) r
$$;


--
-- Name: my_lesson_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_lesson_sessions() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', s.id, 'starts_at', s.starts_at, 'ends_at', s.ends_at,
      'status', upper(s.status), 'location', s.location, 'notes', s.notes)
      ORDER BY s.ord), '[]'::jsonb)
  FROM (
    SELECT b.*, row_number() OVER (
        ORDER BY (b.starts_at >= now()) DESC,
                 CASE WHEN b.starts_at >= now() THEN b.starts_at END ASC,
                 CASE WHEN b.starts_at <  now() THEN b.starts_at END DESC
      ) AS ord
    FROM bookings b
    WHERE b.kind = 'lesson'
      AND b.client_id = current_client_id()
      AND has_module('mod.lessons')
    ORDER BY (b.starts_at >= now()) DESC,
             CASE WHEN b.starts_at >= now() THEN b.starts_at END ASC,
             CASE WHEN b.starts_at <  now() THEN b.starts_at END DESC
    LIMIT 50
  ) s
$$;


--
-- Name: FUNCTION my_lesson_sessions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_lesson_sessions() IS 'The signed-in member''s own lesson sessions (jsonb array): upcoming soonest-first, then recent past, limit 50. Empty array for non-clients or a mod.lessons-OFF tenant.';


--
-- Name: my_listable_horses(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_listable_horses(p_intent text DEFAULT 'sale'::text) RETURNS TABLE(id uuid, registered_name text, nickname text, breed text, color text, sex text, height text, date_of_birth date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT h.id, h.registered_name, h.nickname, h.breed, h.color, h.sex,
         h.height, h.date_of_birth
  FROM horses h
  WHERE h.org_id = current_org() AND h.deleted_at IS NULL
    AND (
      has_staff_access()
      OR h.current_owner_contact_id = current_contact_id()
      OR h.lessee_contact_id = current_contact_id()
    )
    AND can_list_horse(h.id, p_intent)
  ORDER BY coalesce(h.nickname, h.registered_name)
$$;


--
-- Name: my_locations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_locations() RETURNS TABLE(id uuid, name text, address text, is_offsite boolean, is_default boolean, is_mine boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT l.id, l.name, l.address, l.is_offsite, l.is_default,
         (l.owner_contact_id IS NOT NULL) AS is_mine
  FROM locations l
  WHERE l.org_id = current_org()
    AND l.active
    AND (l.owner_contact_id IS NULL OR l.owner_contact_id = current_contact_id())
  ORDER BY l.is_default DESC, (l.owner_contact_id IS NOT NULL), l.sort_order, l.name
$$;


--
-- Name: my_modules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_modules() RETURNS TABLE(module_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT om.module_key
    FROM org_modules om
    JOIN modules m ON m.module_key = om.module_key
    WHERE om.org_id = current_org()
      AND om.enabled
      AND (om.expires_at IS NULL OR om.expires_at > now())
      AND COALESCE(m.active, true)
    ORDER BY om.module_key
$$;


--
-- Name: FUNCTION my_modules(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_modules() IS 'U15 Layer-C UI-gating seam: the CURRENT caller''s own tenant''s enabled+unexpired module keys, read past org_modules RLS so a plain USER member can resolve nav gating. current_org()-scoped; never crosses tenants.';


--
-- Name: my_name_confirmation_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_name_confirmation_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_needs boolean; v_first text; v_last text;
BEGIN
  IF auth.uid() IS NULL OR v_contact IS NULL THEN
    RETURN jsonb_build_object('needs_confirmation', false);
  END IF;
  SELECT name_needs_confirmation, first_name, last_name
    INTO v_needs, v_first, v_last
    FROM contacts WHERE id = v_contact;
  RETURN jsonb_build_object(
    'needs_confirmation', coalesce(v_needs, false),
    'first_name', v_first,
    'last_name', v_last);
END
$$;


--
-- Name: my_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_notifications(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', n.id, 'kind', n.kind, 'title', n.title, 'body', n.body,
      'link', n.link, 'read_at', n.read_at, 'created_at', n.created_at)
      ORDER BY n.created_at DESC, n.id DESC), '[]'::jsonb)
  FROM (
    SELECT * FROM notifications
    WHERE user_id = auth.uid()
      -- a contract-linked notification is only valid while its document exists and
      -- is not soft-deleted; non-contract notifications are unaffected.
      AND (
        link IS NULL
        OR link !~ '^/app/contracts/[0-9a-fA-F-]{36}$'
        OR EXISTS (
          SELECT 1 FROM documents d
          WHERE d.id = regexp_replace(link, '^/app/contracts/', '')::uuid
            AND d.deleted_at IS NULL
        )
      )
      -- RETIRED: the cancel path no longer exists. Its historical notifications
      -- stay in the table as evidence but are never surfaced as live to-dos.
      AND kind <> 'contract_cancelled'
      AND title NOT ILIKE '%awaiting archive%'
    ORDER BY created_at DESC, id DESC
    LIMIT greatest(coalesce(p_limit, 20), 1)
  ) n
$_$;


--
-- Name: FUNCTION my_notifications(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_notifications(p_limit integer) IS 'The signed-in user''s notifications, newest first (jsonb array; empty array when none).';


--
-- Name: my_onboarding_checklist(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_onboarding_checklist() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN has_staff_access() THEN '[]'::jsonb
    WHEN current_contact_id() IS NULL THEN '[]'::jsonb
    ELSE contact_checklist(current_contact_id())
  END
$$;


--
-- Name: my_onboarding_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_onboarding_state() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact  uuid;
  v_c        contacts%ROWTYPE;
  v_docs     jsonb := '[]'::jsonb;
  v_purchase jsonb;
  v_minor    jsonb;
  v_prefill  jsonb;
  v_needed   boolean := false;
  v_profile  boolean := false;
  v_pid      uuid;
  v_phorse   uuid;
  v_horse_needed boolean := false;
  req        record;
  v_doc      uuid;
  v_status   text;
  v_title    text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  PERFORM ensure_my_membership();
  v_contact := coalesce(current_contact_id(), ensure_contact_for_profile(auth.uid()));
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('needed', false, 'profile_complete', false,
                              'documents', '[]'::jsonb, 'purchase', NULL, 'minor', NULL,
                              'horse_needed', false, 'prefill', NULL);
  END IF;

  SELECT * INTO v_c FROM contacts WHERE id = v_contact;
  v_profile := v_c.phone IS NOT NULL AND v_c.date_of_birth IS NOT NULL
           AND v_c.emergency_contact_1_name IS NOT NULL
           AND v_c.emergency_contact_1_phone IS NOT NULL;

  -- Everything the contact record already knows about the person, so the
  -- details form prefills instead of asking again (re-invited members).
  v_prefill := jsonb_build_object(
    'first_name', v_c.first_name, 'last_name', v_c.last_name,
    'phone', v_c.phone,
    'date_of_birth', to_char(v_c.date_of_birth, 'YYYY-MM-DD'),
    'address_street', v_c.address_line1, 'address_city', v_c.city,
    'address_state', v_c.state, 'address_zip', v_c.postal_code,
    'emergency_contact_1_name', v_c.emergency_contact_1_name,
    'emergency_contact_1_relationship', v_c.emergency_contact_1_relationship,
    'emergency_contact_1_phone', v_c.emergency_contact_1_phone,
    'emergency_contact_2_name', v_c.emergency_contact_2_name,
    'emergency_contact_2_relationship', v_c.emergency_contact_2_relationship,
    'emergency_contact_2_phone', v_c.emergency_contact_2_phone,
    'riding_experience_years', v_c.riding_experience_years,
    'jump_experience', v_c.jump_experience,
    'riding_background', v_c.riding_background);

  -- the contact's latest purchase (spine)
  SELECT pu.id, pu.horse_id INTO v_pid, v_phorse
    FROM purchases pu
    WHERE pu.buyer_contact_id = v_contact AND pu.deleted_at IS NULL
    ORDER BY pu.created_at DESC LIMIT 1;
  IF v_pid IS NOT NULL THEN
    SELECT jsonb_build_object(
        'purchase_id', pu.id, 'horse_id', pu.horse_id,
        'tier_label', (SELECT pi.label FROM purchase_items pi WHERE pi.purchase_id = pu.id ORDER BY pi.created_at DESC LIMIT 1),
        'amount', pu.amount, 'lessons_included', NULL, 'cadence', NULL,
        'paid', (pu.payment_status = 'paid'), 'payment_method', pu.payment_method)
      INTO v_purchase
      FROM purchases pu WHERE pu.id = v_pid;

    -- horse intake is needed when this purchase uses the rider's OWN horse and
    -- none is attached yet: any segment='horse' item, or a "(With your horse)"
    -- rider lesson (horse_included = false).
    v_horse_needed := v_phorse IS NULL AND EXISTS (
      SELECT 1 FROM purchase_items pi
      JOIN offerings o ON o.id = pi.offering_id
      WHERE pi.purchase_id = v_pid
        AND (o.segment = 'horse' OR (o.segment = 'rider' AND o.horse_included = false))
    );
  END IF;

  -- The horse step ALSO runs as a review whenever a horse document is required
  -- and not yet satisfied — the member confirms/completes the horse record the
  -- paperwork merges from before signing (staff re-assign, no purchase needed).
  IF NOT v_horse_needed THEN
    v_horse_needed := EXISTS (
      SELECT 1 FROM contact_required_documents crd
      WHERE crd.contact_id = v_contact
        AND crd.template_key IN ('HORSE_EMERGENCY_VET','RELEASE_HORSE_CARE')
        AND NOT EXISTS (
          SELECT 1 FROM documents d
          JOIN contract_templates ct2 ON ct2.id = d.template_id
          WHERE d.contact_id = v_contact AND d.deleted_at IS NULL
            AND d.status = 'EXECUTED'
            AND coalesce(d.current_status,'') <> 'superseded'
            AND ct2.template_key = crd.template_key)
    );
  END IF;

  -- a guardian-linked minor, if any
  SELECT jsonb_build_object('first_name', mc.first_name, 'last_name', mc.last_name,
      'dob', to_char(mc.date_of_birth, 'YYYY-MM-DD'))
    INTO v_minor
    FROM contacts mc
    WHERE mc.guardian_contact_id = v_contact AND mc.deleted_at IS NULL
    ORDER BY mc.created_at LIMIT 1;

  FOR req IN
    SELECT ct.template_key FROM required_templates_for_contact(v_contact) ct
    ORDER BY coalesce(array_position(
      ARRAY['COMPANY_POLICIES','FACILITY_RULES','RELEASE_PARTICIPANT',
            'RELEASE_HORSE_CARE','RELEASE_HORSE_EXERCISE','RELEASE_GENERAL',
            'HUMAN_EMERGENCY_MEDICAL','HORSE_EMERGENCY_VET','MEDIA_RELEASE'],
      ct.template_key), 99), ct.template_key
  LOOP
    SELECT d.id, d.status, coalesce(d.title, t.title) INTO v_doc, v_status, v_title
      FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
      WHERE d.contact_id = v_contact AND t.template_key = req.template_key
        AND d.deleted_at IS NULL
        -- a superseded executed copy no longer satisfies (staff re-assign):
        -- prefer a live pending/current doc over superseded evidence.
      ORDER BY (d.status = 'EXECUTED' AND coalesce(d.current_status,'') <> 'superseded') DESC,
               (d.status <> 'EXECUTED') DESC,
               d.created_at DESC
      LIMIT 1;
    IF v_doc IS NOT NULL AND v_status = 'EXECUTED' THEN
      -- if that executed copy is superseded, it does not satisfy the requirement
      IF EXISTS (SELECT 1 FROM documents dx WHERE dx.id = v_doc AND coalesce(dx.current_status,'') = 'superseded') THEN
        v_status := 'SUPERSEDED';
      END IF;
    END IF;
    IF v_doc IS NULL THEN
      SELECT title INTO v_title FROM contract_templates WHERE template_key = req.template_key;
      v_status := 'MISSING';
    END IF;
    IF v_status IS DISTINCT FROM 'EXECUTED' THEN v_needed := true; END IF;
    v_docs := v_docs || jsonb_build_object(
      'document_id', v_doc, 'template_key', req.template_key,
      'title', v_title, 'status', coalesce(v_status, 'MISSING'));
    v_doc := NULL; v_status := NULL; v_title := NULL;
  END LOOP;

  RETURN jsonb_build_object('needed', v_needed, 'profile_complete', v_profile,
                            'documents', v_docs, 'purchase', v_purchase, 'minor', v_minor,
                            'horse_needed', v_horse_needed, 'prefill', v_prefill);
END;
$$;


--
-- Name: FUNCTION my_onboarding_state(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_onboarding_state() IS 'The signed-in member''s onboarding snapshot. v3: checklist scoped to the single most recent AWAITING_SIGNATURE engagement (duplicate provisions no longer double the documents) and membership self-heals on load.';


--
-- Name: my_pending_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_pending_changes() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', cr.id, 'booking_id', cr.booking_id, 'kind', cr.request_kind,
      'status', cr.status, 'proposed_starts_at', cr.proposed_starts_at,
      'fee_amount', cr.fee_amount, 'fee_paid', cr.fee_paid, 'phone_required', cr.phone_required,
      'created_at', cr.created_at) ORDER BY cr.created_at DESC), '[]'::jsonb)
  FROM booking_change_requests cr
  WHERE cr.requested_by = auth.uid() AND cr.status = 'pending'
$$;


--
-- Name: my_purchase_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_purchase_categories() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(array_agg(DISTINCT cat ORDER BY cat), ARRAY[]::text[])
  FROM (
    SELECT CASE o.segment
             WHEN 'rider'   THEN 'riding'
             WHEN 'support' THEN 'deal'
             WHEN 'horse'   THEN 'care'
             ELSE o.segment
           END AS cat
    FROM purchases pu
    JOIN purchase_items pi ON pi.purchase_id = pu.id
    JOIN offerings o ON o.id = pi.offering_id
    WHERE pu.buyer_contact_id = current_contact_id()
      AND pu.deleted_at IS NULL
      AND o.segment IS NOT NULL

    UNION

    SELECT CASE lower(t)
             WHEN 'rider'       THEN 'riding'
             WHEN 'horse owner' THEN 'care'
             WHEN 'owner'       THEN 'care'
             WHEN 'buyer'       THEN 'deal'
             WHEN 'seller'      THEN 'deal'
             WHEN 'lessee'      THEN 'deal'
             WHEN 'lessor'      THEN 'deal'
             ELSE NULL
           END AS cat
    FROM contacts c
    CROSS JOIN LATERAL unnest(coalesce(c.tags, ARRAY[]::text[])) AS t
    WHERE c.id = current_contact_id()
  ) s
  WHERE cat IS NOT NULL
$$;


--
-- Name: my_stable_add_horse(text, text, text, text, text, date, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_stable_add_horse(p_name text, p_barn_name text DEFAULT NULL::text, p_breed text DEFAULT NULL::text, p_sex text DEFAULT NULL::text, p_height text DEFAULT NULL::text, p_dob date DEFAULT NULL::date, p_color text DEFAULT NULL::text, p_location text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_markings text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_res jsonb;
BEGIN
  v_res := create_horse_record(jsonb_strip_nulls(jsonb_build_object(
    'registered_name', p_name,
    'nickname', p_barn_name,
    'breed', p_breed,
    'sex', p_sex,
    'height', p_height,
    'date_of_birth', p_dob,
    'color', p_color,
    'current_location', coalesce(p_location, 'Carmel Creek Ranch'),
    'markings', p_markings,
    'medical_history', p_notes
  )));
  -- return the horse id for both created + matched outcomes (back-compat).
  RETURN (v_res->>'horse_id')::uuid;
END;
$$;


--
-- Name: my_stable_delete_horse(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_stable_delete_horse(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE horses
     SET deleted_at = now()
   WHERE id = p_id
     AND org_id = current_org()
     AND deleted_at IS NULL
     AND current_owner_contact_id = current_contact_id();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'horse not found or not yours to remove';
  END IF;
END;
$$;


--
-- Name: my_stable_horses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_stable_horses() RETURNS TABLE(id uuid, registered_name text, nickname text, breed text, sex text, height text, date_of_birth date, color text, current_location text, is_owner boolean, created_at timestamp with time zone, lease_start date, lease_end date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope uuid;
BEGIN
  v_scope := CASE WHEN has_staff_access() THEN company_contact_id()
                  ELSE current_contact_id() END;
  RETURN QUERY
  SELECT h.id, h.registered_name, h.nickname, h.breed, h.sex, h.height,
         h.date_of_birth, h.color, h.current_location,
         (h.current_owner_contact_id = v_scope) AS is_owner,
         h.created_at, h.lease_start, h.lease_end
  FROM horses h
  WHERE h.deleted_at IS NULL
    AND h.org_id = current_org()
    AND (
      h.current_owner_contact_id = v_scope
      OR h.lessee_contact_id     = v_scope
      OR EXISTS (
        SELECT 1 FROM horse_relationships hr
        WHERE hr.horse_id = h.id AND hr.active
          AND hr.party_contact_id = v_scope
          AND (hr.term_end IS NULL OR hr.term_end >= current_date)
      )
    )
  ORDER BY h.created_at;
END;
$$;


--
-- Name: my_stable_update_horse(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_stable_update_horse(p_id uuid, p_barn_name text DEFAULT NULL::text, p_breed text DEFAULT NULL::text, p_sex text DEFAULT NULL::text, p_height text DEFAULT NULL::text, p_color text DEFAULT NULL::text, p_location text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE horses
     SET nickname        = COALESCE(p_barn_name, nickname),
         breed            = COALESCE(p_breed, breed),
         sex              = COALESCE(p_sex, sex),
         height           = COALESCE(p_height, height),
         color            = COALESCE(p_color, color),
         current_location = COALESCE(p_location, current_location),
         updated_at       = now()
   WHERE id = p_id
     AND org_id = current_org()
     AND deleted_at IS NULL
     AND current_owner_contact_id = current_contact_id();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'horse not found or not yours to edit';
  END IF;
END;
$$;


--
-- Name: my_standing_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_standing_categories() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_groups  text[];
BEGIN
  IF auth.uid() IS NULL OR v_contact IS NULL THEN RETURN ARRAY[]::text[]; END IF;
  SELECT coalesce(array_agg(DISTINCT g.group_type ORDER BY g.group_type), ARRAY[]::text[])
    INTO v_groups
    FROM groups g
   WHERE g.contact_id = v_contact AND g.group_type IN ('RIDER','HORSE_OWNER');
  RETURN v_groups;
END;
$$;


