COMMENT ON FUNCTION public.my_unread_count() IS 'Unread-notification count for the signed-in user (the bell badge).';


--
-- Name: my_view_surfaces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_view_surfaces() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cats     text[] := my_purchase_categories();
  v_operator boolean := has_staff_access();
  v_surfaces text[] := ARRAY['dashboard']::text[];  -- always present
BEGIN
  IF v_operator THEN
    v_cats := (SELECT ARRAY(SELECT DISTINCT unnest(v_cats || ARRAY['operator'])));
    v_surfaces := v_surfaces || ARRAY['feed', 'company', 'dashboard'];
  END IF;

  IF 'riding' = ANY(v_cats) THEN
    v_surfaces := v_surfaces || ARRAY['feed', 'community', 'library', 'dashboard'];
  END IF;

  IF 'deal' = ANY(v_cats) THEN
    v_surfaces := v_surfaces || ARRAY['deal_dashboard'];
  END IF;
  IF 'care' = ANY(v_cats) THEN
    v_surfaces := v_surfaces || ARRAY['care_dashboard'];
  END IF;

  v_surfaces := v_surfaces || ARRAY['account', 'documents', 'orders'];
  v_surfaces := (SELECT ARRAY(SELECT DISTINCT unnest(v_surfaces) ORDER BY 1));

  RETURN jsonb_build_object(
    'categories', to_jsonb(v_cats),
    'surfaces',   to_jsonb(v_surfaces),
    'has_feed',   ('feed' = ANY(v_surfaces)),
    'has_community', ('community' = ANY(v_surfaces)),
    'is_operator', v_operator
  );
END;
$$;


--
-- Name: my_wall_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_wall_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_state jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_contact IS NULL THEN
    RETURN jsonb_build_object('pending', 0, 'wall', false, 'staff', false);
  END IF;

  v_state := contact_document_wall_state(v_contact);

  RETURN jsonb_build_object(
    'pending', (v_state->>'pending')::int,
    'wall', ((v_state->>'gating')::int > 0 AND NOT has_staff_access()),
    'staff_banner', ((v_state->>'gating')::int > 0 AND has_staff_access()),
    'staff', has_staff_access());
END;
$$;


