END;
$$;


--
-- Name: set_my_onboarding_horses(uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_onboarding_horses(p_horse_ids uuid[], p_deferred_horse_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_user    uuid := auth.uid();
  v_org     uuid;
  v_doc     record;
  v_i       integer;
  v_hid     uuid;
  v_bound   integer := 0;
  v_docs    integer := 0;
  v_notes   integer := 0;
  v_name    text;
  v_purch   uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  v_contact := current_contact_id();
  IF v_contact IS NULL THEN RAISE EXCEPTION 'no contact record for this account'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = v_contact;

  -- Ownership fence: every id must be a horse this contact owns or leases.
  IF p_horse_ids IS NOT NULL THEN
    FOR v_i IN 1 .. coalesce(array_length(p_horse_ids, 1), 0) LOOP
      IF NOT EXISTS (
        SELECT 1 FROM horses h
         WHERE h.id = p_horse_ids[v_i] AND h.deleted_at IS NULL
           AND (h.current_owner_contact_id = v_contact OR h.lessee_contact_id = v_contact)
      ) THEN
        RAISE EXCEPTION 'you can only attach your own horse';
      END IF;
    END LOOP;
  END IF;

  -- Bind to every OPEN horse document this member holds. Executed documents are
  -- never touched — a signed release is evidence and its horse set is frozen.
  --
  -- Binding replaces the whole set (the member's choice on this pass is the
  -- truth) and then REGENERATES the document, because the body was composed for
  -- whatever horse it previously named. Regeneration goes through
  -- generate_my_onboarding_documents' own path: we soft-delete the stale copy
  -- and let generate_document recompose with the full set, which is the single
  -- composition path everything else uses.
  FOR v_doc IN
    SELECT d.id, t.template_key
      FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contact_id = v_contact
       AND d.deleted_at IS NULL
       AND t.template_key IN ('HORSE_EMERGENCY_VET','RELEASE_HORSE_CARE')
       AND d.status <> 'EXECUTED'
       AND d.workflow_state IN ('editable','editing','in_review')
  LOOP
    v_docs := v_docs + 1;
    DELETE FROM document_horses WHERE document_id = v_doc.id;
    FOR v_i IN 1 .. coalesce(array_length(p_horse_ids, 1), 0) LOOP
      INSERT INTO document_horses (org_id, document_id, horse_id, position)
        VALUES (v_org, v_doc.id, p_horse_ids[v_i], v_i)
        ON CONFLICT (document_id, horse_id) DO UPDATE SET position = EXCLUDED.position;
      v_bound := v_bound + 1;
    END LOOP;
  END LOOP;

  -- Recompose: soft-delete the now-stale bodies and regenerate them bound to the
  -- full set. generate_my_onboarding_documents captures the set we just wrote
  -- (per template key) and replays it into generate_document.
  IF v_docs > 0 AND coalesce(array_length(p_horse_ids, 1), 0) > 0 THEN
    PERFORM generate_my_onboarding_documents();
  END IF;

  -- the purchase keeps carrying the PRIMARY horse (unchanged behaviour)
  IF coalesce(array_length(p_horse_ids, 1), 0) > 0 THEN
    SELECT pu.id INTO v_purch FROM purchases pu
      WHERE pu.buyer_contact_id = v_contact AND pu.deleted_at IS NULL
      ORDER BY pu.created_at DESC LIMIT 1;
    IF v_purch IS NOT NULL THEN
      UPDATE purchases SET horse_id = p_horse_ids[1] WHERE id = v_purch;
    END IF;
  END IF;

  -- THE SOFT DEFERRED REMINDER — one per deferred horse, never duplicated while
  -- an undismissed one is already sitting there.
  FOR v_i IN 1 .. coalesce(array_length(p_deferred_horse_ids, 1), 0) LOOP
    v_hid := p_deferred_horse_ids[v_i];
    CONTINUE WHEN NOT EXISTS (
      SELECT 1 FROM horses h WHERE h.id = v_hid AND h.deleted_at IS NULL
        AND (h.current_owner_contact_id = v_contact OR h.lessee_contact_id = v_contact));
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM notifications n
       WHERE n.user_id = v_user AND n.kind = 'horse_record_task'
         AND n.read_at IS NULL
         AND n.link = '/app/horse-intake?horse=' || v_hid::text);
    SELECT coalesce(nullif(btrim(h.nickname), ''), h.registered_name, 'your horse')
      INTO v_name FROM horses h WHERE h.id = v_hid;
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
      VALUES (v_org, v_user, 'horse_record_task',
        'Finish ' || v_name || '''s record',
        'You set ' || v_name || ' aside for later. Their record still needs a few '
        || 'details before the horse paperwork can cover them. Pick up where you '
        || 'left off whenever you are ready — nothing else is waiting on it.',
        '/app/horse-intake?horse=' || v_hid::text);
    v_notes := v_notes + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'documents', v_docs, 'bindings', v_bound, 'deferred_reminders', v_notes);
END;
$$;


--
-- Name: FUNCTION set_my_onboarding_horses(p_horse_ids uuid[], p_deferred_horse_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_my_onboarding_horses(p_horse_ids uuid[], p_deferred_horse_ids uuid[]) IS 'Member path: bind an ordered horse set to BOTH open horse documents (combined signing), attach the primary to the purchase, and raise the soft dashboard reminder for horses the member deferred. Own horses only.';


--
-- Name: set_org_module(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_org_module(p_org uuid, p_key text, p_enabled boolean DEFAULT true, p_source text DEFAULT 'ADDON'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Platform / billing path only. service_role (BYPASSRLS) has auth.uid() NULL and is
  -- not a SUPER_ADMIN profile, so allow it explicitly as the billing webhook caller.
  IF NOT is_super_admin() AND auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'set_org_module is restricted to SUPER_ADMIN / the billing service'
      USING errcode = 'insufficient_privilege';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM organizations WHERE id = p_org) THEN
    RAISE EXCEPTION 'unknown organization: %', p_org;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM modules WHERE module_key = p_key) THEN
    RAISE EXCEPTION 'unknown module: %', p_key;
  END IF;
  IF p_source NOT IN ('TIER','ADDON','GRANT','SUBSCRIPTION') THEN
    RAISE EXCEPTION 'invalid source: %', p_source;
  END IF;

  INSERT INTO org_modules (org_id, module_key, enabled, source)
  VALUES (p_org, p_key, p_enabled, p_source)
  ON CONFLICT (org_id, module_key)
    DO UPDATE SET enabled = EXCLUDED.enabled, source = EXCLUDED.source, updated_at = now();
END;
$$;


--
-- Name: FUNCTION set_org_module(p_org uuid, p_key text, p_enabled boolean, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_org_module(p_org uuid, p_key text, p_enabled boolean, p_source text) IS 'U6: SUPER_ADMIN / billing-service upsert of a single org_modules entitlement (add-on / subscription seam). §4.1.';


--
-- Name: set_party_controls(uuid, text, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_party_controls(p_document_id uuid, p_role text, p_can_fill boolean, p_can_edit_deal boolean, p_can_suggest boolean, p_can_add_clause boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_role text := upper(p_role);
  v_others int;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (has_staff_access() AND v_org = current_org()) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;

  -- Turning this party OFF is refused when no OTHER party is left holding it.
  -- Counted over the parties that actually sign, so the company's own role
  -- cannot be mistaken for a counterparty that could carry the permission.
  IF NOT p_can_edit_deal THEN
    SELECT count(*) INTO v_others
      FROM document_party_controls c
      JOIN document_parties dp
        ON dp.document_id = c.document_id AND dp.party_role = c.party_role
     WHERE c.document_id = p_document_id
       AND c.party_role <> v_role
       AND c.can_edit_deal
       AND dp.is_signer
       AND dp.party_role NOT IN ('FHE', 'COMPANY');

    IF v_others = 0 THEN
      RAISE EXCEPTION 'at least one party must be able to edit deal terms — '
        'otherwise no party can change a term and every edit has to go through staff';
    END IF;
  END IF;

  INSERT INTO document_party_controls (document_id, party_role, can_fill, can_edit_deal, can_suggest, can_add_clause, org_id)
  VALUES (p_document_id, v_role, p_can_fill, p_can_edit_deal, p_can_suggest, p_can_add_clause, v_org)
  ON CONFLICT (document_id, party_role)
  DO UPDATE SET can_fill = excluded.can_fill,
                can_edit_deal = excluded.can_edit_deal,
                can_suggest = excluded.can_suggest,
                can_add_clause = excluded.can_add_clause;
END;
$$;


--
-- Name: FUNCTION set_party_controls(p_document_id uuid, p_role text, p_can_fill boolean, p_can_edit_deal boolean, p_can_suggest boolean, p_can_add_clause boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_party_controls(p_document_id uuid, p_role text, p_can_fill boolean, p_can_edit_deal boolean, p_can_suggest boolean, p_can_add_clause boolean) IS 'Sets one party''s document controls. REFUSES a change that would leave no signing party able to edit deal terms: in that state the parties can at most suggest, and every actual edit has to be made by staff on their behalf. Turning one party off while another holds the permission is unaffected.';


--
-- Name: set_recipient_editing(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_recipient_editing(p_document_id uuid, p_on boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  IF NOT (
       (has_staff_access() AND v_org = current_org())
  ) THEN
    RAISE EXCEPTION 'not authorized to change editing permission on document %', p_document_id;
  END IF;

  UPDATE documents SET recipient_editing = coalesce(p_on, false) WHERE id = p_document_id;
  -- keep the active share row in step, if one exists
  UPDATE document_shares SET recipient_editing = coalesce(p_on, false)
    WHERE document_id = p_document_id;
  RETURN coalesce(p_on, false);
END;
$$;


--
-- Name: FUNCTION set_recipient_editing(p_document_id uuid, p_on boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_recipient_editing(p_document_id uuid, p_on boolean) IS 'Originator/staff toggles documents.recipient_editing (whether the counterparty may edit DEAL fields/body). Keeps the active document_shares row in step.';


--
-- Name: set_request_checklist(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_request_checklist(p_request_id uuid, p_checklist jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_out jsonb;
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'not authorized to update the request checklist';
  END IF;
  IF p_checklist IS NULL OR jsonb_typeof(p_checklist) <> 'object' THEN
    RAISE EXCEPTION 'checklist must be a JSON object of item key -> boolean';
  END IF;

  UPDATE requests SET checklist = p_checklist WHERE id = p_request_id
    RETURNING checklist INTO v_out;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown request: %', p_request_id;
  END IF;

  RETURN v_out;
END;
$$;


--
-- Name: FUNCTION set_request_checklist(p_request_id uuid, p_checklist jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_request_checklist(p_request_id uuid, p_checklist jsonb) IS 'Store the lesson-fit checklist state (flat object of item key -> boolean) on a request. Staff-gated (has_staff_access()).';


--
-- Name: set_support_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_support_status(p_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'admin access required';
  END IF;
  IF p_status NOT IN ('open', 'in_progress', 'resolved') THEN
    RAISE EXCEPTION 'invalid status';
  END IF;

  UPDATE support_requests
     SET status = p_status,
         resolved_at = CASE WHEN p_status = 'resolved' THEN now() ELSE NULL END,
         resolved_by = CASE WHEN p_status = 'resolved' THEN auth.uid() ELSE NULL END
   WHERE id = p_id
     AND org_id = current_org();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'request not found in this org';
  END IF;
END;
$$;


--
-- Name: set_unit_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_unit_status(p_unit_id uuid, p_status text, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_u fulfillment_units%ROWTYPE;
BEGIN
  SELECT * INTO v_u FROM fulfillment_units WHERE id = p_unit_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unit not found'; END IF;
  UPDATE fulfillment_units
     SET current_status = p_status,
         consumed_at = CASE WHEN p_status IN ('consumed','delivered') THEN now() ELSE consumed_at END
   WHERE id = p_unit_id;
  PERFORM log_status_event('fulfillment', p_unit_id, p_status, p_detail, v_u.org_id);
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: share_document(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_document(p_document_id uuid, p_with_contact_id uuid, p_recipient_editing boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid;
  v_title   text;
  v_by      uuid := current_contact_id();
  v_share   document_shares%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT org_id, coalesce(title, 'A contract') INTO v_org, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  IF NOT (
       (has_staff_access() AND v_org = current_org())
  ) THEN
    RAISE EXCEPTION 'not authorized to share document %', p_document_id;
  END IF;

  PERFORM 1 FROM contacts WHERE id = p_with_contact_id AND org_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown contact % in this organization', p_with_contact_id;
  END IF;

  INSERT INTO document_shares (org_id, document_id, shared_with_contact_id,
                              granted_by_contact_id, recipient_editing, notified_at)
    VALUES (v_org, p_document_id, p_with_contact_id, v_by,
            coalesce(p_recipient_editing, false), now())
  ON CONFLICT (document_id, shared_with_contact_id) DO UPDATE SET
    recipient_editing = excluded.recipient_editing,
    granted_by_contact_id = excluded.granted_by_contact_id,
    notified_at = now()
  RETURNING * INTO v_share;

  -- mirror recipient_editing onto the document for the active share
  UPDATE documents SET recipient_editing = coalesce(p_recipient_editing, false)
    WHERE id = p_document_id;

  -- notify the recipient's app user (skip silently when they have no account)
  PERFORM contract_notify(p_document_id, p_with_contact_id, 'contract_shared',
    v_title || ' was shared with you',
    'You have been granted access to review this contract.');

  RETURN jsonb_build_object(
    'id', v_share.id, 'document_id', v_share.document_id,
    'shared_with_contact_id', v_share.shared_with_contact_id,
    'recipient_editing', v_share.recipient_editing, 'notified_at', v_share.notified_at);
END;
$$;


--
-- Name: FUNCTION share_document(p_document_id uuid, p_with_contact_id uuid, p_recipient_editing boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.share_document(p_document_id uuid, p_with_contact_id uuid, p_recipient_editing boolean) IS 'Originator/staff: create/update a document_shares grant, mirror recipient_editing onto the document, and notify the recipient (kind ''contract_shared''). Returns the share as jsonb.';


--
-- Name: share_evaluation_report(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_evaluation_report(p_report_id uuid, p_email text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_allowed boolean;
BEGIN
  SELECT org_id, (has_staff_access() OR contact_id = current_contact_id())
    INTO v_org, v_allowed
    FROM evaluation_reports WHERE id = p_report_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'report not found'; END IF;
  IF NOT coalesce(v_allowed, false) THEN RAISE EXCEPTION 'not allowed to share this report'; END IF;

  INSERT INTO evaluation_report_shares (org_id, report_id, shared_with_contact_id, shared_with_email, shared_by)
    VALUES (v_org, p_report_id, p_contact_id, lower(nullif(trim(p_email), '')), auth.uid());
  INSERT INTO evaluation_report_access (org_id, report_id, actor_user_id, action, detail)
    VALUES (v_org, p_report_id, auth.uid(), 'shared', coalesce(p_email, p_contact_id::text));
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: sign_general_release(text, text, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_general_release(p_full_name text, p_email text, p_phone text, p_typed_name text, p_org uuid DEFAULT NULL::uuid, p_esign_consent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Owner directive 2026-07-03: kiosk signatures must carry an email for
  -- attribution. Fail before any row is written.
  IF NULLIF(trim(coalesce(p_email, '')), '') IS NULL THEN
    RAISE EXCEPTION 'email is required';
  END IF;
  RETURN sign_release(
    'RELEASE_GENERAL',
    NULLIF(split_part(trim(coalesce(p_full_name, '')), ' ', 1), ''),
    CASE WHEN position(' ' IN trim(coalesce(p_full_name, ''))) > 0
         THEN NULLIF(trim(substring(trim(p_full_name) FROM position(' ' IN trim(p_full_name)) + 1)), '')
         ELSE NULL END,
    p_email, p_phone, p_typed_name,
    false, NULL, NULL, NULL, NULL, true, p_org,
    coalesce(p_esign_consent, false));
END;
$$;


--
-- Name: FUNCTION sign_general_release(p_full_name text, p_email text, p_phone text, p_typed_name text, p_org uuid, p_esign_consent boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sign_general_release(p_full_name text, p_email text, p_phone text, p_typed_name text, p_org uuid, p_esign_consent boolean) IS 'Kiosk wrapper over sign_release(RELEASE_GENERAL, …, adult path). v4: forwards its own trailing p_esign_consent (DEFAULT false — sign_release rejects without it; consent always comes from the user). v3: p_email REQUIRED. Splits its single full-name argument on the first space into first/last. Unilateral: EXECUTES on the visitor signature (signer = CLIENT party).';


--
-- Name: sign_release(text, text, text, text, text, text, boolean, text, text, date, text, boolean, uuid, boolean, date, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_release(p_template_key text, p_first_name text, p_last_name text, p_email text, p_phone text, p_typed_name text, p_is_minor boolean DEFAULT false, p_minor_first_name text DEFAULT NULL::text, p_minor_last_name text DEFAULT NULL::text, p_minor_dob date DEFAULT NULL::date, p_guardian_relationship text DEFAULT NULL::text, p_rules_acknowledged boolean DEFAULT false, p_org uuid DEFAULT NULL::uuid, p_esign_consent boolean DEFAULT false, p_dob date DEFAULT NULL::date, p_address_line1 text DEFAULT NULL::text, p_address_line2 text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_ec1_name text DEFAULT NULL::text, p_ec1_relationship text DEFAULT NULL::text, p_ec1_phone text DEFAULT NULL::text, p_ec2_name text DEFAULT NULL::text, p_ec2_relationship text DEFAULT NULL::text, p_ec2_phone text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_first     text := trim(coalesce(p_first_name, ''));
  v_last      text := trim(coalesce(p_last_name, ''));
  v_name      text;
  v_typed     text := trim(coalesce(p_typed_name, ''));
  v_email     text := lower(trim(coalesce(p_email, '')));
  v_phone     text := trim(coalesce(p_phone, ''));
  v_minor_first text := trim(coalesce(p_minor_first_name, ''));
  v_minor_last  text := trim(coalesce(p_minor_last_name, ''));
  v_minor     text;
  v_rel       text := trim(coalesce(p_guardian_relationship, ''));
  v_org       uuid;
  v_contact   uuid;
  v_minor_c   uuid;
  v_client    uuid;
  v_parties   jsonb;
  v_doc       uuid;
  v_doc_code  text;
  v_body      text;
  v_today     text := to_char(current_date, 'FMMonth FMDD, YYYY');
  v_need      integer;
  v_have      integer;
  v_status    text;
  v_ip        text;
  v_ua        text;
  v_signed_at timestamptz;
  v_hash      text;
  v_is_release boolean;
BEGIN
  v_name  := trim(v_first || ' ' || v_last);
  v_minor := trim(v_minor_first || ' ' || v_minor_last);

  IF p_template_key NOT IN ('RELEASE_GENERAL','RELEASE_PARTICIPANT',
                            'RELEASE_HORSE_EXERCISE','RELEASE_HORSE_CARE',
                            'FACILITY_RULES','COMPANY_POLICIES',
                            'HUMAN_EMERGENCY_MEDICAL') THEN
    RAISE EXCEPTION 'unknown release template: %', p_template_key;
  END IF;

  v_is_release := (p_template_key LIKE 'RELEASE\_%');

  IF v_is_release AND NOT coalesce(p_rules_acknowledged, false) THEN
    RAISE EXCEPTION 'the facility rules must be acknowledged before signing';
  END IF;
  IF NOT coalesce(p_esign_consent, false) THEN
    RAISE EXCEPTION 'electronic signing consent is required';
  END IF;
  IF v_first = '' THEN
    RAISE EXCEPTION 'a first name is required';
  END IF;
  IF length(v_name) < 2 OR length(v_name) > 200 THEN
    RAISE EXCEPTION 'a name is required (2-200 characters)';
  END IF;
  IF v_typed = '' OR lower(v_typed) <> lower(v_name) THEN
    RAISE EXCEPTION 'typed signature must match the full name exactly';
  END IF;
  IF v_email = '' THEN v_email := NULL; END IF;
  IF v_phone = '' THEN v_phone := NULL; END IF;
  IF v_email IS NULL AND v_phone IS NULL THEN
    RAISE EXCEPTION 'an email address or phone number is required';
  END IF;
  IF v_email IS NOT NULL AND (
       length(v_email) > 320
       OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ) THEN
    RAISE EXCEPTION 'invalid email address';
  END IF;
  IF v_phone IS NOT NULL AND v_phone !~ '^[0-9+().\- ]{7,25}$' THEN
    RAISE EXCEPTION 'invalid phone number';
  END IF;
  IF coalesce(p_is_minor, false) THEN
    IF v_minor_first = '' THEN
      RAISE EXCEPTION 'the minor''s first name is required';
    END IF;
    IF length(v_minor) < 2 OR length(v_minor) > 200 THEN
      RAISE EXCEPTION 'the minor''s name is required (2-200 characters)';
    END IF;
    IF p_minor_dob IS NULL OR p_minor_dob >= current_date THEN
      RAISE EXCEPTION 'a valid date of birth for the minor is required';
    END IF;
    IF p_minor_dob + interval '18 years' <= current_date THEN
      RAISE EXCEPTION 'the named person is not a minor (18 or older); sign the adult release';
    END IF;
    IF length(v_rel) < 2 OR length(v_rel) > 100 THEN
      RAISE EXCEPTION 'the guardian''s relationship to the minor is required (2-100 characters)';
    END IF;
  END IF;

  -- ---- org resolution + transaction-local tenant pin (see 20260702020000) ----
  v_org := coalesce(p_org, current_org(), current_addressed_org(), sole_org());
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no organization addressed (multi-tenant deployments must address a tenant)';
  END IF;
  PERFORM 1 FROM organizations WHERE id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown organization: %', v_org;
  END IF;
  PERFORM set_config('app.current_org', v_org::text, true);

  SELECT a.ip, a.user_agent INTO v_ip, v_ua FROM http_request_attribution() a;

  -- ---- find-or-create the SIGNER's contact (per-org email match) ----
  IF v_email IS NOT NULL THEN
    SELECT id INTO v_contact FROM contacts
      WHERE org_id = v_org AND lower(email) = v_email AND deleted_at IS NULL
      ORDER BY created_at LIMIT 1;
  END IF;
  IF v_contact IS NULL THEN
    INSERT INTO contacts (org_id, first_name, last_name, email, phone,
                          date_of_birth, address_line1, address_line2, city, state, postal_code,
                          emergency_contact_1_name, emergency_contact_1_relationship, emergency_contact_1_phone,
                          emergency_contact_2_name, emergency_contact_2_relationship, emergency_contact_2_phone)
      VALUES (v_org, v_first, NULLIF(v_last, ''), v_email, v_phone,
              p_dob, NULLIF(trim(coalesce(p_address_line1,'')),''), NULLIF(trim(coalesce(p_address_line2,'')),''),
              NULLIF(trim(coalesce(p_city,'')),''), NULLIF(trim(coalesce(p_state,'')),''), NULLIF(trim(coalesce(p_postal_code,'')),''),
              NULLIF(trim(coalesce(p_ec1_name,'')),''), NULLIF(trim(coalesce(p_ec1_relationship,'')),''), NULLIF(trim(coalesce(p_ec1_phone,'')),''),
              NULLIF(trim(coalesce(p_ec2_name,'')),''), NULLIF(trim(coalesce(p_ec2_relationship,'')),''), NULLIF(trim(coalesce(p_ec2_phone,'')),''))
      RETURNING id INTO v_contact;
  ELSE
    UPDATE contacts
       SET first_name = v_first,
           last_name  = NULLIF(v_last, ''),
           phone      = coalesce(nullif(phone, ''), v_phone)
     WHERE id = v_contact
       AND (
         NULLIF(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')), '') IS NULL
         OR lower(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, ''))) = lower(coalesce(email, ''))
       );
    UPDATE contacts SET
        date_of_birth = coalesce(date_of_birth, p_dob),
        address_line1 = coalesce(nullif(address_line1,''), NULLIF(trim(coalesce(p_address_line1,'')),'')),
        address_line2 = coalesce(nullif(address_line2,''), NULLIF(trim(coalesce(p_address_line2,'')),'')),
        city          = coalesce(nullif(city,''), NULLIF(trim(coalesce(p_city,'')),'')),
        state         = coalesce(nullif(state,''), NULLIF(trim(coalesce(p_state,'')),'')),
        postal_code   = coalesce(nullif(postal_code,''), NULLIF(trim(coalesce(p_postal_code,'')),'')),
        emergency_contact_1_name         = coalesce(nullif(emergency_contact_1_name,''), NULLIF(trim(coalesce(p_ec1_name,'')),'')),
        emergency_contact_1_relationship = coalesce(nullif(emergency_contact_1_relationship,''), NULLIF(trim(coalesce(p_ec1_relationship,'')),'')),
        emergency_contact_1_phone        = coalesce(nullif(emergency_contact_1_phone,''), NULLIF(trim(coalesce(p_ec1_phone,'')),'')),
        emergency_contact_2_name         = coalesce(nullif(emergency_contact_2_name,''), NULLIF(trim(coalesce(p_ec2_name,'')),'')),
        emergency_contact_2_relationship = coalesce(nullif(emergency_contact_2_relationship,''), NULLIF(trim(coalesce(p_ec2_relationship,'')),'')),
        emergency_contact_2_phone        = coalesce(nullif(emergency_contact_2_phone,''), NULLIF(trim(coalesce(p_ec2_phone,'')),''))
      WHERE id = v_contact;
  END IF;

  

  -- ---- client shell (CRM: a visitor who signs a release becomes a client) ----
  SELECT id INTO v_client FROM clients
    WHERE contact_id = v_contact AND deleted_at IS NULL;
  IF v_client IS NULL THEN
    INSERT INTO clients (org_id, contact_id, source, client_since)
      VALUES (v_org, v_contact, 'VISITOR_RELEASE', now())
      RETURNING id INTO v_client;
  END IF;

  -- ---- build the spine document_parties roster (NO engagement) ----
  IF coalesce(p_is_minor, false) THEN
    -- Minor path: the minor is the PARTICIPANT party (NOT a signer) — its
    -- presence makes generate_document KEEP the MINOR_* CUT sections and resolve
    -- {{PARTICIPANT.*}} tokens. The parent/guardian signs as CLIENT.
    SELECT id INTO v_minor_c FROM contacts
      WHERE org_id = v_org
        AND lower(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, ''))) = lower(v_minor)
        AND deleted_at IS NULL
      ORDER BY created_at LIMIT 1;
    IF v_minor_c IS NULL THEN
      INSERT INTO contacts (org_id, first_name, last_name, date_of_birth, guardian_contact_id)
        VALUES (v_org, v_minor_first, NULLIF(v_minor_last, ''), p_minor_dob, v_contact)
        RETURNING id INTO v_minor_c;
    ELSE
      UPDATE contacts SET date_of_birth = coalesce(date_of_birth, p_minor_dob),
                          guardian_contact_id = coalesce(guardian_contact_id, v_contact)
        WHERE id = v_minor_c;
    END IF;
    

    v_parties := jsonb_build_array(
      jsonb_build_object('contact_id', v_minor_c, 'role', 'PARTICIPANT', 'is_signer', false),
      jsonb_build_object('contact_id', v_contact, 'role', 'CLIENT', 'is_signer', true,
                         'signer_order', 1, 'relationship', v_rel));
  ELSE
    -- Adult path: the CLIENT signs for themself; no PARTICIPANT party, so
    -- generate_document strips the MINOR_* CUT sections whole.
    v_parties := jsonb_build_array(
      jsonb_build_object('contact_id', v_contact, 'role', 'CLIENT', 'is_signer', true, 'signer_order', 1));
  END IF;

  -- NO COMPANY party: releases are unilateral (owner decision 2026-07-02).

  -- ---- generate through the ONE spine generator (v11): contact-owned, no
  --      engagement, no contract, no horse; document_parties seeded from v_parties ----
  SELECT gd.document_id, gd.merged_body INTO v_doc, v_body
    FROM generate_document(v_contact, p_template_key, NULL::uuid, NULL::uuid, v_parties, NULL::text) gd;
  UPDATE documents SET org_id = v_org, status = 'AWAITING_SIGNATURE' WHERE id = v_doc;

  IF position('{{SIG.CLIENT.NAME}}' IN v_body) = 0 THEN
    RAISE EXCEPTION 'template % is missing its CLIENT signature block', p_template_key;
  END IF;
  v_body := replace(v_body, '{{SIG.CLIENT.NAME}}', v_typed);
  v_body := replace(v_body, '{{SIG.CLIENT.DATE}}', v_today);

  IF v_is_release THEN
    v_body := rtrim(v_body)
      || E'\n\nFACILITY RULES ACKNOWLEDGMENT\n\nSigner acknowledged the Facility Rules and Safety Acknowledgment on '
      || v_today || E'.\n';
  END IF;

  INSERT INTO signatures (org_id, document_id, signer_contact_id, signer_user_id, party_role, typed_name, signed_at, ip_address, user_agent, method)
    VALUES (v_org, v_doc, v_contact, (SELECT pr.user_id FROM profiles pr WHERE pr.contact_id = v_contact LIMIT 1), 'CLIENT', v_typed, now(), v_ip, v_ua, 'KIOSK_TYPED')
    RETURNING signed_at INTO v_signed_at;

  INSERT INTO esign_consents (org_id, contact_id, document_id, ip_address, user_agent)
    VALUES (v_org, v_contact, v_doc, v_ip, v_ua);

  -- executed once EVERY signer party has signed (single signer here) — counted
  -- off document_parties (the spine roster) instead of engagement_parties.
  SELECT count(*) FILTER (WHERE is_signer) INTO v_need
    FROM document_parties WHERE document_id = v_doc;
  SELECT count(*) INTO v_have
    FROM signatures WHERE document_id = v_doc AND signed_at IS NOT NULL AND deleted_at IS NULL;
  IF v_need > 0 AND v_have >= v_need THEN
    v_hash := compute_execution_hash(v_body, v_contact, v_typed, v_signed_at);
    UPDATE documents SET status = 'EXECUTED', effective_date = now()::date,
                         execution_hash = v_hash
      WHERE id = v_doc;
  END IF;

  UPDATE documents SET merged_body = v_body WHERE id = v_doc;

  SELECT status, display_code INTO v_status, v_doc_code FROM documents WHERE id = v_doc;

  RETURN jsonb_build_object(
    'document_id',   v_doc,
    'document_code', v_doc_code,
    'contact_id',    v_contact,
    'status',        v_status,
    'merged_body',   v_body
  );
END;
$_$;


--
-- Name: FUNCTION sign_release(p_template_key text, p_first_name text, p_last_name text, p_email text, p_phone text, p_typed_name text, p_is_minor boolean, p_minor_first_name text, p_minor_last_name text, p_minor_dob date, p_guardian_relationship text, p_rules_acknowledged boolean, p_org uuid, p_esign_consent boolean, p_dob date, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_ec1_name text, p_ec1_relationship text, p_ec1_phone text, p_ec2_name text, p_ec2_relationship text, p_ec2_phone text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sign_release(p_template_key text, p_first_name text, p_last_name text, p_email text, p_phone text, p_typed_name text, p_is_minor boolean, p_minor_first_name text, p_minor_last_name text, p_minor_dob date, p_guardian_relationship text, p_rules_acknowledged boolean, p_org uuid, p_esign_consent boolean, p_dob date, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_ec1_name text, p_ec1_relationship text, p_ec1_phone text, p_ec2_name text, p_ec2_relationship text, p_ec2_phone text) IS 'Public release kiosk (2026-07-07 medical-auth extension): adds HUMAN_EMERGENCY_MEDICAL to the allow-list and twelve optional trailing params (DOB, address parts, two emergency contacts) written fill-blank onto the signer contact so the medical-auth document merges them. All prior behavior preserved from 20260703140000.';


--
-- Name: snapshot_execution_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_execution_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_log jsonb; v_cmt jsonb; v_nlog int; v_ncmt int;
BEGIN
  IF NOT (NEW.workflow_state = 'executed' AND OLD.workflow_state IS DISTINCT FROM 'executed') THEN
    RETURN NEW;
  END IF;

  SELECT coalesce(jsonb_agg(to_jsonb(cl) ORDER BY cl.created_at), '[]'::jsonb), count(*)
    INTO v_log, v_nlog
    FROM contract_change_log cl WHERE cl.document_id = NEW.id;

  SELECT coalesce(jsonb_agg(to_jsonb(cc) ORDER BY cc.created_at), '[]'::jsonb), count(*)
    INTO v_cmt, v_ncmt
    FROM contract_change_requests cc WHERE cc.document_id = NEW.id;

  INSERT INTO contract_execution_audit (
    org_id, document_id, executed_at, execution_hash, merged_body,
    change_log, comments, change_count, comment_count)
  VALUES (
    NEW.org_id, NEW.id, now(), NEW.execution_hash, NEW.merged_body,
    coalesce(v_log,'[]'::jsonb), coalesce(v_cmt,'[]'::jsonb),
    coalesce(v_nlog,0), coalesce(v_ncmt,0))
  ON CONFLICT (document_id) DO NOTHING;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


--
-- Name: sole_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sole_org() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN (SELECT count(*) FROM organizations) = 1
              THEN (SELECT id FROM organizations LIMIT 1) END
$$;


--
-- Name: FUNCTION sole_org(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sole_org() IS 'The lone organization when exactly one exists (single-tenant launch fallback for public intake); NULL once a second tenant is provisioned — unaddressed anon writes then fail loudly.';


--
-- Name: staff_assign_documents(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_assign_documents(p_contact_id uuid, p_template_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_assigned text[] := '{}';
  v_resign   text[] := '{}';
  k          text;
  r          record;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact not found'; END IF;

  FOREACH k IN ARRAY coalesce(p_template_keys, '{}') LOOP
    IF NOT EXISTS (SELECT 1 FROM staff_assignable_templates(p_contact_id) t WHERE t.template_key = k) THEN
      RAISE EXCEPTION 'template % is not assignable (inactive, clause-engine, or not the current version)', k;
    END IF;

    INSERT INTO contact_required_documents (contact_id, template_key, org_id)
    VALUES (p_contact_id, k, v_org)
    ON CONFLICT DO NOTHING;
    v_assigned := v_assigned || k;

    -- Re-sign: every executed, non-superseded copy that would still satisfy the
    -- requirement is superseded (retained as evidence), so the assignment
    -- ALWAYS produces a pending requirement.
    FOR r IN
      SELECT d.id FROM documents d
      JOIN contract_templates ct ON ct.id = d.template_id
      WHERE d.contact_id = p_contact_id AND d.deleted_at IS NULL
        AND d.status = 'EXECUTED'
        AND coalesce(d.current_status, '') <> 'superseded'
        AND ct.template_key = k
    LOOP
      UPDATE documents SET current_status = 'superseded' WHERE id = r.id;
      PERFORM log_status_event('document', r.id, 'superseded',
        'Re-assigned for signature by staff', v_org);
      IF NOT (k = ANY (v_resign)) THEN v_resign := v_resign || k; END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'assigned', to_jsonb(v_assigned),
    'resign',   to_jsonb(v_resign));
END;
$$;


--
-- Name: staff_assign_horse_party(uuid, text, uuid, date, date, boolean, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_assign_horse_party(p_horse_id uuid, p_role text, p_contact_id uuid, p_term_start date DEFAULT NULL::date, p_term_end date DEFAULT NULL::date, p_sublease_allowed boolean DEFAULT false, p_share_pct numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF p_role NOT IN ('OWNER','LESSEE','TRAINER','CARETAKER','BOARDER') THEN
    RAISE EXCEPTION 'role must be OWNER, LESSEE, TRAINER, CARETAKER, or BOARDER';
  END IF;

  -- OWNER/LESSEE keep their exclusive semantics + horses-column side effects
  -- (live behavior, unchanged). The ledger roles are plain additive rows.
  IF p_role = 'OWNER' THEN
    UPDATE horse_relationships SET active = false, ended_at = now()
     WHERE horse_id = p_horse_id AND relationship = 'OWNER' AND active
       AND (p_contact_id IS NULL OR party_contact_id IS DISTINCT FROM p_contact_id);
    UPDATE horses SET current_owner_contact_id = p_contact_id, updated_at = now()
     WHERE id = p_horse_id AND org_id = v_org;
  ELSIF p_role = 'LESSEE' THEN
    UPDATE horse_relationships SET active = false, ended_at = now()
     WHERE horse_id = p_horse_id AND relationship = 'LESSEE' AND active
       AND (p_contact_id IS NULL OR party_contact_id IS DISTINCT FROM p_contact_id);
    UPDATE horses
       SET lessee_contact_id = p_contact_id,
           lease_start = CASE WHEN p_contact_id IS NULL THEN NULL ELSE coalesce(p_term_start, lease_start) END,
           lease_end   = CASE WHEN p_contact_id IS NULL THEN NULL ELSE coalesce(p_term_end, lease_end) END,
           sublease_allowed = CASE WHEN p_contact_id IS NULL THEN false ELSE p_sublease_allowed END,
           updated_at = now()
     WHERE id = p_horse_id AND org_id = v_org;
  END IF;

  IF p_contact_id IS NOT NULL THEN
    INSERT INTO horse_relationships
      (org_id, horse_id, relationship, party_contact_id, term_start, term_end,
       share_pct, notes, created_by_contact_id)
    VALUES (v_org, p_horse_id, p_role, p_contact_id, p_term_start, p_term_end,
            p_share_pct, p_notes, current_contact_id());
  END IF;
END;
$$;


--
-- Name: staff_assignable_templates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_assignable_templates(p_contact_id uuid) RETURNS TABLE(template_key text, title text, version integer, wall_gating boolean, on_file_status text, on_file_date date, on_file_version integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ct.template_key, ct.title, ct.version, ct.wall_gating,
         CASE WHEN d.id IS NULL THEN 'none'
              WHEN d.current_status = 'superseded' THEN 'superseded'
              ELSE 'executed' END,
         d.exec_date, d.version
    FROM contract_templates ct
    LEFT JOIN LATERAL (
      SELECT dd.id, dd.current_status, dd.created_at::date AS exec_date, ct2.version
        FROM documents dd JOIN contract_templates ct2 ON ct2.id = dd.template_id
       WHERE dd.contact_id = p_contact_id AND dd.deleted_at IS NULL
         AND dd.status = 'EXECUTED' AND ct2.template_key = ct.template_key
       ORDER BY (dd.current_status IS DISTINCT FROM 'superseded') DESC, dd.created_at DESC
       LIMIT 1
    ) d ON true
   WHERE has_staff_access()
     AND ct.active AND ct.deleted_at IS NULL
     AND ct.body IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM contract_section_defs s WHERE s.template_key = ct.template_key)
     AND ct.version = (SELECT max(x.version) FROM contract_templates x
                        WHERE x.template_key = ct.template_key AND x.active AND x.deleted_at IS NULL)
   ORDER BY ct.wall_gating DESC, ct.title;
$$;


--
-- Name: staff_contact_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_contact_directory() RETURNS TABLE(id uuid, display_code text, first_name text, last_name text, email text, phone text, tags text[], notes text, created_at timestamp with time zone, linked_user_id uuid, linked_role text, is_client boolean, party_roles text[], horses_owned bigint, horses_leased bigint, engagement_count bigint, document_count bigint, contact_type text, is_company boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, c.display_code, c.first_name, c.last_name,
         c.email, c.phone, c.tags, c.notes, c.created_at,
         p.user_id, p.role,
         EXISTS (SELECT 1 FROM clients cl
                  WHERE cl.contact_id = c.id AND cl.deleted_at IS NULL),
         (SELECT coalesce(array_agg(DISTINCT dp.party_role), '{}')
            FROM document_parties dp WHERE dp.contact_id = c.id),
         (SELECT count(*) FROM horses h
           WHERE h.current_owner_contact_id = c.id AND h.deleted_at IS NULL),
         (SELECT count(*) FROM horses h
           WHERE h.lessee_contact_id = c.id AND h.deleted_at IS NULL),
         0::bigint,
         (SELECT count(DISTINCT d.id)
            FROM documents d
           WHERE d.deleted_at IS NULL
             AND (d.contact_id = c.id
                  OR EXISTS (SELECT 1 FROM document_parties dp
                              WHERE dp.document_id = d.id AND dp.contact_id = c.id))),
         c.contact_type,
         coalesce(c.is_company, false)
  FROM contacts c
  LEFT JOIN profiles p ON p.contact_id = c.id
  WHERE c.org_id = current_org()
    AND c.deleted_at IS NULL
    AND has_staff_access()
  ORDER BY c.last_name NULLS LAST, c.first_name
$$;


--
-- Name: FUNCTION staff_contact_directory(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.staff_contact_directory() IS 'Every contact in the org, for the staff person-pages. `contact_type` is the page discriminator (LEAD | CONTACT | TEAM | DIRECTORY) — an EXPLICIT stored value, not a derived leftover. A NULL contact_type means unclassified and is surfaced deliberately so a human can file it, rather than being defaulted into a bucket and forgotten.';


--
-- Name: staff_contact_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_contact_options() RETURNS TABLE(id uuid, name text, email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, trim(concat_ws(' ', c.first_name, c.last_name)), c.email
  FROM contacts c
  WHERE c.org_id = current_org() AND c.deleted_at IS NULL AND has_staff_access()
  ORDER BY c.last_name NULLS LAST, c.first_name
$$;


--
-- Name: staff_end_horse_relationship(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_end_horse_relationship(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  UPDATE horse_relationships SET active = false, ended_at = now()
   WHERE id = p_id AND org_id = current_org() AND active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'relationship not found or already ended';
  END IF;
END;
$$;


--
-- Name: staff_evaluation_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_evaluation_reports() RETURNS TABLE(id uuid, contact_id uuid, title text, horse_label text, status text, delivered_at timestamp with time zone, available_until timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.id, r.contact_id, r.title, r.horse_label, r.status,
         r.delivered_at, r.available_until, r.created_at
    FROM evaluation_reports r
   WHERE r.deleted_at IS NULL AND r.org_id = current_org()
     AND has_staff_access()
   ORDER BY r.created_at DESC;
$$;


--
-- Name: staff_horse_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_horse_records() RETURNS TABLE(id uuid, registered_name text, nickname text, breed text, color text, markings text, sex text, date_of_birth date, height text, registration_number text, registration_org text, microchip_id text, current_location text, fair_market_value numeric, vet_name text, vet_phone text, farrier_name text, farrier_phone text, owner_contact_id uuid, owner_name text, owner_name_text text, lessee_contact_id uuid, lessee_name text, lessee_name_text text, lease_start date, lease_end date, document_count bigint, active_lease_doc jsonb, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT h.id, h.registered_name, h.nickname, h.breed, h.color,
         h.markings, h.sex, h.date_of_birth, h.height,
         h.registration_number, h.registration_org, h.microchip_id,
         h.current_location, h.fair_market_value,
         h.vet_name, h.vet_phone, h.farrier_name, h.farrier_phone,
         h.current_owner_contact_id,
         (SELECT trim(concat_ws(' ', c.first_name, c.last_name)) FROM contacts c WHERE c.id = h.current_owner_contact_id),
         h.owner_name_text,
         h.lessee_contact_id,
         (SELECT trim(concat_ws(' ', c.first_name, c.last_name)) FROM contacts c WHERE c.id = h.lessee_contact_id),
         h.lessee_name_text,
         h.lease_start, h.lease_end,
         (SELECT count(*) FROM horse_relationships r
           WHERE r.horse_id = h.id AND r.source_document_id IS NOT NULL),
         horse_active_lease_doc(h.id) AS active_lease_doc,
         h.created_at
  FROM horses h
  WHERE h.org_id = current_org() AND h.deleted_at IS NULL AND has_staff_access()
  ORDER BY coalesce(h.nickname, h.registered_name)
$$;


--
-- Name: staff_request_horse_record_completion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_request_horse_record_completion(p_horse_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_horse horses%ROWTYPE;
  v_user  uuid;
  v_name  text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT * INTO v_horse FROM horses WHERE id = p_horse_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown horse'; END IF;
  SELECT p.user_id INTO v_user FROM profiles p WHERE p.contact_id = v_horse.current_owner_contact_id;
  IF v_user IS NULL THEN RAISE EXCEPTION 'the horse''s owner has no account to notify'; END IF;
  v_name := coalesce(nullif(btrim(v_horse.nickname), ''), v_horse.registered_name, 'your horse');
  RETURN notify_user(
    v_user,
    'horse_record_task',
    'Complete ' || v_name || '''s record',
    'A few details are still needed on ' || v_name || '''s record so their care paperwork can be completed. It only takes a couple of minutes.',
    '/app/horse-intake?horse=' || p_horse_id::text);
END;
$$;


--
-- Name: staff_update_horse(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_update_horse(p_id uuid, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  UPDATE horses SET
    registered_name     = coalesce(nullif(p ->> 'registered_name', ''), registered_name),
    nickname           = CASE WHEN p ? 'nickname' THEN nullif(p ->> 'nickname', '') ELSE nickname END,
    breed               = CASE WHEN p ? 'breed' THEN nullif(p ->> 'breed', '') ELSE breed END,
    color               = CASE WHEN p ? 'color' THEN nullif(p ->> 'color', '') ELSE color END,
    markings            = CASE WHEN p ? 'markings' THEN nullif(p ->> 'markings', '') ELSE markings END,
    sex                 = CASE WHEN p ? 'sex' THEN nullif(p ->> 'sex', '') ELSE sex END,
    height              = CASE WHEN p ? 'height' THEN nullif(p ->> 'height', '') ELSE height END,
    current_location    = CASE WHEN p ? 'current_location' THEN nullif(p ->> 'current_location', '') ELSE current_location END,
    fair_market_value   = CASE WHEN p ? 'fair_market_value'
                               THEN nullif(replace(replace(p ->> 'fair_market_value', '$', ''), ',', ''), '')::numeric
                               ELSE fair_market_value END,
    vet_name            = CASE WHEN p ? 'vet_name' THEN nullif(p ->> 'vet_name', '') ELSE vet_name END,
    vet_phone           = CASE WHEN p ? 'vet_phone' THEN nullif(p ->> 'vet_phone', '') ELSE vet_phone END,
    farrier_name        = CASE WHEN p ? 'farrier_name' THEN nullif(p ->> 'farrier_name', '') ELSE farrier_name END,
    farrier_phone       = CASE WHEN p ? 'farrier_phone' THEN nullif(p ->> 'farrier_phone', '') ELSE farrier_phone END,
    updated_at = now()
  WHERE id = p_id AND org_id = current_org() AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'horse not found in this org'; END IF;
END;
$_$;


--
-- Name: start_bill_of_sale(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_bill_of_sale(p_sale_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale     documents%ROWTYPE;
  v_tkey     text;
  v_doc      uuid;
  v_anchor   uuid;
  v_installments text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to generate a bill of sale'; END IF;

  SELECT * INTO v_sale FROM documents WHERE id = p_sale_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_sale_document_id; END IF;
  SELECT template_key INTO v_tkey FROM contract_templates WHERE id = v_sale.template_id;
  IF v_tkey <> 'HORSE_SALE_V2' THEN
    RAISE EXCEPTION 'a bill of sale is generated from a HORSE_SALE_V2 document (got %)', v_tkey;
  END IF;

  SELECT contact_id INTO v_anchor FROM document_parties
   WHERE document_id = p_sale_document_id AND party_role = 'BUYER'
   ORDER BY signer_order NULLS LAST, id LIMIT 1;
  IF v_anchor IS NULL THEN v_anchor := v_sale.contact_id; END IF;

  -- parties mirror the SALE DOCUMENT's parties (co-buyer + signer_order carried)
  v_doc := bos_generate_document(
    v_sale.contract_id, v_anchor, v_sale.horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',dp.contact_id,'role',dp.party_role,'is_signer',dp.is_signer,'signer_order',dp.signer_order))
       FROM document_parties dp WHERE dp.document_id = p_sale_document_id));

  -- prefill every shared field from the sale document's values (parties, horse,
  -- price, co-buyer set) — same field_keys by design; still editable before signing
  UPDATE contract_fields b
     SET value = s.value, updated_at = now()
    FROM contract_fields s
   WHERE b.document_id = v_doc
     AND s.document_id = p_sale_document_id
     AND s.field_key = b.field_key
     AND coalesce(btrim(s.value), '') <> ''
     AND coalesce(btrim(b.value), '') = '';

  UPDATE contract_fields SET value = 'YES'
   WHERE document_id = v_doc AND field_key = 'TXN.BOS_HAS_SALE_AGREEMENT';

  -- payment status derives from the sale's installment election (still editable)
  SELECT coalesce(btrim(value), '') INTO v_installments
    FROM contract_fields
   WHERE document_id = p_sale_document_id AND field_key = 'TXN.INSTALLMENTS_ENABLED';
  UPDATE contract_fields
     SET value = CASE v_installments WHEN 'YES' THEN 'INSTALLMENTS'
                                     WHEN 'NO'  THEN 'PAID_IN_FULL'
                                     ELSE '' END
   WHERE document_id = v_doc AND field_key = 'TXN.BOS_PAYMENT_STATUS';

  IF v_sale.horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, v_sale.horse_id);
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_sale.contract_id);
END;
$$;


--
-- Name: start_bill_of_sale_standalone(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_bill_of_sale_standalone(p_buyer_contact_id uuid, p_seller_contact_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_contract uuid;
  v_doc      uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to start a bill of sale'; END IF;
  IF p_buyer_contact_id IS NULL THEN RAISE EXCEPTION 'a buyer contact is required'; END IF;

  SELECT org_id INTO v_org FROM contacts WHERE id = p_buyer_contact_id;

  INSERT INTO contracts (org_id, segment, status, horse_id, originator_contact_id, terms)
    VALUES (v_org, 'acquisition', 'draft', p_horse_id, current_contact_id(), jsonb_build_object('deal_side','SALE'))
    RETURNING id INTO v_contract;
  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_org, v_contract, p_buyer_contact_id, 'BUYER', true, 1);
  IF p_seller_contact_id IS NOT NULL THEN
    INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, v_contract, p_seller_contact_id, 'SELLER', true, 2);
  END IF;

  v_doc := bos_generate_document(
    v_contract, p_buyer_contact_id, p_horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',cp.contact_id,'role',cp.party_role,'is_signer',cp.is_signer,'signer_order',cp.signer_order))
       FROM contract_parties cp WHERE cp.contract_id = v_contract));

  UPDATE contract_fields SET value = 'NO'
   WHERE document_id = v_doc AND field_key = 'TXN.BOS_HAS_SALE_AGREEMENT';

  IF p_horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, p_horse_id);
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_contract);
END;
$$;


--
-- Name: start_lease_contract_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_lease_contract_v2(p_lessee_contact_id uuid, p_lessor_contact_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid, p_responsible_role text DEFAULT 'LESSEE'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract   uuid;
  v_org        uuid;
  v_doc        uuid;
  v_tmpl       uuid;
  v_originator uuid;
  v_n          int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to start a lease contract'; END IF;
  IF p_lessee_contact_id IS NULL THEN RAISE EXCEPTION 'a lessee contact is required'; END IF;

  v_originator := current_contact_id();  -- H1: the company (staff caller) is always the author

  SELECT org_id INTO v_org FROM contacts WHERE id = p_lessee_contact_id;
  SELECT id INTO v_tmpl FROM contract_templates WHERE template_key = 'HORSE_LEASE_V2';
  IF v_tmpl IS NULL THEN RAISE EXCEPTION 'HORSE_LEASE_V2 template missing'; END IF;

  -- contract + parties (spine model)
  INSERT INTO contracts (org_id, segment, status, horse_id, originator_contact_id, terms)
    VALUES (v_org, 'acquisition', 'draft', p_horse_id, v_originator, jsonb_build_object('deal_side','LEASE_IN'))
    RETURNING id INTO v_contract;
  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_org, v_contract, p_lessee_contact_id, 'LESSEE', true, 1);
  IF p_lessor_contact_id IS NOT NULL THEN
    INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, v_contract, p_lessor_contact_id, 'LESSOR', true, 2);
  END IF;

  -- document shell (same generator the engine uses; body recomposed below)
  SELECT gd.document_id INTO v_doc FROM generate_document(
    p_lessee_contact_id, 'HORSE_LEASE_V2', v_contract, p_horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',cp.contact_id,'role',cp.party_role,'is_signer',cp.is_signer,'signer_order',cp.signer_order))
       FROM contract_parties cp WHERE cp.contract_id = v_contract),
    NULL::text) gd;

  UPDATE documents SET originator_contact_id = v_originator,
                       workflow_state = 'editable', status = 'AWAITING_SIGNATURE'
   WHERE id = v_doc;

  -- seed fields straight from the clause-model defs (clause_key + responsibility_kind carried)
  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key,
    responsibility_kind)
  SELECT v_org, v_doc, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on, d.closed, d.guidance,
         d.required, d.is_optional, d.responsibility, d.sort_order, d.parent_field_key,
         d.responsibility_kind
    FROM contract_field_defs d
   WHERE d.template_key = 'HORSE_LEASE_V2';
  GET DIAGNOSTICS v_n = ROW_COUNT;

  -- fill horse + party identity fields from records (reuse verified paths)
  IF p_horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, p_horse_id);
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);

  -- compose the numbered clause body
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_contract, 'fields_seeded', v_n);
END;
$$;


--
-- Name: start_sale_contract(uuid, uuid, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_sale_contract(p_buyer_contact_id uuid, p_seller_contact_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT NULL::numeric, p_deposit numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract   uuid;
  v_org        uuid;
  v_doc        uuid;
  v_tmpl       uuid;
  v_originator uuid;
  v_n          int;
  v_horse      horses%ROWTYPE;
  v_lessee_nm  text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to start a sale contract'; END IF;
  IF p_buyer_contact_id IS NULL THEN RAISE EXCEPTION 'a buyer contact is required'; END IF;

  v_originator := current_contact_id();  -- H1: the company (staff caller) is always the author

  SELECT org_id INTO v_org FROM contacts WHERE id = p_buyer_contact_id;
  SELECT id INTO v_tmpl FROM contract_templates WHERE template_key = 'HORSE_SALE_V2';
  IF v_tmpl IS NULL THEN RAISE EXCEPTION 'HORSE_SALE_V2 template missing'; END IF;

  -- contract + parties (spine model)
  INSERT INTO contracts (org_id, segment, status, horse_id, originator_contact_id, terms)
    VALUES (v_org, 'acquisition', 'draft', p_horse_id, v_originator, jsonb_build_object('deal_side','SALE'))
    RETURNING id INTO v_contract;
  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_org, v_contract, p_buyer_contact_id, 'BUYER', true, 1);
  IF p_seller_contact_id IS NOT NULL THEN
    INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, v_contract, p_seller_contact_id, 'SELLER', true, 2);
  END IF;

  -- document shell (same generator the engine uses; body recomposed below)
  SELECT gd.document_id INTO v_doc FROM generate_document(
    p_buyer_contact_id, 'HORSE_SALE_V2', v_contract, p_horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',cp.contact_id,'role',cp.party_role,'is_signer',cp.is_signer,'signer_order',cp.signer_order))
       FROM contract_parties cp WHERE cp.contract_id = v_contract),
    NULL::text) gd;

  UPDATE documents SET originator_contact_id = v_originator,
                       workflow_state = 'editable', status = 'AWAITING_SIGNATURE'
   WHERE id = v_doc;

  -- seed fields straight from the clause-model defs (clause_key + responsibility_kind carried)
  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key,
    responsibility_kind)
  SELECT v_org, v_doc, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on, d.closed, d.guidance,
         d.required, d.is_optional, d.responsibility, d.sort_order, d.parent_field_key,
         d.responsibility_kind
    FROM contract_field_defs d
   WHERE d.template_key = 'HORSE_SALE_V2';
  GET DIAGNOSTICS v_n = ROW_COUNT;

  -- deal terms handed in at start
  IF p_amount IS NOT NULL THEN
    UPDATE contract_fields SET value = p_amount::text
     WHERE document_id = v_doc AND field_key = 'TXN.PURCHASE_PRICE';
  END IF;
  IF p_deposit IS NOT NULL THEN
    UPDATE contract_fields SET value = p_deposit::text
     WHERE document_id = v_doc AND field_key = 'TXN.DEPOSIT_AMOUNT';
    UPDATE contract_fields SET value = 'YES'
     WHERE document_id = v_doc AND field_key = 'TXN.DEPOSIT_ENABLED';
  END IF;

  -- fill horse + party identity fields from records (reuse verified paths)
  IF p_horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, p_horse_id);
    SELECT * INTO v_horse FROM horses WHERE id = p_horse_id;

    -- seller-disclosure seed from the record (attach fills HORSE.* only)
    UPDATE contract_fields
       SET value = coalesce(horse_field_token_value(v_horse, 'KNOWN_CONDITIONS'), '')
     WHERE document_id = v_doc AND field_key = 'TXN.KNOWN_CONDITIONS'
       AND coalesce(btrim(value), '') = ''
       AND coalesce(horse_field_token_value(v_horse, 'KNOWN_CONDITIONS'), '') <> '';

    -- owner ruling: an actively-leased horse is sellable; prefill the
    -- encumbrances election toward YES identifying the lease (still editable).
    IF v_horse.lessee_contact_id IS NOT NULL
       AND (v_horse.lease_end IS NULL OR v_horse.lease_end >= current_date) THEN
      SELECT nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), '')
        INTO v_lessee_nm FROM contacts c WHERE c.id = v_horse.lessee_contact_id;
      UPDATE contract_fields SET value = 'YES'
       WHERE document_id = v_doc AND field_key = 'TXN.HAS_ENCUMBRANCES'
         AND coalesce(btrim(value), '') = '';
      UPDATE contract_fields
         SET value = 'The Horse is currently under an active lease to '
                     || coalesce(v_lessee_nm, 'the lessee of record')
                     || coalesce(' through ' || to_char(v_horse.lease_end, 'FMMonth FMDD, YYYY'), '')
                     || '.'
       WHERE document_id = v_doc AND field_key = 'TXN.DISCLOSED_ENCUMBRANCES'
         AND coalesce(btrim(value), '') = '';
    END IF;
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);

  -- compose the numbered clause body
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_contract, 'fields_seeded', v_n);
END;
$$;


--
-- Name: status_feed(text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.status_feed(p_entity_type text DEFAULT NULL::text, p_true_only boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS TABLE(entity_type text, entity_id uuid, status text, display_name text, is_true_status boolean, detail text, actor_user_id uuid, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.entity_type, e.entity_id, e.status, v.display_name, v.is_true_status,
         e.detail, e.actor_user_id, e.created_at
    FROM status_events e
    JOIN status_events_vocab v ON v.entity_type = e.entity_type AND v.code = e.status
   WHERE has_staff_access() AND e.org_id = current_org()
     AND (p_entity_type IS NULL OR e.entity_type = p_entity_type)
     AND (NOT p_true_only OR v.is_true_status)
   ORDER BY e.created_at DESC
   LIMIT greatest(1, least(coalesce(p_limit, 100), 500));
$$;


--
-- Name: submit_acquisition_intake(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_acquisition_intake(p_purchase_item_id uuid, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_org     uuid;
  v_owns    boolean;
BEGIN
  IF v_contact IS NULL THEN RAISE EXCEPTION 'sign in to submit intake'; END IF;

  -- the line must belong to a purchase this member owns (contact or user grain)
  SELECT pu.org_id, true INTO v_org, v_owns
    FROM purchase_items pi
    JOIN purchases pu ON pu.id = pi.purchase_id
   WHERE pi.id = p_purchase_item_id
     AND (pu.buyer_contact_id = v_contact OR pu.buyer_user_id = auth.uid());
  IF NOT coalesce(v_owns, false) THEN RAISE EXCEPTION 'that purchase is not yours'; END IF;

  UPDATE purchase_items
     SET config = coalesce(config, '{}'::jsonb)
                  || coalesce(p_data, '{}'::jsonb)
                  || jsonb_build_object('submitted_at', now())
   WHERE id = p_purchase_item_id;

  -- let staff know the brief/intake is in
  PERFORM notify_staff(v_org, 'acquisition_intake_submitted',
    'A client submitted their acquisition intake', '/app/ops/oversight');

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: submit_change_requests(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_change_requests(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_title text; v_cid uuid;
  v_next int; v_n int := 0; r record;
  v_top jsonb; v_body text; v_ids uuid[] := '{}';
  v_party record; v_me_label text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, workflow_state, coalesce(title,'A contract')
    INTO v_org, v_state, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF NOT ((has_staff_access() AND v_org = current_org())
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this document is % — it is no longer open to change requests', v_state;
  END IF;

  SELECT contact_id, label INTO v_cid, v_me_label FROM comment_author_identity(p_document_id);

  SELECT coalesce(max(annotation_number), 0) INTO v_next
    FROM contract_change_requests WHERE document_id = p_document_id;

  -- lock every unsubmitted draft this caller authored
  FOR r IN
    SELECT id FROM contract_change_requests
     WHERE document_id = p_document_id AND parent_request_id IS NULL
       AND author_contact_id = v_cid AND submitted_at IS NULL
     ORDER BY created_at
  LOOP
    v_next := v_next + 1; v_n := v_n + 1;
    UPDATE contract_change_requests
       SET submitted_at = now(), annotation_number = v_next, updated_at = now()
     WHERE id = r.id;
    v_ids := v_ids || r.id;
  END LOOP;

  IF v_n = 0 THEN
    RETURN jsonb_build_object('submitted', 0, 'notified', 0);
  END IF;

  -- the FIVE highest-impact requests just submitted (impact desc, then earliest)
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'annotation_number', t.annotation_number,
           'target_section', t.target_section,
           'heading', t.heading,
           'impact_rank', t.impact_rank,
           'body', t.body) ORDER BY t.impact_rank DESC, t.annotation_number), '[]'::jsonb)
    INTO v_top
    FROM (
      SELECT cr.annotation_number, cr.target_section, cr.impact_rank, cr.body,
             coalesce(sd.heading, 'The whole document') AS heading
        FROM contract_change_requests cr
        LEFT JOIN documents d ON d.id = cr.document_id
        LEFT JOIN contract_templates ct ON ct.id = d.template_id
        LEFT JOIN contract_section_defs sd
               ON sd.template_key = ct.template_key AND sd.section_key = cr.target_section
       WHERE cr.id = ANY(v_ids)
       ORDER BY cr.impact_rank DESC, cr.annotation_number
       LIMIT 5
    ) t;

  SELECT string_agg('#' || (e->>'annotation_number') || ' ' || (e->>'heading') || ' — ' ||
                    left(e->>'body', 160), E'\n' ORDER BY ord)
    INTO v_body
    FROM jsonb_array_elements(v_top) WITH ORDINALITY AS x(e, ord);

  -- notify every OTHER party (dashboard notification via contract_notify, which
  -- resolves the contact's app user and links back to this document).
  FOR v_party IN
    SELECT DISTINCT dp.contact_id
      FROM document_parties dp
     WHERE dp.document_id = p_document_id
       AND dp.contact_id IS DISTINCT FROM v_cid
  LOOP
    PERFORM contract_notify(p_document_id, v_party.contact_id,
      'contract_change_requested',
      coalesce(v_me_label,'A party') || ' submitted ' || v_n || ' change request'
        || CASE WHEN v_n = 1 THEN '' ELSE 's' END || ' on ' || v_title,
      v_body);
  END LOOP;

  RETURN jsonb_build_object(
    'submitted', v_n,
    'top', v_top,
    'notify_parties', coalesce((
      SELECT jsonb_agg(DISTINCT dp.contact_id)
        FROM document_parties dp
       WHERE dp.document_id = p_document_id
         AND dp.contact_id IS DISTINCT FROM v_cid), '[]'::jsonb));
END;
$$;


--
-- Name: submit_public_request(text, text, text, text, text, text, jsonb, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_public_request(p_first_name text, p_last_name text, p_email text, p_phone text DEFAULT NULL::text, p_contact_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_proposed_times jsonb DEFAULT '[]'::jsonb, p_category text DEFAULT NULL::text, p_channel text DEFAULT 'contact'::text, p_entry_location text DEFAULT NULL::text, p_intent text DEFAULT NULL::text, p_selections jsonb DEFAULT '[]'::jsonb, p_details jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org   uuid := coalesce(current_org(), current_addressed_org(), sole_org());
  v_first text := NULLIF(btrim(coalesce(p_first_name, '')), '');
  v_last  text := NULLIF(btrim(coalesce(p_last_name, '')), '');
  v_email text := lower(NULLIF(btrim(coalesce(p_email, '')), ''));
  v_phone text := NULLIF(btrim(coalesce(p_phone, '')), '');
  v_notes text := NULLIF(btrim(coalesce(p_notes, '')), '');
  v_details jsonb := CASE WHEN jsonb_typeof(p_details) = 'object' THEN p_details ELSE '{}'::jsonb END;
  v_id    uuid;
  v_sel   jsonb;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'could not resolve an organization for this request';
  END IF;
  IF v_first IS NULL THEN RAISE EXCEPTION 'first name is required'; END IF;
  IF v_last  IS NULL THEN RAISE EXCEPTION 'last name is required'; END IF;
  IF v_email IS NULL THEN RAISE EXCEPTION 'email is required'; END IF;
  IF v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'that email address does not look valid';
  END IF;
  IF v_phone IS NOT NULL AND v_phone !~ '^[-+().0-9[:space:]]{7,32}$' THEN
    RAISE EXCEPTION 'that phone number does not look valid';
  END IF;
  IF v_notes IS NOT NULL AND char_length(v_notes) > 4000 THEN
    RAISE EXCEPTION 'your message is too long (max 4000 characters)';
  END IF;
  IF p_contact_method IS NOT NULL AND p_contact_method NOT IN ('text','call','email') THEN
    RAISE EXCEPTION 'invalid contact method';
  END IF;

  INSERT INTO requests (
    org_id, status, contact_name, contact_first_name, contact_last_name,
    contact_email, contact_phone, contact_method, proposed_times, notes,
    category, channel, entry_location, intent, details
  ) VALUES (
    v_org, 'new', v_first || ' ' || v_last, v_first, v_last,
    v_email, v_phone, p_contact_method, coalesce(p_proposed_times, '[]'::jsonb), v_notes,
    p_category, coalesce(p_channel, 'contact'), p_entry_location, p_intent, v_details
  )
  RETURNING id INTO v_id;

  -- cart selections (Checkout) — resolve each offering slug to its row in-tenant.
  FOR v_sel IN SELECT * FROM jsonb_array_elements(coalesce(p_selections, '[]'::jsonb))
  LOOP
    INSERT INTO request_selections (request_id, org_id, offering_id, offering_slug, label)
    SELECT v_id, v_org, o.id, (v_sel->>'offering_slug'), (v_sel->>'label')
      FROM offerings o
      WHERE o.slug = (v_sel->>'offering_slug') AND o.org_id = v_org
      LIMIT 1;
    IF NOT FOUND THEN
      INSERT INTO request_selections (request_id, org_id, offering_slug, label)
        VALUES (v_id, v_org, (v_sel->>'offering_slug'), (v_sel->>'label'));
    END IF;
  END LOOP;

  -- alert the barn: in-app to every staff/owner (mirrored to co-admins by the
  -- notifications trigger). Email is sent separately by the /api/request-received
  -- endpoint the public form calls after this returns.
  PERFORM notify_staff(
    v_org, 'request_new',
    'New inquiry from ' || coalesce(nullif(btrim(v_first || ' ' || v_last), ''), v_email),
    '/app/ops/intake');

  RETURN jsonb_build_object('request_id', v_id, 'status', 'new');
END;
$_$;


--
-- Name: submit_support_request(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_support_request(p_subject text, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_id  uuid;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no org context';
  END IF;
  IF p_subject IS NULL OR btrim(p_subject) = '' OR p_body IS NULL OR btrim(p_body) = '' THEN
    RAISE EXCEPTION 'subject and message are required';
  END IF;

  INSERT INTO support_requests (org_id, user_id, subject, body)
  VALUES (v_org, auth.uid(), btrim(p_subject), btrim(p_body))
  RETURNING id INTO v_id;

  -- alert the barn: in-app to every staff/owner (co-admins get it via the
  -- notifications mirror trigger). No email — support is an in-app channel.
  PERFORM notify_staff(
    v_org, 'support_new',
    'New support request: ' || left(btrim(p_subject), 80),
    '/app/ops/support');

  RETURN v_id;
END;
$$;


--
-- Name: suggested_category_for_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggested_category_for_contact(p_contact_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH signed AS (
    SELECT DISTINCT t.template_key
    FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
    JOIN contract_templates t ON t.id = d.template_id
    WHERE dp.contact_id = p_contact_id
  )
  SELECT jsonb_build_object(
    'suggested', CASE
      WHEN EXISTS (SELECT 1 FROM signed WHERE template_key IN ('RELEASE_HORSE_CARE','HORSE_EMERGENCY_VET'))
        THEN 'HORSE_OWNER'
      WHEN EXISTS (SELECT 1 FROM signed WHERE template_key IN ('RELEASE_PARTICIPANT','RIDER_LESSON','RIDER_LESSON_JUMPER','MINOR_RIDER'))
        THEN 'RIDER'
      ELSE 'GUEST'
    END,
    'executed_templates', coalesce((SELECT array_agg(template_key ORDER BY template_key) FROM signed), ARRAY[]::text[])
  );
$$;


--
-- Name: supersede_invitations(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supersede_invitations(p_org uuid, p_email text, p_new_invitation_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
BEGIN
  WITH superseded AS (
    UPDATE invitations
       SET status = 'superseded', superseded_by = p_new_invitation_id
     WHERE org_id = p_org
       AND lower(email) = lower(p_email)
       AND id <> p_new_invitation_id
       AND status = 'sent'
       AND deleted_at IS NULL
    RETURNING 1)
  SELECT count(*) INTO v_count FROM superseded;

  UPDATE invitations SET resend_of = (
    SELECT id FROM invitations
     WHERE org_id = p_org AND lower(email) = lower(p_email)
       AND id <> p_new_invitation_id AND status = 'superseded'
     ORDER BY created_at DESC LIMIT 1)
   WHERE id = p_new_invitation_id AND resend_of IS NULL;

  RETURN v_count;
END;
$$;


--
-- Name: sync_contract_fields_from_defs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_contract_fields_from_defs(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid;
  v_tkey text;
BEGIN
  SELECT d.org_id, t.template_key INTO v_org, v_tkey
    FROM documents d JOIN contract_templates t ON t.id = d.template_id
   WHERE d.id = p_document_id AND d.deleted_at IS NULL;
  IF v_tkey IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM contract_clause_defs WHERE template_key = v_tkey) THEN
    RETURN;  -- flat templates manage their own fields
  END IF;

  -- new defs → new blank rows
  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key,
    responsibility_kind)
  SELECT v_org, p_document_id, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on, d.closed, d.guidance,
         d.required, d.is_optional, d.responsibility, d.sort_order, d.parent_field_key,
         d.responsibility_kind
    FROM contract_field_defs d
   WHERE d.template_key = v_tkey
     AND NOT EXISTS (
       SELECT 1 FROM contract_fields cf
        WHERE cf.document_id = p_document_id AND cf.field_key = d.field_key);

  -- existing rows → refresh def-owned columns (value is preserved)
  UPDATE contract_fields cf SET
      label = d.label, section = d.section, clause_key = d.clause_key,
      owner_role = d.owner_role, value_type = d.value_type,
      input_kind = nullif(d.input_kind,''), format_type = d.format_type,
      options = d.options, conditional_on = d.conditional_on, guidance = d.guidance,
      required = d.required, is_optional = d.is_optional, sort_order = d.sort_order,
      parent_field_key = d.parent_field_key, responsibility_kind = d.responsibility_kind,
      updated_at = now()
    FROM contract_field_defs d
   WHERE d.template_key = v_tkey
     AND cf.document_id = p_document_id AND cf.field_key = d.field_key;

  -- selected option no longer offered → reset the field. Only for single-select
  -- controls (select / buttons / yesno) with a non-empty value that is NOT present
  -- in the (now-refreshed) options list. Multi-select values (which are stored as
  -- CSV and may legitimately combine several codes) and free-text are left alone.
  UPDATE contract_fields cf SET value = '', updated_at = now()
   WHERE cf.document_id = p_document_id
     AND cf.owner_role <> 'SYSTEM'
     AND coalesce(cf.value,'') <> ''
     AND cf.input_kind IN ('select','buttons','yesno')
     AND cf.value NOT LIKE '%,%'                       -- skip multi-select CSVs
     AND jsonb_typeof(cf.options) = 'array'
     AND jsonb_array_length(cf.options) > 0
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(cf.options) o
        WHERE o->>'value' = cf.value);

  -- rows whose def is gone → remove (but never remove SYSTEM party auto-fill rows,
  -- which are inserted by fill_party_fields_from_contacts and have no def)
  DELETE FROM contract_fields cf
   WHERE cf.document_id = p_document_id
     AND cf.owner_role <> 'SYSTEM'
     AND NOT EXISTS (
       SELECT 1 FROM contract_field_defs d
        WHERE d.template_key = v_tkey AND d.field_key = cf.field_key);
END;
$$;


--
-- Name: sync_document_primary_horse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_document_primary_horse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc     uuid := coalesce(NEW.document_id, OLD.document_id);
  v_primary uuid;
BEGIN
  SELECT dh.horse_id INTO v_primary
    FROM document_horses dh
    WHERE dh.document_id = v_doc
    ORDER BY dh.position, dh.created_at
    LIMIT 1;
  -- No join rows left → the document is horse-less again (NULL), which is the
  -- pre-existing "no horse named" state, not an error.
  UPDATE documents SET horse_id = v_primary, updated_at = now()
    WHERE id = v_doc AND horse_id IS DISTINCT FROM v_primary;
  RETURN NULL;
END;
$$;


--
-- Name: sync_horse_fields_to_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_horse_fields_to_documents() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d         record;
  f         record;
  v_new     text;
  v_old     text;
  v_changed boolean;
BEGIN
  FOR d IN
    SELECT doc.id, ct.template_key FROM documents doc
    JOIN contract_templates ct ON ct.id = doc.template_id
    WHERE doc.horse_id = NEW.id
      AND doc.deleted_at IS NULL
      AND doc.workflow_state IN ('editable', 'editing', 'in_review')
  LOOP
    -- Per-document sub-block: a document-side failure (e.g. the horse's owner
    -- updating their record while not (yet) a party on some staff draft, so
    -- remerge refuses) must NEVER block the horse record save. That document
    -- simply stays as-is (its fields refresh on the next attach/edit).
    BEGIN
      v_changed := false;
      FOR f IN
        SELECT cf.id, cf.value,
               upper(split_part(regexp_replace(cf.field_key, '[{}]', '', 'g'), '.', 2)) AS field
        FROM contract_fields cf
        WHERE cf.document_id = d.id
          AND regexp_replace(cf.field_key, '[{}]', '', 'g') LIKE 'HORSE.%'
      LOOP
        v_new := horse_field_token_value(NEW, f.field);
        v_old := horse_field_token_value(OLD, f.field);
        -- Preserve deliberate contract-side edits: overwrite only when the
        -- stored value is empty OR still equals the horse record's PREVIOUS
        -- value (i.e. it was never manually diverged).
        IF (f.value IS NULL OR btrim(f.value) = '' OR f.value = v_old)
           AND f.value IS DISTINCT FROM v_new THEN
          UPDATE contract_fields SET value = v_new, updated_at = now() WHERE id = f.id;
          v_changed := true;
        END IF;
      END LOOP;
      IF v_changed THEN
        -- clause-engine docs recompose from clauses; flat docs from the body
        IF EXISTS (SELECT 1 FROM contract_section_defs s WHERE s.template_key = d.template_key) THEN
          PERFORM remerge_contract_from_clauses(d.id);
        ELSE
          PERFORM remerge_contract_from_fields(d.id);
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL; -- this document is skipped; the horse save proceeds
    END;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: sync_horse_id_to_document_horses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_horse_id_to_document_horses() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.horse_id IS NULL THEN RETURN NULL; END IF;

  -- already bound (in any position) → nothing to do
  IF EXISTS (SELECT 1 FROM document_horses dh
              WHERE dh.document_id = NEW.id AND dh.horse_id = NEW.horse_id) THEN
    RETURN NULL;
  END IF;

  -- Make room at position 1 FIRST (no-op when the document has no rows yet),
  -- then insert the new primary there. Done in this order there is no window
  -- where two rows share position 1.
  UPDATE document_horses dh
     SET position = dh.position + 1
   WHERE dh.document_id = NEW.id;

  INSERT INTO document_horses (org_id, document_id, horse_id, position)
    VALUES (NEW.org_id, NEW.id, NEW.horse_id, 1)
    ON CONFLICT (document_id, horse_id) DO NOTHING;

  RETURN NULL;
END;
$$;


--
-- Name: sync_profile_name_from_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_profile_name_from_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.first_name IS DISTINCT FROM OLD.first_name
     OR NEW.last_name IS DISTINCT FROM OLD.last_name THEN
    UPDATE profiles
       SET first_name = NEW.first_name,
           last_name  = NEW.last_name,
           updated_at = now()
     WHERE contact_id = NEW.id;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION sync_profile_name_from_contact(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_profile_name_from_contact() IS 'contacts is authoritative for the legal name; profiles mirrors it so the two can never diverge again (they had, for 2 of 6 linked pairs). The community PERSONA — display_name, avatar_url, bio — is separate and deliberately not touched: a member may show "CJ" while their contracts read "Charles Zigmund".';


--
-- Name: template_past_signers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_past_signers(p_template_key text) RETURNS TABLE(contact_id uuid, name text, email text, signed_version integer, signed_at timestamp with time zone, already_required boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id,
         coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''),
                  c.email, 'Unnamed'),
         c.email,
         max(coalesce(d.signed_template_version, ct.version))::int,
         max(d.generated_at),
         EXISTS (SELECT 1 FROM contact_required_documents crd
                  WHERE crd.contact_id = c.id AND crd.template_key = p_template_key)
    FROM documents d
    JOIN contract_templates ct ON ct.id = d.template_id
    JOIN contacts c ON c.id = d.contact_id AND c.deleted_at IS NULL
   WHERE ct.template_key = p_template_key
     AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
     AND c.org_id = current_org()
     AND has_staff_access()
   GROUP BY c.id, c.first_name, c.last_name, c.email
  HAVING max(coalesce(d.signed_template_version, ct.version))
         < (SELECT max(version) FROM contract_templates
             WHERE template_key = p_template_key AND active AND deleted_at IS NULL)
   ORDER BY max(d.generated_at) DESC
$$;


--
-- Name: FUNCTION template_past_signers(p_template_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.template_past_signers(p_template_key text) IS 'Everyone who signed an OLDER version of this template — the pick list for a targeted re-sign request. already_required shows who is on the hook already, so staff can see at a glance what a second run would change.';


--
-- Name: token_display_value(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.token_display_value(p_token text, p_raw text, p_labels jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE
    WHEN coalesce(p_raw,'') = '' THEN ''
    -- pure include-toggles (checkbox controls) emit no document text; they only
    -- gate their target clause. Convention: token key ends in _INCLUDE.
    WHEN p_token LIKE '%\_INCLUDE' THEN ''
    -- ISO date values render in written-out style, matching DOC.EFFECTIVE_DATE
    WHEN p_raw ~ '^\d{4}-\d{2}-\d{2}$'
      THEN to_char(to_date(p_raw, 'YYYY-MM-DD'), 'FMMonth FMDD, YYYY')
    WHEN p_raw LIKE '%,%' AND p_labels ? p_token THEN (
      SELECT string_agg(
               coalesce(p_labels #>> ARRAY[p_token, btrim(v)], btrim(v)),
               ', ' ORDER BY ord)
        FROM unnest(string_to_array(p_raw, ',')) WITH ORDINALITY AS t(v, ord)
        WHERE btrim(v) <> ''
    )
    WHEN p_labels #>> ARRAY[p_token, p_raw] IS NOT NULL
      THEN p_labels #>> ARRAY[p_token, p_raw]
    WHEN upper(p_raw) = 'YES' THEN 'Yes'
    WHEN upper(p_raw) = 'NO'  THEN 'No'
    ELSE p_raw
  END;
$_$;


--
-- Name: transfer_payment_responsibility(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_payment_responsibility(p_purchase_id uuid, p_new_payer_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_p    purchases%ROWTYPE;
  v_user uuid;
BEGIN
  SELECT * INTO v_p FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;
  IF NOT (has_staff_access() OR v_p.buyer_user_id = auth.uid()
          OR v_p.buyer_contact_id = current_contact_id()) THEN
    RAISE EXCEPTION 'not your purchase';
  END IF;
  IF v_p.payment_status = 'paid' THEN
    RAISE EXCEPTION 'this purchase is already paid';
  END IF;

  SELECT user_id INTO v_user FROM profiles WHERE contact_id = p_new_payer_contact_id;
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'the new payer must have an account';
  END IF;

  UPDATE purchases
     SET buyer_contact_id = p_new_payer_contact_id,
         buyer_user_id    = v_user,
         updated_at       = now()
   WHERE id = p_purchase_id;

  PERFORM log_status_event('order', p_purchase_id, coalesce(v_p.current_status, 'pending'),
    'Payment responsibility transferred to contact ' || p_new_payer_contact_id::text, v_p.org_id);
END;
$$;


