    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT contracts_segment_check CHECK ((segment = ANY (ARRAY['rider'::text, 'horse'::text, 'acquisition'::text]))),
    CONSTRAINT contracts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'negotiating'::text, 'signed'::text, 'executed'::text, 'void'::text, 'declined'::text])))
);


