    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT cost_allocation_rules_scope_check CHECK ((scope = ANY (ARRAY['horse'::text, 'lease'::text, 'board'::text, 'default'::text])))
);


