    CONSTRAINT requests_notes_len CHECK (((notes IS NULL) OR (char_length(notes) <= 4000))),
    CONSTRAINT requests_phone_format CHECK (((contact_phone IS NULL) OR (contact_phone ~ '^[-+().0-9[:space:]]{7,32}$'::text))),
