INSERT INTO public.contract_clause_defs VALUES ('dc1b68c5-962c-4656-997b-ed3bf4d69da2', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.JUMP_TITLE', 'Jumping Restrictions', '{{TXN.JUMP_OMIT}}', 'input', 320, false, NULL, '{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('aabcd80b-33dd-4341-8436-33814211b263', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.JUMP_ON', NULL, 'Jumping is restricted as follows: maximum height {{TXN.JUMP_MAX_HEIGHT}}; no more than {{TXN.JUMP_DAYS_PER_WEEK}} days per week; under trainer supervision only: {{TXN.JUMP_SUPERVISION}}.', 'input', 330, true, NULL, '{"all": [{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["NO", ""], "field_key": "TXN.JUMP_OMIT"}]}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('31b2a1d2-f14d-4d16-afc1-db2098dfbb19', 'HORSE_LEASE_V2', 'TERMINATION', 'TERMINATION.LOSS', 'Self-Termination upon Loss or Injury', 'This Agreement shall self-terminate if the Horse is significantly injured or seriously ill as determined by a licensed veterinarian, or dies. Lessee is entitled to a prorated refund of Lease Fee paid for the remaining time unused at the time of self-termination. In the event Lessee is found to have caused, through gross negligence, reckless conduct, or intentional misconduct, the injury, illness, or death, Lessor may retain the unused portion of the paid Lease Fee.', 'prose', 40, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b10e3b12-83c7-4f90-956f-739e760cf952', 'HORSE_LEASE_V2', 'NOTICE', 'NOTICE.LESSEE_ADDRESS', 'Lessee', 'Name: {{LESSEE.FULL_NAME}}
Address: {{LESSEE.ADDRESS}}
Phone: {{LESSEE.PHONE}}
Email: {{LESSEE.EMAIL}}', 'prose', 20, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('5a6ee240-7c76-4145-b5e0-207e998f0648', 'HORSE_LEASE_V2', 'NOTICE', 'NOTICE.CHANGES', 'Changes in Contact Information', 'Each party shall promptly notify the other party in writing of any change in the party''s address or contact information.', 'prose', 40, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('5f291639-9f33-4eff-8809-f77d13a08d9e', 'HORSE_LEASE_V2', 'NOTICE', 'NOTICE.FORM', 'Form of Notice', 'Any notice required or permitted under this Agreement shall be in writing and delivered by a method that provides evidence of receipt to the party at the contact information below. Notice by email is not effective unless the receiving party acknowledges receipt.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0726a0ad-f271-4f9c-b3f9-3c78fd29603f', 'HORSE_LEASE_V2', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions and understandings. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0ca215f4-47bb-4068-95ff-942e10c32d0d', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.IDENTITY', 'Horse', 'This Agreement applies to the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Current fair market value: {{HORSE.FAIR_MARKET_VALUE}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}', 'input', 10, false, NULL, NULL, NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('9f5c57b0-5c6e-41e5-a045-38b9b14c7fb9', 'HORSE_LEASE_V2', 'TERMINATION', 'TERMINATION.CAUSE', 'Termination for Cause', 'Either party may terminate this Agreement for cause (including a material breach that remains uncured) by giving the other party at least {{TXN.CAUSE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 30, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a8bb507d-1f7e-4b78-9737-5ce2438f1892', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.CONDITION', 'Physical Condition', 'The Lessor warrants that the Horse is sound and in good physical condition as of the Effective Date of this Agreement.', 'input', 40, false, NULL, NULL, NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('82432f7e-4f95-420f-b773-5f4a2505f860', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.BEHAVIOR', 'Behavior', 'The Lessor warrants that the Horse has no history of dangerous or vicious behavior as of the Effective Date of this Agreement.', 'input', 30, false, NULL, NULL, NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('33fcf9a2-9080-45a0-ac43-7a90c47b4a06', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.OWNERSHIP_LIMITS_Q', NULL, 'Are there any ownership related leasing restrictions? {{TXN.HAS_OWNERSHIP_LIMITS}}', 'input', 25, false, NULL, NULL, NULL, '2026-07-23 06:01:38.395078+00', false);
INSERT INTO public.contract_clause_defs VALUES ('5ea17ad7-43b2-4e6f-81f4-c103877b7bcf', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'TRAINING_LESSONS.LESSONS', 'Lessons', 'Lessee is required to maintain continuous enrollment in weekly riding lessons: {{TXN.LESSONS_REQUIRED}}.
Lessons shall be conducted only by a French Heritage Equestrian Approved Instructor.', 'input', 250, false, NULL, '{"all": [{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}, {"contains": ["LESSONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}]}', NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('56ef7a89-f61e-4263-b2d5-8d58db2282e3', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.LESSOR_PENDING', NULL, '[Pending — select whether Lessor is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 11, false, NULL, '{"equals": [""], "field_key": "LESSOR.PARTY_TYPE"}', NULL, '2026-08-01 16:39:09.138085+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0130af5c-ee51-49b8-916a-3b1c9c1a8c7b', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.LESSEE_PENDING', NULL, '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 13, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-01 16:39:09.138085+00', false);
INSERT INTO public.contract_clause_defs VALUES ('004ea30e-86fc-41a0-85ba-12d9ae520427', 'HORSE_LEASE_V2', 'LESSEE_REPS', 'LESSEE_REPS.PENDING', 'Lessee''s Representations', '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable representations and blocks signing.]', 'prose', 21, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-01 16:39:09.138085+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1c2b98f6-2df8-4924-8b16-3c7038333392', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'TRAINING_LESSONS.PENDING', 'Lessons', '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable lessons terms and blocks signing.]', 'input', 256, false, NULL, '{"all": [{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}, {"contains": ["LESSONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}]}', NULL, '2026-08-01 16:39:09.138085+00', false);
INSERT INTO public.contract_clause_defs VALUES ('68b363ed-9954-4744-9da7-e479815140d6', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.WARRANTY', 'Disclaimer of Warranties', 'Except for the representations expressly stated in this Agreement, LESSOR MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.', 'prose', 60, false, NULL, NULL, NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('cab56e2d-353a-44d0-95dd-e36601fa871d', 'HORSE_LEASE_V2', 'TERM', 'TERM.TERMINATION_XREF', NULL, 'Notwithstanding the term stated above, this Agreement may be terminated earlier as provided in the Termination section of this Agreement.', 'prose', 30, false, NULL, NULL, NULL, '2026-07-20 21:49:32.565438+00', false);
INSERT INTO public.contract_clause_defs VALUES ('fea4e95d-de33-4877-9a7f-0c45564c1858', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.TRAIL_ON', NULL, 'Trail riding is restricted as follows: {{TXN.TRAIL_RESTRICTION}}.', 'input', 390, true, NULL, '{"all": [{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["NO", ""], "field_key": "TXN.TRAIL_OMIT"}]}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('198a1ab9-1d6f-4a2e-9b0b-2960178147b5', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_NONE', NULL, 'Lessor has elected not to require general liability insurance under this Agreement. Lessor accepts full risk and responsibility for liability claims for bodily injury or property damage to third parties arising from the Horse or the activities contemplated by this Agreement, except as otherwise expressly allocated in this Agreement.', 'input', 168, false, NULL, '{"equals": ["YES"], "field_key": "TXN.GL_NOT_REQUIRED"}', NULL, '2026-07-28 00:38:32.692603+00', false);
INSERT INTO public.contract_clause_defs VALUES ('21ef19b6-ca2d-4445-af50-10b56829bd6e', 'HORSE_LEASE_V2', 'EVALUATION', 'EVALUATION.CHOICE', NULL, '', 'choice', 10, false, NULL, NULL, NULL, '2026-07-20 21:49:32.565438+00', false);
INSERT INTO public.contract_clause_defs VALUES ('bf819b78-bfd9-4d88-8ac7-747ac207065a', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.COOWNERS', NULL, 'Co-owners: {{TXN.CO_OWNERS}}', 'input', 22, false, NULL, NULL, NULL, '2026-07-23 08:19:19.771914+00', false);
INSERT INTO public.contract_clause_defs VALUES ('627c921b-a069-47b3-b1ef-4dfa712b86a2', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.TRAIL_OFF', NULL, 'Lessor does not restrict trail riding.', 'input', 400, false, NULL, '{"all": [{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.TRAIL_OMIT"}]}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('9df99f00-6108-40b1-b148-6dc568996b57', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.TRAINER_EVAL', 'Pre-Lease Trainer Evaluation', 'Pre-lease trainer evaluation of the Horse: {{TXN.TRAINER_EVAL_CHOICE}}', 'input', 55, false, NULL, NULL, NULL, '2026-07-27 20:12:30.672304+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1342f73e-2c53-4862-a95d-1557542f4d6b', 'HORSE_LEASE_V2', 'CARE', 'CARE.RIDER_AIDS_OTHER', NULL, 'Other prohibited rider aid: {{TXN.RIDER_AIDS_OTHER}}.', 'input', 92, true, NULL, '{"contains": ["OTHER"], "field_key": "TXN.RIDER_AIDS"}', NULL, '2026-07-21 19:46:38.674225+00', false);
INSERT INTO public.contract_clause_defs VALUES ('34e59eef-f689-4065-96ac-0e9162ef9e26', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.SAFETY_ATTIRE', 'Required Protective Attire', 'Lessee shall wear, and shall ensure that any other person riding the Horse under Lessee''s authorization wears, an appropriately fitted and securely fastened ASTM/SEI-certified equestrian helmet at all times while mounted on the Horse, together with heeled boots and long pants; gloves and long sleeves are highly recommended. Riders shall provide their own helmet, boots, and pants meeting these requirements unless otherwise agreed in writing. Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, assumes all increased risk of injury or death resulting from any failure to wear the required attire. Any refusal or failure to wear an approved helmet or the other required attire immediately revokes permission to ride or handle the Horse and constitutes a material breach of this Agreement.', 'prose', 1100, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('290f5460-e710-43af-8c6e-76968e5b8674', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSEE_RESP', 'General Liability — Lessee Responsibility', 'Lessee has elected to accept, and hereby accepts, financial responsibility for general liability insurance under this Agreement. Lessee shall obtain and maintain, at Lessee''s sole cost, general liability insurance covering the Horse and the activities contemplated by this Agreement for the duration of this Agreement, and shall provide proof of coverage to Lessor upon request. As between the parties, and except as otherwise expressly allocated in this Agreement, Lessee bears responsibility for liability claims for bodily injury or property damage to third parties arising from the Horse or the activities contemplated by this Agreement to the extent not covered by an in-force policy.', 'input', 169, false, NULL, '{"equals": ["YES"], "field_key": "TXN.GL_LESSEE_RESPONSIBLE"}', NULL, '2026-08-02 03:51:14.989194+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4e410687-1369-4608-863c-aa97f49ed23d', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_LESSEE_RESP', 'Mortality — Lessee Responsibility', 'Lessee has elected to accept, and hereby accepts, financial responsibility for mortality insurance under this Agreement. Lessee shall obtain and maintain, at Lessee''s sole cost, mortality insurance on the Horse for the duration of this Agreement in an amount not less than the Horse''s current fair market value, and shall provide proof of coverage to Lessor upon request. As between the parties, and except as otherwise expressly allocated in this Agreement, Lessee bears responsibility for the loss of the Horse''s value in the event of the Horse''s death, theft, or humane destruction to the extent not covered by an in-force policy.', 'input', 221, false, NULL, '{"equals": ["YES"], "field_key": "TXN.MORT_LESSEE_RESPONSIBLE"}', NULL, '2026-08-02 03:51:14.989194+00', false);
INSERT INTO public.contract_clause_defs VALUES ('f8b6a22e-a7a2-4531-9783-1792a6cedcd1', 'HORSE_LEASE_V2', 'LEASE_FEE', 'LEASE_FEE.CHOICE', NULL, '{{TXN.LEASE_FEE}}
If no monetary lease fee is payable under this Agreement, the parties agree that Lessee''s undertakings of care, exercise, and use of the Horse and Lessee''s other obligations under this Agreement constitute good and adequate consideration for this Agreement.', 'input', 5, false, NULL, NULL, NULL, '2026-07-21 12:19:05.018123+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7f45616b-cacc-4f63-941e-3412828ad76d', 'HORSE_LEASE_V2', 'CARE', 'CARE.RIDER_AIDS', 'Rider Aids', 'The following rider aids are prohibited: {{TXN.RIDER_AIDS}}.', 'input', 90, true, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('03b2ccff-daed-491a-befb-2533f8996aa2', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.LOSS_OF_USE_ACK', 'Loss of Use', 'Lessor acknowledges and accepts that loss of use of the Horse may result from injury to, illness of, or the death of the Horse. No loss-of-use insurance is required or provided under this Agreement.', 'prose', 550, false, NULL, NULL, NULL, '2026-07-27 19:24:47.335707+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b203e5d5-bad0-4c8b-87f6-c377f3865797', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.JUMPING_RISKS', 'Jumping Risks', 'Lessee acknowledges that jumping the Horse exposes Lessee and the Horse to additional risks beyond flat riding, including refusals, run-outs, awkward or missed distances, falls, unseating, and the Horse landing, stopping, or twisting unpredictably. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1210, false, NULL, '{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-23 09:13:17.556063+00', false);
INSERT INTO public.contract_clause_defs VALUES ('3389070f-56f6-4789-aa5f-b70d5d227afe', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.COMPETITION_RISKS', 'Competition Risks', 'Lessee acknowledges that competing with the Horse exposes Lessee and the Horse to additional risks, including unfamiliar and crowded show grounds, proximity to other horses and riders, loudspeakers, banners, and other stimuli that may cause the Horse to spook or behave unpredictably, as well as the physical demands and pressures of competition. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1220, false, NULL, '{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-23 09:13:17.556063+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c9fbf642-176b-4bdf-b428-ad140a3f290c', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.SHARED_ARENA_RISKS', 'Shared Arena Riding Risks', 'Lessee acknowledges that riding in an arena at the same time as other riders exposes Lessee and the Horse to additional risks, including collisions, crowding, sudden movements or loss of control by other horses or riders, and the Horse reacting to other horses. Lessee agrees to ride with awareness of others, to follow standard arena etiquette and right-of-way rules and any directions of Lessor or an instructor, and voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1230, false, NULL, '{"contains": ["ARENA_GROUP"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-23 09:13:17.556063+00', false);
INSERT INTO public.contract_clause_defs VALUES ('d96fd116-0c1f-4f08-ac3f-8020a98fc0a2', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PERMITTED_USE.RESTRICTIONS', 'Additional Restrictions', 'Additional restrictions: {{TXN.PERMITTED_RESTRICTIONS}}', 'input', 410, false, NULL, NULL, NULL, '2026-07-23 08:39:16.966195+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2d77bbf5-a6d6-419b-950d-fddb092247c8', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PROHIBITED.OTHER_NONE', 'Other Allowed Activities', 'Lessee is not permitted to engage in any activities with the Horse beyond the permitted uses stated above.', 'input', 455, false, NULL, '{"equals": ["", "NONE"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-07-28 01:21:07.406412+00', false);
INSERT INTO public.contract_clause_defs VALUES ('55510793-1541-447b-aeb2-4eefc1a7a181', 'HORSE_LEASE_V2', 'PAYMENT_TERMS', 'PAYMENT_TERMS.RECEIPTS', 'Receipts', 'A party seeking reimbursement for an expense paid on behalf of the other party shall provide a receipt or other reasonable documentation of the expense as a condition of reimbursement.', 'prose', 30, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0c18a3bf-4bd4-4380-9403-2a5c13bd2961', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.LESSOR_ENT', NULL, '"Lessor Parties" means Lessor; Lessor''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessor and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 11, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-07-31 16:54:48.684074+00', false);
INSERT INTO public.contract_clause_defs VALUES ('3f7fcf4a-f474-4f8d-8d67-50be7fdfe1ba', 'HORSE_LEASE_V2', 'EVALUATION', 'EVALUATION.DATES_FIXED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_FIXED_LENGTH}} {{TXN.EVAL_FIXED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is {{TXN.EVAL_FIXED_FEE}}, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 21, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["FIXED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_FIXED_LENGTH"}]}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4324b919-146d-414c-8269-c660e786dd6a', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.BINDING', NULL, 'Each release, waiver, assumption of risk, and covenant made by a party under this Agreement is made by that party on its own behalf and, to the fullest extent permitted by law, binds anyone claiming by, through, or under that party, including that party''s estate, executors, administrators, heirs, legal representatives, successors, assigns, insurers, and subrogees. Each party covenants that it will not permit any person who has not executed this Agreement or a release satisfying the Releases Required for Authorized Riders provision of this Agreement to ride, handle, or care for the Horse, and each party shall indemnify, defend, and hold harmless the other party''s Lessor Parties or Lessee Parties, as applicable, from and against any claim brought by that party''s family members, invitees, or authorized riders arising out of the Horse or the activities contemplated by this Agreement, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'input', 14, false, NULL, NULL, NULL, '2026-07-31 16:54:48.684074+00', false);
INSERT INTO public.contract_clause_defs VALUES ('aecaed03-d86e-4e46-aaa8-cdba303e75fb', 'HORSE_LEASE_V2', 'EVALUATION', 'EVALUATION.REFUSED', NULL, 'No evaluation period applies to this Agreement. The Lessor has declined to provide an evaluation period, and the Lease begins on the Effective Date without one.', 'input', 40, false, NULL, '{"any": [{"equals": ["REFUSED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-07-31 20:30:42.05298+00', false);
INSERT INTO public.contract_clause_defs VALUES ('478c444b-f9cd-4754-b247-73dfa4ae2712', 'HORSE_LEASE_V2', 'EVALUATION', 'EVALUATION.WAIVED', NULL, 'No evaluation period applies to this Agreement. The Lessee has waived any evaluation period, and the Lease begins on the Effective Date without one.', 'input', 41, false, NULL, '{"any": [{"equals": ["WAIVED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-07-31 20:30:42.09657+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e0ec5d84-9fc8-46b5-b185-87a7bec65b8c', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.RISK_OF_LOSS', 'Risk of Loss of or Injury to the Horse', 'Lessor assumes all risk of loss of or injury to the Horse during the term of this Agreement, except to the extent caused by Lessee''s gross negligence, reckless conduct, or intentional misconduct.', 'input', 500, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('86340cdc-5509-426c-8646-a1f0309e7b98', 'HORSE_LEASE_V2', 'PAYMENT_TERMS', 'PAYMENT_TERMS.LATE', 'Late Payments', 'All payments are due on their due date or within 5 business days of notification of the amount owed. Payments will be deemed late if they remain unpaid on the 6th business day. Late payments are considered a breach of the contract terms and may be grounds for termination of the Agreement unless the party from whom the payment is owed has communicated in writing the date by which payment will be made. Payments exceeding 1 calendar month in past-due status constitute grounds for termination for cause under the Termination for Cause provisions of this Agreement unless prior written acceptance of the delay is provided by the party to whom the payment is owed.', 'input', 40, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('20614d1f-d53c-454a-aad6-832e1427d6b7', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORTALITY', 'Mortality Insurance', '', 'input', 200, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('d58ffb8a-5e24-4ba3-8db4-a8b0b6573a60', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.INDEMNIFICATION', 'Mutual Indemnification', 'Each party shall indemnify, defend, and hold harmless the other party and, respectively, the Lessor Parties or the Lessee Parties, from and against any and all claims, damages, losses, liabilities, costs, and expenses arising out of the indemnifying party''s use, handling, care, or possession of the Horse, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'input', 1400, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0f110803-be39-4eea-8cb8-49e85a28d1a5', 'HORSE_LEASE_V2', 'PAYMENT_TERMS', 'PAYMENT_TERMS.OFFSET', 'Right of Offset', 'A party to whom money is owed under this Agreement may offset the amount owed against any amount that party owes to the other party.', 'prose', 20, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0433aa3f-42c5-435b-a090-44c3542504d0', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.INSURANCE', 'Insurance Requirements', 'The parties agree to the insurance elections set forth below. Each policy elected or required below shall be maintained in effect for the duration of this Agreement.', 'prose', 100, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7b0df54b-5942-4f84-b87b-556f2437798f', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE', 'Release of Liability', 'In consideration for being permitted to handle or ride the Horse, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, completely releases, forever discharges, and agrees to hold harmless the Lessor Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessee''s use, handling, or riding of the Horse, whether caused by the ordinary negligence of any Lessor Party or otherwise. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 960, false, NULL, NULL, NULL, '2026-07-21 02:48:55.640351+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b99ed9ba-80eb-40e7-851a-6ff48f2678cf', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Agreement that the waiving party does not know or suspect to exist in its favor at the time of this Agreement. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Agreement.', 'prose', 1300, false, NULL, NULL, NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('87ce748d-c496-4aa0-8d27-717074492b21', 'HORSE_LEASE_V2', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('3297bc65-483e-4f03-afd6-303b936c1c0d', 'HORSE_LEASE_V2', 'CARE', 'CARE.PROTECTIVE_EQUIP', NULL, 'Lessor will provide the following equipment for the Horse: {{TXN.PROTECTIVE_EQUIPMENT}}
Lessee must ensure equipment is used and properly secured to the Horse prior to all activities.', 'input', 62, true, NULL, '{"equals": ["YES"], "field_key": "TXN.PROTECTIVE_REQUIRED"}', NULL, '2026-07-21 19:52:35.787525+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6df79ded-6550-4e96-a0a7-e0a2c305b478', 'HORSE_LEASE_V2', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_ENTITY', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is duly organized and in good standing, and has full authority to enter into this Agreement, and that the individual signing this Agreement does so as Lessee''s authorized representative; that each person who rides or handles the Horse under Lessee''s authorization will, before doing so, have executed the releases required under this Agreement and possess the knowledge and experience to handle and ride the Horse safely; and that Lessee will use reasonable care and follow Lessor''s instructions in all handling of the Horse. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b430693c-32af-4037-82b5-c23e6127db8d', 'HORSE_LEASE_V2', 'PURPOSE', 'PURPOSE.LEASE_TYPE', 'Lease Type', 'Lease type: {{TXN.LEASE_TYPE}}.', 'input', 20, false, NULL, NULL, NULL, '2026-07-21 15:53:40.262978+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a33bad2e-93c5-45e3-b803-ad2e6c34fbae', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DEDR_SIMPLE', NULL, 'If a claim is made under any such policy arising from events for which Lessee bears responsibility, whether directly or indirectly, responsibility for any deductible shall be borne by: {{TXN.MORT_DED_RESP}}.', 'input', 214, false, NULL, '{"all": [{"equals": ["NO", ""], "field_key": "TXN.MORT_NOT_REQUIRED"}, {"any": [{"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MORT_LESSOR_STATUS"}, {"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MORT_LESSEE_STATUS"}]}]}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b02a137f-5994-46e3-a19a-6defe782e0f3', 'HORSE_LEASE_V2', 'TERM', 'TERM.ADDITIONAL', NULL, 'Additional terms: {{TXN.ADDITIONAL_TERMS}}', 'input', 22, false, NULL, NULL, NULL, '2026-07-23 09:26:27.245016+00', false);
INSERT INTO public.contract_clause_defs VALUES ('18db9f1b-0c0e-4109-84ee-d639485487e8', 'HORSE_LEASE_V2', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

LESSEE
Signature: {{SIG.LESSEE.NAME}}
Printed Name: {{LESSEE.PRINTED_NAME}}
Date: {{SIG.LESSEE.DATE}}

LESSOR (OWNER)
Signature: {{SIG.LESSOR.NAME}}
Printed Name: {{LESSOR.PRINTED_NAME}}
Date: {{SIG.LESSOR.DATE}}', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e479b468-c881-49ab-b29f-2212c3bd930c', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DEDR_SPLITC', NULL, 'The deductible shall be split between the parties: {{TXN.MORT_DED_RESP_SPLIT_LESSOR}} paid by Lessor and {{TXN.MORT_DED_RESP_SPLIT_LESSEE}} paid by Lessee.', 'input', 215, false, NULL, '{"all": [{"equals": ["NO", ""], "field_key": "TXN.MORT_NOT_REQUIRED"}, {"equals": ["SPLIT"], "field_key": "TXN.MORT_DED_RESP"}, {"any": [{"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MORT_LESSOR_STATUS"}, {"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MORT_LESSEE_STATUS"}]}]}', NULL, '2026-07-28 00:36:43.221618+00', true);
INSERT INTO public.contract_clause_defs VALUES ('0670e22d-bb44-4ef1-a772-08220b0af3bd', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_NONE', NULL, 'Lessor has elected not to require mortality insurance under this Agreement. Lessor accepts full risk and responsibility for the loss of the Horse''s value in the event of the Horse''s death, theft, or humane destruction, except as otherwise expressly allocated in this Agreement.', 'input', 220, false, NULL, '{"equals": ["YES"], "field_key": "TXN.MORT_NOT_REQUIRED"}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1d9d19ff-0f8c-4b7d-8722-3b53558cf9a2', 'HORSE_SALE_V2', 'PARTIES', 'PARTIES.INTRO', NULL, 'This Horse Sale and Purchase Agreement (the "Agreement") is made effective as of {{DOC.EFFECTIVE_DATE}} by and between {{SELLER.FULL_NAME}} of {{SELLER.ADDRESS}} ("Seller") and {{BUYER.FULL_NAME}} of {{BUYER.ADDRESS}} ("Buyer").', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:12.539765+00', false);
INSERT INTO public.contract_clause_defs VALUES ('f93dc9c5-13e7-4961-bc92-15cce6fce490', 'HORSE_LEASE_V2', 'ATTORNEYS_FEES', 'ATTORNEYS_FEES.PREVAILING', 'Attorneys'' Fees', 'Each party shall cover their own attorney''s fees and costs.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('df6dca1f-91f7-4acf-a5c7-184b9c48374d', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MEDICAL', 'Medical Insurance', '', 'input', 300, false, NULL, NULL, NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c18b8272-df3f-4f74-8484-35c713d928b7', 'HORSE_LEASE_V2', 'ASSIGNMENT', 'ASSIGNMENT.NO_ASSIGN', 'Assignment or Transfer', 'Lessee shall not assign, sublease, or otherwise transfer this Agreement or any of Lessee''s rights or obligations under it without Lessor''s prior written consent, unless permitted in the sections above.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('ed6aced2-cfe5-4079-a961-f599ba7625f6', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_LESSEE_RESP', 'Medical — Lessee Responsibility', 'Lessee has elected to accept, and hereby accepts, financial responsibility for medical insurance under this Agreement. Lessee shall obtain and maintain, at Lessee''s sole cost, medical insurance on the Horse for the duration of this Agreement, and shall provide proof of coverage to Lessor upon request. As between the parties, and except as otherwise expressly allocated in the Horse Care and Expenses section of this Agreement, Lessee bears responsibility for the costs of veterinary care arising from injury to or illness of the Horse to the extent not covered by an in-force policy.', 'input', 306, false, NULL, '{"equals": ["YES"], "field_key": "TXN.MED_LESSEE_RESPONSIBLE"}', NULL, '2026-08-02 03:51:14.989194+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1265c8ff-3bb4-4d63-9c3a-bc471eaa7ea4', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE_LESSOR', 'Release of Liability by Lessor', 'In consideration of the mutual promises in this Agreement, Lessor, on behalf of Lessor and anyone claiming by, through, or under Lessor, completely releases, forever discharges, and agrees to hold harmless the Lessee Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessor''s riding or handling of the Horse or Lessor''s presence at any facility where the Horse is kept during the term of this Agreement, whether caused by the ordinary negligence of any Lessee Party or otherwise. Lessor expressly and voluntarily assumes all inherent risks of equine activities in connection with such riding, handling, or presence. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 961, false, NULL, NULL, NULL, '2026-08-02 11:16:19.009752+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a0088f87-736a-4b0c-b42a-e4c0c0131d3a', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_NONE', 'No Serious Injury History', 'Lessor represents that, to Lessor''s knowledge, no person has suffered serious injury proximately caused by the direct actions of the Horse, including biting, kicking, striking, bucking, rearing, bolting, crushing, or throwing a rider. This representation does not extend to any incident caused primarily by a third party or an external stimulus — such as another horse or rider being at fault, a loose dog, wildlife, a vehicle, or a similar external provocation — where the Horse''s reaction was within the range of normal equine behavior.', 'input', 43, false, NULL, '{"equals": ["NO"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 11:16:19.009752+00', false);
INSERT INTO public.contract_clause_defs VALUES ('30ca5326-b4eb-43db-bb15-4c7f59368985', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_DISCLOSED', 'Serious Injury History Disclosed', 'Lessor discloses that one or more persons have suffered serious injury involving the direct actions of the Horse, as follows, including for each incident the approximate date, the circumstances, the Horse''s actions, and the nature of the injury: {{TXN.INJURY_HISTORY_DETAILS}}. Lessee acknowledges this disclosure and proceeds with knowledge of it.', 'input', 44, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 11:16:19.009752+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e196b8f5-c545-47ab-8af7-242bc369b902', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_PENDING', NULL, '[Pending — state whether anyone has been seriously injured by the Horse''s direct actions. This placeholder is replaced by the applicable statement and blocks signing.]', 'input', 45, false, NULL, '{"equals": [""], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 11:16:19.009752+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7056b095-c051-442f-b563-56a4a758b6a2', 'HORSE_LEASE_V2', 'SIGNATURES', 'SIGNATURES.LESSEE_CAPACITY', NULL, 'By: {{LESSEE.ENTITY_SIGNER_NAME}}
Title: {{LESSEE.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{LESSEE.FULL_NAME}}', 'input', 11, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-02 11:16:19.009752+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e76fae5a-aa34-44de-ba46-3cf70b48c234', 'HORSE_LEASE_V2', 'SIGNATURES', 'SIGNATURES.LESSOR_CAPACITY', NULL, 'By: {{LESSOR.ENTITY_SIGNER_NAME}}
Title: {{LESSOR.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{LESSOR.FULL_NAME}}', 'input', 12, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSOR.PARTY_TYPE"}', NULL, '2026-08-02 11:16:19.009752+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4307910c-7aae-404c-be76-bd314b009a8c', 'HORSE_LEASE_V2', 'LOCATION', 'LOCATION.MOVE_CHOICE', NULL, '', 'input', 12, false, NULL, NULL, NULL, '2026-07-21 10:46:50.122503+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6480d88a-eba6-4f10-97cb-06ce092d4140', 'HORSE_LEASE_V2', 'PURPOSE', 'PURPOSE.GRANT', 'Lease Grant', 'Subject to the terms and conditions of this Agreement, Lessor agrees to lease to Lessee and Lessee agrees to lease from Lessor the horse described below.', 'prose', 15, false, NULL, NULL, NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('67b06cba-9712-49be-b8ee-7af61ffa42d0', 'HORSE_LEASE_V2', 'NOTICE', 'NOTICE.LESSOR_ADDRESS', 'Lessor', 'Name: {{LESSOR.FULL_NAME}}
Address: {{LESSOR.ADDRESS}}
Phone: {{LESSOR.PHONE}}
Email: {{LESSOR.EMAIL}}', 'prose', 30, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0de38835-39df-4fc4-95ee-85331422c17e', 'HORSE_LEASE_V2', 'SCHEDULE', 'SCHEDULE.CHANGES', 'Schedule Changes', 'Any changes to the agreed upon schedule must be made and accepted in writing.', 'prose', 15, false, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-07-20 23:52:25.2913+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7186adae-35c0-4112-b0ca-d9f5cb04ccba', 'HORSE_LEASE_V2', 'PURPOSE', 'PURPOSE.RECREATION', 'Purpose of Agreement', 'For {{TXN.LEASE_PURPOSE}} purposes, Lessee wishes to ride and/or handle Lessor''s horse, and Lessor agrees to allow Lessee to ride and/or handle Lessor''s horse in exchange for the consideration described herein.', 'prose', 10, false, NULL, '{"equals": ["RECREATIONAL", "INSTRUCTIONAL", "COMPETITION", "COMMERCIAL"], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('fe0380fc-7a09-425f-860d-f03633b81e95', 'HORSE_LEASE_V2', 'LOCATION', 'LOCATION.NEW', NULL, 'Location during lease term: {{TXN.NEW_LOCATION}}.', 'input', 14, true, NULL, '{"equals": ["YES"], "field_key": "TXN.HORSE_MOVES"}', NULL, '2026-07-21 10:46:50.122503+00', false);
INSERT INTO public.contract_clause_defs VALUES ('848137bf-22dc-49fa-9acc-77115698defa', 'HORSE_LEASE_V2', 'CARE', 'CARE.INTRO', NULL, 'Horse care and expenses shall be managed and paid for by the responsible party as listed below.', 'prose', 5, false, NULL, NULL, NULL, '2026-07-21 19:04:04.492529+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7a8a6340-0203-4597-bf75-4f2f4d428597', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GENERAL_LIABILITY', 'General Liability Insurance', '', 'input', 150, false, NULL, NULL, NULL, '2026-07-23 14:46:52.299025+00', false);
INSERT INTO public.contract_clause_defs VALUES ('5c205654-246e-4ef6-981e-793af4864a9e', 'HORSE_LEASE_V2', 'PAYMENT_METHOD', 'PAYMENT_METHOD.MAIN', 'Payments by the Lessee', 'The Lessee may pay amounts owed under this Agreement by the following method(s): {{TXN.PAYMENT_METHODS}}', 'input', 10, false, NULL, NULL, NULL, '2026-07-21 10:45:54.446698+00', false);
INSERT INTO public.contract_clause_defs VALUES ('10751f68-abaf-4676-88be-eb2c9952adc1', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PROHIBITED.OTHER_NOTE', NULL, 'Other additional permitted activity: {{TXN.ADDITIONAL_ACTIVITIES_OTHER}}.', 'input', 460, true, NULL, '{"contains": ["OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-07-21 12:52:57.478346+00', false);
INSERT INTO public.contract_clause_defs VALUES ('738d7264-8034-4c42-9fdf-b90d973b0c97', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.LESSOR_IND', NULL, '"Lessor Parties" means Lessor; Lessor''s spouse and family and household members, in each case when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessor''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 10, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-07-31 16:54:48.684074+00', false);
INSERT INTO public.contract_clause_defs VALUES ('fb77c780-e0ec-4ab6-b633-692b7d1a47dc', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.LESSEE_IND', NULL, '"Lessee Parties" means Lessee; Lessee''s spouse and family and household members, in each case when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessee''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 12, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-07-31 16:54:48.684074+00', false);
INSERT INTO public.contract_clause_defs VALUES ('3edbbcdd-c2a1-4598-a4c4-c2a764f86c41', 'HORSE_LEASE_V2', 'SCHEDULE', 'SCHEDULE.OTHER', NULL, 'Additional or custom schedule terms: {{TXN.SCHEDULE_TERMS}}', 'input', 12, true, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-07-21 10:45:54.446698+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b5fa0150-49b4-4487-bed2-9f8f68aabc62', 'HORSE_LEASE_V2', 'TERM', 'TERM.FIXED_END', NULL, 'This Agreement continues until {{TXN.LEASE_END}}.', 'input', 12, false, NULL, '{"equals": ["FIXED"], "field_key": "TXN.LEASE_TERM_TYPE"}', NULL, '2026-07-21 10:45:54.446698+00', false);
INSERT INTO public.contract_clause_defs VALUES ('5efa4ddd-9335-4b60-8602-d916c0a02186', 'HORSE_LEASE_V2', 'CARE', 'SCHEDULE.TRAINER_CARE', '3rd Party Exercise', 'Lessee is permitted to engage an approved 3rd party to exercise the Horse. All 3rd party exercise shall be conducted only by a French Heritage Equestrian Approved Trainer. Other 3rd parties must be approved in writing by the Lessor.
Party responsible for arranging: {{TXN.TRAINER_EXERCISE_ARRANGE}}
Party responsible for costs: {{TXN.TRAINER_EXERCISE_COST}}
Lessee''s share of the cost: {{TXN.TRAINER_EXERCISE_SPLIT_PCT}}', 'input', 2, false, NULL, '{"equals": ["YES"], "field_key": "TXN.TRAINER_CARE_INCLUDE"}', NULL, '2026-07-21 10:45:54.446698+00', false);
INSERT INTO public.contract_clause_defs VALUES ('127deb62-6ea9-4cb1-8454-af5b50af8a32', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.LESSEE_ENT', NULL, '"Lessee Parties" means Lessee; Lessee''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessee and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 13, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-07-31 16:54:48.684074+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1feed771-1f27-49be-8daa-1498bdf6b3f2', 'HORSE_LEASE_V2', 'PAYMENT_METHOD', 'PAYMENT_METHOD.CARD', NULL, 'Credit card payments are processed as follows: {{TXN.CARD_PROCESSOR}}', 'input', 20, true, NULL, '{"contains": ["CREDIT_CARD"], "field_key": "TXN.PAYMENT_METHODS"}', NULL, '2026-07-21 10:45:54.446698+00', false);
INSERT INTO public.contract_clause_defs VALUES ('24418645-501b-4d00-ac34-f378aafd5189', 'HORSE_LEASE_V2', 'PAYMENT_METHOD', 'PAYMENT_METHOD.MAIN_LESSOR', 'Payments by the Lessor', 'The Lessor may pay amounts owed under this Agreement by the following method(s): {{TXN.LESSOR_PAYMENT_METHODS}}', 'input', 30, false, NULL, NULL, NULL, '2026-07-23 05:52:43.39427+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8e4a7044-771e-4402-b919-e667419016b9', 'HORSE_LEASE_V2', 'PAYMENT_METHOD', 'PAYMENT_METHOD.CARD_LESSOR', NULL, 'Credit card payments are processed as follows: {{TXN.LESSOR_CARD_PROCESSOR}}', 'input', 40, false, NULL, '{"contains": ["CREDIT_CARD"], "field_key": "TXN.LESSOR_PAYMENT_METHODS"}', NULL, '2026-07-23 05:52:43.39427+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c18d9f8f-825b-4675-a5ab-085b87f67dcc', 'HORSE_LEASE_V2', 'CARE', 'CARE.TACK', 'Tack', 'When riding and handling the Horse, Lessee shall use only tack in good condition that is properly fitted to the Horse.
{{TXN.TACK_PROHIBITED}}', 'input', 70, false, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('65a78d5a-4a4f-42fa-a5e6-55cfb6267530', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'COMPETITIONS.INTRO', 'Competitions', 'Expenses of competition (entry fees, transportation, and the like) are: {{TXN.COMPETITION_EXPENSES}}.
Any prize money or winnings earned in competition shall belong to: {{TXN.COMPETITION_WINNINGS}}.', 'prose', 300, false, NULL, '{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7a60e575-b8f0-4cbf-90d6-fd7170e0ee11', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.BEHAVIOR_EXC', NULL, 'The Lessor notes the following known exceptions to the behavior of the Horse: {{TXN.BEHAVIOR_EXCEPTIONS}}.', 'input', 32, true, NULL, '{"equals": ["YES"], "field_key": "TXN.BEHAVIOR_HAS_EXCEPTIONS"}', NULL, '2026-07-21 04:51:08.986097+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6305cadc-8639-46f4-989e-e4e32b5c781a', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.OWNERSHIP_LIMITS', NULL, 'Ownership related leasing restrictions: {{TXN.OWNERSHIP_LIMITATIONS}}', 'input', 26, true, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_OWNERSHIP_LIMITS"}', NULL, '2026-07-21 12:52:57.478346+00', false);
INSERT INTO public.contract_clause_defs VALUES ('47554dcb-7267-4d12-94f3-8e771ed7fba5', 'HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.CONDITION_STANDALONE', NULL, 'Except for the warranty of title above and the representations expressly stated in this Bill of Sale, the Horse is sold AS IS, and SELLER MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE, and no warranty is made regarding the Horse''s future soundness, health, temperament, performance, suitability for any discipline or rider, or value. This disclaimer does not limit claims arising from fraud or from breach of the express representations stated in this Bill of Sale. Buyer acknowledges the opportunity to have the Horse examined by a veterinarian of Buyer''s choosing before purchase.', 'prose', 30, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.086175+00', false);
INSERT INTO public.contract_clause_defs VALUES ('48408fbb-22b1-4404-8269-8ae3b95bcfe8', 'HORSE_LEASE_V2', 'SCHEDULE', 'SCHEDULE.MAIN', 'Schedule for Lessee''s Usage', 'Reserved days of use: {{TXN.DAYS_USED}}', 'input', 10, false, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-07-20 21:49:32.565438+00', false);
INSERT INTO public.contract_clause_defs VALUES ('96fcb50d-38c5-4666-abb0-e0213a6f0da6', 'HORSE_LEASE_V2', 'CARE', 'SCHEDULE.CARE_DUTY', 'Lessee''s Responsibility for Care and Exercise', 'Lessee''s use of the Horse is a responsibility as well as a right: regular, consistent exercise and attention are important to the Horse''s health and wellbeing. Lessee is required to maintain regular use and exercise for the Horse on their allowed days, unless Lessee has discussed with and received mutual agreement from the Lessor in writing that one of those days will be used as a rest day for the Horse. If Lessee regularly fails to use and care for the Horse, Lessor may terminate this Agreement.', 'prose', 1, false, NULL, '{"equals": ["YES"], "field_key": "TXN.EXERCISE_INCLUDE"}', NULL, '2026-07-20 21:49:32.565438+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2c30f7d8-4678-4a18-9b54-61341545c0d3', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'TRAINING_LESSONS.LESSONS_ENTITY', 'Lessons', 'Lessee is permitted by Lessor to provide riding lessons with the Horse: {{TXN.LESSONS_ENTITY_PERMITTED}}.', 'input', 255, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"contains": ["LESSONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}]}', NULL, '2026-07-29 01:32:35.488005+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e354c9f2-d6da-460a-9c2a-6a4ea31bfe6b', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.HEALTH', 'Health and Condition Disclosures', 'Seller has disclosed to Buyer all known material information regarding the Horse''s medical conditions, injuries, lameness history, surgeries, allergies, current and past medications, behavioral issues, vices, and prior veterinary concerns, as follows: {{TXN.KNOWN_CONDITIONS}}. Seller represents that these disclosures are true and complete to Seller''s knowledge as of the date of this Bill of Sale.', 'input', 10, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.134383+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8f519e3c-ba4e-4c66-a628-b183ebef44f9', 'HORSE_LEASE_V2', 'DEFINITIONS', 'DEFINITIONS.BENEFICIARIES', NULL, 'Each Lessor Party and each Lessee Party who is not a signatory to this Agreement is an intended third-party beneficiary of the releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement and may enforce them directly.', 'input', 15, false, NULL, NULL, NULL, '2026-07-31 16:54:48.684074+00', false);
INSERT INTO public.contract_clause_defs VALUES ('531aa969-1f82-4332-8b20-9e710c5f8bbe', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PERMITTED_USE.TRAINER', NULL, 'Riding Lessons, Jumping, and Competitions may take place only while a French Heritage Equestrian Approved Trainer or Instructor is present.', 'input', 200, false, NULL, '{"contains": ["LESSONS", "JUMPING", "COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-21 05:47:22.63689+00', false);
INSERT INTO public.contract_clause_defs VALUES ('91f24969-7a8e-4ce7-b141-a4c13be023ca', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.BEHAVIOR', 'Behavior', 'Seller represents that, to Seller''s knowledge, the Horse has no history of dangerous or vicious behavior as of the date of this Bill of Sale, except as disclosed in this Bill of Sale.', 'prose', 20, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.134383+00', false);
INSERT INTO public.contract_clause_defs VALUES ('99979696-487c-4a67-a969-820e5c26efec', 'HORSE_LEASE_V2', 'CARE', 'CARE.PROTECTIVE', 'Protective Equipment', 'Horse must wear protective equipment: {{TXN.PROTECTIVE_REQUIRED}}', 'input', 60, false, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0fb89588-54bc-4b9a-8b1a-eeac2beb2165', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.CONDITION_EXC', NULL, 'The Lessor notes the following known exceptions to the physical condition of the Horse: {{TXN.CONDITION_EXCEPTIONS}}.', 'input', 42, true, NULL, '{"equals": ["YES"], "field_key": "TXN.CONDITION_HAS_EXCEPTIONS"}', NULL, '2026-07-21 04:51:08.986097+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8e347945-c172-41aa-b9a0-5046ed4e7f28', 'HORSE_LEASE_V2', 'GOVERNING_LAW', 'GOVERNING_LAW.CHOICE', 'Governing Law and Venue', 'This Agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Agreement or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'input', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('305ecca4-0434-4ebd-945c-35e6e45ba79c', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PROHIBITED.OTHERS_OTHER', NULL, 'Other persons allowed to ride or handle the Horse: {{TXN.OTHERS_ALLOWED_OTHER}}.', 'input', 490, false, NULL, '{"contains": ["OTHER"], "field_key": "TXN.OTHERS_ALLOWED"}', NULL, '2026-07-24 00:28:31.305973+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c1832293-fb78-4d43-9409-85282518d646', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.TRAIL_RIDING', 'Trail Riding Risks', 'Lessee acknowledges that riding outside an enclosed arena, including trail riding, exposes Lessee and the Horse to additional risks, including uneven terrain, traffic, wildlife, water crossings, and other conditions that may cause the Horse to spook or behave unpredictably. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'prose', 1200, false, NULL, '{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-20 21:49:33.78281+00', false);
INSERT INTO public.contract_clause_defs VALUES ('88123fcd-2855-4cbd-971b-9da5559bdd6a', 'HORSE_LEASE_V2', 'LOCATION', 'LOCATION.INSPECTION', NULL, 'Lessor may inspect the Horse at any time, subject to the reasonable access rules of the facility where the Horse is kept. If Lessor reasonably determines that the Horse is not being properly cared for, Lessor may take possession of the Horse upon written notice to Lessee.', 'prose', 20, false, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('01f04af2-b497-4193-8e29-37f9fdd1f80c', 'HORSE_SALE_V2', 'HORSE', 'HORSE.BEHAVIOR', 'Behavior', 'Seller warrants that, to Seller''s knowledge, the Horse has no history of dangerous or vicious behavior as of the Effective Date of this Agreement, except as disclosed in this Agreement.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-02 14:03:13.281406+00', false);
INSERT INTO public.contract_clause_defs VALUES ('bfee3d5b-7237-4cce-abbe-08d4fd3090a6', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.INJURY_NONE', 'No Serious Injury History', 'Seller represents that, to Seller''s knowledge, no person or animal has suffered serious injury proximately caused by the direct actions of the Horse, including biting, kicking, striking, bucking, rearing, bolting, crushing, or throwing a rider. This representation does not extend to any incident caused primarily by a third party or an external stimulus — such as another horse or rider being at fault, a loose dog, wildlife, a vehicle, or a similar external provocation — where the Horse''s reaction was within the range of normal equine behavior.', 'prose', 30, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["NO"], "field_key": "TXN.INJURY_HISTORY"}]}', NULL, '2026-08-03 20:21:18.134383+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1afcdd7c-3868-4b99-9b80-3bb28f39ee01', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_TAIL', NULL, 'Any out-of-pocket costs for deductibles or other expenses related to the needs of the Horse are to be paid by Lessor, and where Lessee is deemed to be responsible for part or all of a cost paid by Lessor, Lessee shall reimburse Lessor in accordance with the acceptable payment methods stated in this Agreement, or, if Lessee so requests prior to payment by Lessor, Lessee may make such request to pay the billing party directly using a method allowed by that party. Lessee may, with Lessor''s written permission, pay for any or all of Lessor''s portion when paying the billing party directly, and Lessor may reimburse Lessee in accordance with the terms of this Agreement. Lessor assumes and is responsible for all risks and costs not paid or covered by any policy held by either party, including in the event a policy is not in effect at the time of the incident, an incident for which a claim is made is deemed not to be covered by a policy, a payment for a claim made for an incident that is covered by a policy is less than the actual cost incurred, or a claim made to a policy is denied for any reason, except as otherwise expressly allocated in this section or elsewhere in this Agreement.', 'input', 320, false, NULL, '{"equals": ["NO", ""], "field_key": "TXN.MED_NOT_REQUIRED"}', NULL, '2026-07-28 00:36:43.221618+00', true);
INSERT INTO public.contract_clause_defs VALUES ('d69143be-c67a-40da-87e4-a003cc3ab73e', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.INJURY_DISCLOSED', 'Serious Injury History Disclosed', 'Seller discloses that one or more persons or animals have suffered serious injury involving the direct actions of the Horse, as follows, including for each incident the approximate date, the circumstances, the Horse''s actions, and the nature of the injury: {{TXN.INJURY_HISTORY_DETAILS}}. Buyer acknowledges this disclosure and proceeds with knowledge of it.', 'input', 40, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}]}', NULL, '2026-08-03 20:21:18.134383+00', false);
INSERT INTO public.contract_clause_defs VALUES ('30516430-98f6-460a-b323-3aad85fc36b6', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_DEDR_SIMPLE', NULL, 'If a claim is made under any such policy arising from events for which Lessee bears responsibility, whether directly or indirectly, responsibility for any deductible shall be borne by: {{TXN.MED_DED_RESP}}.', 'input', 314, false, NULL, '{"all": [{"equals": ["NO", ""], "field_key": "TXN.MED_NOT_REQUIRED"}, {"any": [{"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MED_LESSOR_STATUS"}, {"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MED_LESSEE_STATUS"}]}]}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('fe645d35-c6d0-431f-b7ef-841e50146c82', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.INJURY_PENDING', NULL, '[Pending — state whether anyone or any animal has been seriously injured by the Horse''s direct actions. This placeholder is replaced by the applicable statement and blocks signing.]', 'prose', 50, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": [""], "field_key": "TXN.INJURY_HISTORY"}]}', NULL, '2026-08-03 20:21:18.134383+00', false);
INSERT INTO public.contract_clause_defs VALUES ('412c8124-5d2e-49ed-904d-ec0308577e5a', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_DEDR_SPLITC', NULL, 'The deductible shall be split between the parties: {{TXN.MED_DED_RESP_SPLIT_LESSOR}} paid by Lessor and {{TXN.MED_DED_RESP_SPLIT_LESSEE}} paid by Lessee.', 'input', 315, false, NULL, '{"all": [{"equals": ["NO", ""], "field_key": "TXN.MED_NOT_REQUIRED"}, {"equals": ["SPLIT"], "field_key": "TXN.MED_DED_RESP"}, {"any": [{"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MED_LESSOR_STATUS"}, {"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.MED_LESSEE_STATUS"}]}]}', NULL, '2026-07-28 00:36:43.221618+00', true);
INSERT INTO public.contract_clause_defs VALUES ('4ea00cfc-5907-48d0-9838-6deb7a0acfb6', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.ENCUMBRANCES', 'Disclosed Encumbrances and Interests', 'Seller discloses the following liens, leases, co-ownership interests, or other encumbrances affecting the Horse, each of which is released or satisfied at or before delivery unless expressly stated otherwise: {{TXN.DISCLOSED_ENCUMBRANCES}}', 'input', 60, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "TXN.HAS_ENCUMBRANCES"}]}', NULL, '2026-08-03 20:21:18.134383+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6338bfae-fedf-4981-b308-5dec7fa01102', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.ENCUMBRANCES_PENDING', NULL, '[Pending — state whether any liens, leases, or other encumbrances affect the Horse. This placeholder is replaced by the applicable statement and blocks signing.]', 'prose', 70, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": [""], "field_key": "TXN.HAS_ENCUMBRANCES"}]}', NULL, '2026-08-03 20:21:18.134383+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e0bb1060-523c-4bbb-ad96-13f8e0693cce', 'HORSE_BILL_OF_SALE', 'BOS_DELIVERY', 'BOS_DELIVERY.TERMS', 'Delivery', 'The Horse is delivered to Buyer at {{TXN.DELIVERY_LOCATION}} on or about {{TXN.DELIVERY_DATE}}. Transport is arranged by {{TXN.TRANSPORT_RESPONSIBLE}} and paid for by {{TXN.TRANSPORT_COST_RESPONSIBLE}}. If Buyer fails to take delivery within 7 days of the agreed date other than due to Seller''s delay, Buyer shall pay board and care for the Horse at {{TXN.BOARD_RATE_AFTER}} per day until delivery occurs, and risk of loss passes to Buyer on the 8th day.', 'input', 10, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.18129+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c0951665-4118-4068-b756-f5e725cd3988', 'HORSE_BILL_OF_SALE', 'BOS_DELIVERY', 'BOS_DELIVERY.RISK', 'Transfer of Title and Risk', 'Title to the Horse passes to Buyer as provided in the Conveyance section above, and risk of loss of or injury to the Horse passes to Buyer upon delivery. This executed Bill of Sale constitutes the instrument of transfer for the Horse, and Seller shall execute any additional transfer document reasonably required by a breed registry, microchip registry, or passport authority.', 'prose', 20, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.18129+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8d1c11eb-605d-4554-9503-aca61739da29', 'HORSE_BILL_OF_SALE', 'BOS_DELIVERY', 'BOS_DELIVERY.PAPERS', 'Registration and Transfer Documents', 'At delivery (or, where installment payment applies, upon payment in full), Seller shall deliver to Buyer the Horse''s registration papers, passport, and any transfer forms required to record the change of ownership, executed by Seller where signature is required. Each party shall cooperate to complete breed registry, microchip registry, and passport transfers promptly, with recording fees paid by {{TXN.TRANSFER_FEES_RESPONSIBLE}}.', 'input', 30, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.18129+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b8f1d54b-0606-4f42-94c2-4aa3c1bd9091', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_STATUS', NULL, 'Lessor: {{TXN.GL_LESSOR_STATUS}} general liability insurance covering the Horse and the activities contemplated by this Agreement.
Lessee: {{TXN.GL_LESSEE_STATUS}} general liability insurance covering the Horse and the activities contemplated by this Agreement.', 'input', 155, false, NULL, '{"equals": ["NO", ""], "field_key": "TXN.GL_NOT_REQUIRED"}', NULL, '2026-07-29 01:32:36.529718+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8a5c0aaa-a8ef-44ba-a36a-507d266ca1cb', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_STATUS', NULL, 'Lessor: {{TXN.MORT_LESSOR_STATUS}} mortality insurance on the Horse.
Lessee: {{TXN.MORT_LESSEE_STATUS}} mortality insurance on the Horse.', 'input', 205, false, NULL, '{"equals": ["NO", ""], "field_key": "TXN.MORT_NOT_REQUIRED"}', NULL, '2026-07-29 01:32:36.529718+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a39a4abe-3f2d-4239-bfc1-8610b9a6d7a0', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_STATUS', NULL, 'Lessor: {{TXN.MED_LESSOR_STATUS}} medical insurance on the Horse.
Lessee: {{TXN.MED_LESSEE_STATUS}} medical insurance on the Horse.', 'input', 308, false, NULL, '{"equals": ["NO", ""], "field_key": "TXN.MED_NOT_REQUIRED"}', NULL, '2026-07-29 01:32:36.529718+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a529c2da-13a3-4249-9bb9-b9ff9731ad60', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_NONE', NULL, 'Lessor has elected not to maintain medical insurance on the Horse. Lessor accepts full risk and responsibility for any and all injury to or illness of the Horse during the term of this Agreement, including all costs of veterinary care arising from such injury or illness, except as otherwise expressly allocated in the Horse Care and Expenses section of this Agreement.', 'input', 305, false, NULL, '{"equals": ["YES"], "field_key": "TXN.MED_NOT_REQUIRED"}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('90b308db-2f8f-49a7-b059-74b07d4bc440', 'HORSE_BILL_OF_SALE', 'BOS_RELEASE', 'BOS_RELEASE.BUYER', 'Release by Buyer', 'Buyer, on behalf of Buyer and anyone claiming by, through, or under Buyer, completely releases, forever discharges, and agrees to hold harmless Seller and Seller''s family members, employees, agents, contractors, successors, and assigns, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Buyer''s examination, trial, handling, riding, or transport of the Horse before delivery, whether caused by the ordinary negligence of any released party or otherwise, and from any and all claims arising after delivery relating to the Horse''s condition, soundness, behavior, suitability, or value. This release does not apply to gross negligence, reckless conduct, intentional misconduct, fraud, or breach of the express representations stated in this Bill of Sale.', 'prose', 10, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["INCLUDED"], "field_key": "TXN.BOS_RELEASE_ELECTION"}]}', NULL, '2026-08-03 20:21:18.229071+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c2ead65e-f0a2-4417-b24d-17811a68eefb', 'HORSE_LEASE_V2', 'TERM', 'TERM.RENEWAL', 'Renewal Terms', 'Renewal terms: {{TXN.RENEWAL_TERMS}}', 'input', 19, false, NULL, '{"equals": ["YES"], "field_key": "TXN.RENEWAL_INCLUDE"}', NULL, '2026-07-20 21:49:32.565438+00', false);
INSERT INTO public.contract_clause_defs VALUES ('fde734e7-5478-4e45-86bd-23a69dcecdc3', 'HORSE_LEASE_V2', 'LOCATION', 'LOCATION.MAIN', 'Location of the Horse', 'Location of the Horse: {{HORSE.CURRENT_LOCATION}}.', 'input', 10, false, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4ec115e8-aa53-4169-96e9-a5e03fe02e99', 'HORSE_LEASE_V2', 'TERM', 'TERM.MAIN', 'Agreement Term', 'Term of this Agreement: {{TXN.LEASE_TERM_TYPE}}. This Agreement begins on {{TXN.LEASE_START}}.', 'input', 10, false, NULL, NULL, NULL, '2026-07-20 21:49:32.565438+00', false);
INSERT INTO public.contract_clause_defs VALUES ('20805bc1-8b71-45ee-87f9-51012be40316', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'TRAINING_LESSONS.TRAINING', 'Training', 'Any professional training of the Horse under this Agreement, including groundwork, schooling, and under-saddle training, shall be conducted only by a French Heritage Equestrian Approved Trainer.', 'input', 270, false, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4917d710-4720-4767-acfd-83fd88d4944c', 'HORSE_LEASE_V2', 'CARE', 'CARE.SUPPLEMENTS', NULL, '{{TXN.MEDICATIONS}}', 'input', 10, true, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6778f24b-a710-4a49-9444-e86faf65d8df', 'HORSE_LEASE_V2', 'TERMINATION', 'TERMINATION.LESSEE', 'Lessee''s Right to Terminate', 'Lessee may terminate this Agreement by giving Lessor at least {{TXN.LESSEE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 10, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('f55e0b60-c850-453e-b704-7c0c28c11917', 'HORSE_LEASE_V2', 'TERMINATION', 'TERMINATION.OWNER', 'Owner''s Right to Terminate', 'Lessor may terminate this Agreement by giving Lessee at least {{TXN.OWNER_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 20, false, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('40d1928a-7f8a-4457-a893-eb3a2934df3e', 'HORSE_LEASE_V2', 'CARE', 'CARE.FARRIER', 'Farrier Care', 'Party responsible for arranging: {{TXN.FARRIER_ARRANGE}}
Party responsible for costs: {{TXN.FARRIER_COST_PARTY}}
Farrier: {{HORSE.FARRIER_NAME}}
Farrier phone: {{HORSE.FARRIER_PHONE}}', 'input', 20, true, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6bee1527-c2f7-41be-baf2-e355f114ea63', 'HORSE_LEASE_V2', 'CARE', 'CARE.ROUTINE_VET', 'Veterinary Care', 'Party responsible for arranging: {{TXN.VET_ARRANGE}}
Party responsible for costs: {{TXN.VET_COST_PARTY}}
Veterinarian: {{HORSE.VET_NAME}}
Practice: {{HORSE.VET_BUSINESS}}
Address: {{HORSE.VET_ADDRESS}}
Veterinarian phone: {{HORSE.VET_PHONE}}', 'input', 30, true, NULL, NULL, NULL, '2026-07-20 21:49:33.162432+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a76c7d6e-b6e3-4420-a399-a4d148349fd9', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.VET_CHECK', 'Pre-Lease Veterinary Examination', 'Pre-lease veterinary examination of the Horse: {{TXN.VET_CHECK_CHOICE}}', 'input', 50, false, NULL, NULL, NULL, '2026-07-20 23:52:25.2913+00', false);
INSERT INTO public.contract_clause_defs VALUES ('96f78dd7-3bd9-4856-b9c3-b4446a88073c', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.OWNERSHIP', 'Ownership of the Horse', 'Lessor warrants that Lessor lawfully owns the Horse — whether owned outright, financed without any restriction that prohibits or limits leasing the Horse, or owned jointly with one or more other owners — and that Lessor has all requisite rights, authority, and (where there are co-owners) permission to enter into this Agreement and lease the Horse.', 'input', 20, false, NULL, NULL, NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('06427863-039c-45cb-9976-e36824f7a756', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PERMITTED_USE.MAIN', 'Permitted Use(s)', 'Lessor grants Lessee the right to use the Horse for the following purpose(s): {{TXN.PERMITTED_ACTIVITIES}}
Lessee shall not use the Horse for any other purpose without Lessor''s prior written consent.', 'input', 100, false, NULL, NULL, NULL, '2026-07-20 21:49:32.565438+00', false);
INSERT INTO public.contract_clause_defs VALUES ('9cea2c91-dd1e-48f7-8052-842ec1842ed7', 'HORSE_LEASE_V2', 'PARTIES', 'PARTIES.INTRO', NULL, 'This Horse Lease Agreement (the "Agreement") is made effective as of {{DOC.EFFECTIVE_DATE}} by and between {{LESSOR.FULL_NAME}} of {{LESSOR.ADDRESS}} ("Lessor") and {{LESSEE.FULL_NAME}} of {{LESSEE.ADDRESS}} ("Lessee").', 'input', 10, false, NULL, NULL, NULL, '2026-07-20 21:43:51.525808+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7e573f68-add0-4dba-8e60-06ce1da3ac75', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Lessee understands that horseback riding and handling horses are inherently dangerous activities. Lessee acknowledges that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. Lessee acknowledges the California common law doctrine of "Primary Assumption of Risk," as established by the California Supreme Court in Knight v. Jewett (1992) 3 Cal.4th 296 and subsequent equine-specific case law (e.g., Levinson v. Owens (2009) 176 Cal.App.4th 1534). Consistent with this precedent, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, expressly and voluntarily assumes all inherent risks associated with riding or handling the Horse, and acknowledges that no Lessor Party owes a duty to protect Lessee from these inherent risks.', 'prose', 950, false, NULL, NULL, NULL, '2026-07-21 02:48:55.640351+00', false);
INSERT INTO public.contract_clause_defs VALUES ('133368fc-ffb1-4772-8683-ad1bf770bab0', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_DED_SIMPLE', NULL, 'If a claim is made under any such policy arising from events for which Lessee bears responsibility, whether directly or indirectly, responsibility for any deductible shall be borne by: {{TXN.GL_DED_RESP}}.', 'input', 162, false, NULL, '{"all": [{"equals": ["NO", ""], "field_key": "TXN.GL_NOT_REQUIRED"}, {"any": [{"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.GL_LESSOR_STATUS"}, {"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.GL_LESSEE_STATUS"}]}]}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c18ad64b-1ab2-4bba-8ca6-cfe09fc33b05', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_DED_SPLITC', NULL, 'The deductible shall be split between the parties: {{TXN.GL_DED_RESP_SPLIT_LESSOR}} paid by Lessor and {{TXN.GL_DED_RESP_SPLIT_LESSEE}} paid by Lessee.', 'input', 164, false, NULL, '{"all": [{"equals": ["NO", ""], "field_key": "TXN.GL_NOT_REQUIRED"}, {"equals": ["SPLIT"], "field_key": "TXN.GL_DED_RESP"}, {"any": [{"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.GL_LESSOR_STATUS"}, {"equals": ["HAS_WILL_MAINTAIN", "WILL_OBTAIN"], "field_key": "TXN.GL_LESSEE_STATUS"}]}]}', NULL, '2026-07-28 00:36:43.221618+00', true);
INSERT INTO public.contract_clause_defs VALUES ('e847cfa6-2be7-4dc5-8c55-42232a112fcf', 'HORSE_BILL_OF_SALE', 'BOS_RELEASE', 'BOS_RELEASE.POST_DELIVERY', 'Post-Delivery Responsibility', 'From and after delivery, the Horse and its actions, behavior, care, and condition are the sole responsibility of Buyer, and Buyer shall indemnify, defend, and hold harmless Seller and Seller''s family members, employees, agents, contractors, successors, and assigns from and against any claim, damage, loss, liability, cost, or expense arising out of the Horse or its use, handling, care, or possession after delivery, except to the extent caused by the gross negligence, reckless conduct, intentional misconduct, or fraud of a released party or by breach of the express representations stated in this Bill of Sale.', 'prose', 20, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["INCLUDED"], "field_key": "TXN.BOS_RELEASE_ELECTION"}]}', NULL, '2026-08-03 20:21:18.229071+00', false);
INSERT INTO public.contract_clause_defs VALUES ('404f268d-4f92-4fe9-9bed-2b0dde16a512', 'HORSE_BILL_OF_SALE', 'BOS_RELEASE', 'BOS_RELEASE.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Bill of Sale that the waiving party does not know or suspect to exist in its favor at the time of this Bill of Sale. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Bill of Sale. This waiver does not apply to claims arising from fraud or from breach of the express representations stated in this Bill of Sale.', 'prose', 30, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["INCLUDED"], "field_key": "TXN.BOS_RELEASE_ELECTION"}]}', NULL, '2026-08-03 20:21:18.229071+00', false);
INSERT INTO public.contract_clause_defs VALUES ('381709e8-70a7-4c31-b2ae-674e9a03bb1d', 'HORSE_BILL_OF_SALE', 'BOS_GOVERNING', 'BOS_GOVERNING.CHOICE', NULL, 'This Bill of Sale is governed by the laws of the State of California. Any dispute arising out of or relating to this Bill of Sale shall be resolved in the same manner as disputes under the parties'' Horse Sale and Purchase Agreement, with the same small-claims and provisional-relief rights stated in that Agreement.', 'prose', 10, false, NULL, '{"equals": ["YES"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.276465+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4933f5cc-462d-4f20-b54a-020ec0f5c662', 'HORSE_BILL_OF_SALE', 'BOS_GOVERNING', 'BOS_GOVERNING.STANDALONE', NULL, 'This Bill of Sale is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Bill of Sale or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'prose', 20, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.276465+00', false);
INSERT INTO public.contract_clause_defs VALUES ('f0dd37bf-cc51-4b7a-8206-566c8cd82fa3', 'HORSE_BILL_OF_SALE', 'BOS_GOVERNING', 'BOS_GOVERNING.PENDING', NULL, '[Pending — state whether a Horse Sale and Purchase Agreement accompanies this Bill of Sale. This placeholder is replaced by the applicable governing-law terms and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-03 20:21:18.276465+00', false);
INSERT INTO public.contract_clause_defs VALUES ('9de4d5de-6918-413a-b493-cb097bffa508', 'HORSE_LEASE_V2', 'TERMINATION', 'TERMINATION.LOSS_OF_USE', 'Termination upon Loss of Use', 'If the Horse becomes unusable for the purposes of this Agreement for any reason, Lessee may terminate this Agreement immediately upon written notice to Lessor. Upon such termination, Lessee is entitled to a prorated refund of any Lease Fee paid for the remaining unused time as of the date of termination.', 'prose', 45, false, NULL, NULL, NULL, '2026-07-27 19:24:47.335707+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2865c6ad-bfd5-4293-abf4-b4322c90fe88', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.COMP_ON', NULL, 'Competitions are restricted as follows: {{TXN.COMP_RESTRICTION}}.', 'input', 360, true, NULL, '{"all": [{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["NO", ""], "field_key": "TXN.COMP_OMIT"}]}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('47717c9d-5c44-4a95-8a4a-94e23048c77b', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.JUMP_OFF', NULL, 'Lessor does not restrict jumping.', 'input', 340, false, NULL, '{"all": [{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.JUMP_OMIT"}]}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a9458556-c466-46da-b35b-52ba5b725261', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.COMP_TITLE', 'Competition Restrictions', '{{TXN.COMP_OMIT}}', 'input', 350, false, NULL, '{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('16d8ef7d-d08e-42f6-8e38-5d6c7e4a24e4', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.COMP_OFF', NULL, 'Lessor does not restrict competitions.', 'input', 370, false, NULL, '{"all": [{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.COMP_OMIT"}]}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('def2cd47-c954-4363-9a82-d1fc95bec550', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'RESTRICT.TRAIL_TITLE', 'Trail-Riding Restrictions', '{{TXN.TRAIL_OMIT}}', 'input', 380, false, NULL, '{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-07-23 08:48:54.735558+00', false);
INSERT INTO public.contract_clause_defs VALUES ('53a6b89a-bf12-4e2b-ac86-ccc8b01934c3', 'HORSE_LEASE_V2', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_INDIVIDUAL', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is at least 18 years of age and has full authority to enter into this Agreement; that Lessee has no physical or mental condition that would prevent Lessee from safely participating in the activities contemplated by this Agreement; and that Lessee has the requisite knowledge and experience to handle and ride the Horse, and will use reasonable care in doing so and follow Lessor''s instructions. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 10, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('533775a6-8e8b-49ac-a4ac-4146c8ddb1a9', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PERMITTED_USE.TRANSPORT', 'Transport of the Horse', 'Transport of the Horse to offsite locations (other than for medical care, which is always permitted): {{TXN.OFFSITE_TRANSPORT}}
For clarity, riding trails attached to the location at which the Horse is kept under this Agreement are not offsite locations. Where Competitions are a permitted activity under this Agreement, transport of the Horse to and from the competition venue for that competition is deemed consented, subject to any competition restrictions stated in this Agreement.', 'input', 500, true, NULL, NULL, NULL, '2026-07-21 05:47:22.63689+00', false);
INSERT INTO public.contract_clause_defs VALUES ('092e03de-aaf1-483c-ad64-880279c7f7ab', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PERMITTED_USE.RELEASES_REQUIRED', 'Releases Required for Authorized Riders', 'All persons other than Lessee must, prior to handling or riding the Horse, have executed a liability release that names the Lessor Parties and the Lessee Parties as released parties, contains an express assumption of the inherent risks of equine activities, has been reviewed and approved by Lessor, and, for any rider under 18 years of age, is signed by the rider''s parent or legal guardian. Lessee is responsible for ensuring this requirement is satisfied before permitting any authorized person to ride or handle the Horse.', 'prose', 495, false, NULL, NULL, NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b8457b10-ff53-49a1-9ad3-3b953801cb43', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PROHIBITED.OTHER', 'Other Allowed Activities', 'Lessee is permitted to engage in the following additional activities with the Horse: {{TXN.ADDITIONAL_ACTIVITIES}}.', 'input', 450, true, NULL, '{"contains": ["BREEDING", "EMOTIONAL_SUPPORT", "FILM_TV_AD", "OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8f08d285-c336-46ac-9628-cce4d14a9af0', 'HORSE_LEASE_V2', 'TERMINATION', 'TERMINATION.SURVIVAL', 'Survival', 'The releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement, and any payment obligations accrued before termination, survive the expiration or termination of this Agreement for any reason.', 'prose', 50, false, NULL, NULL, NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2444a000-84b4-42b1-a4d4-9ac81e5647e9', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.LIMITATION', 'Limitation of Liability', 'Under no circumstances shall either party be liable to the other for any special, consequential, incidental, or punitive damages arising out of or relating to this Agreement. The total aggregate liability of either party (including, respectively, the Lessor Parties and the Lessee Parties) to the other under this Agreement shall not exceed the Horse''s current fair market value of {{HORSE.FAIR_MARKET_VALUE}}. Any amount owed by one party to the other under this Agreement shall be reduced by the amount of any insurance proceeds actually received by the party owed with respect to the same loss. This limitation does not apply to gross negligence, reckless conduct, or intentional misconduct, to either party''s indemnification obligations for third-party claims for bodily injury or death, or to amounts actually covered by insurance available for the loss.', 'prose', 1520, false, NULL, NULL, NULL, '2026-07-27 18:39:24.275588+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1ad3d5af-0405-4ea2-8c96-16e69c80734e', 'HORSE_LEASE_V2', 'PERMITTED_USE', 'PROHIBITED.OTHERS', 'Allowing Others to Ride', 'The following additional persons may ride or handle the Horse without Lessor''s prior permission: {{TXN.OTHERS_ALLOWED}}.
Only the persons identified above shall be permitted to ride or handle the Horse without Lessor''s written permission.', 'input', 480, true, NULL, NULL, NULL, '2026-07-20 21:51:03.659545+00', false);
INSERT INTO public.contract_clause_defs VALUES ('367ea844-068a-4bf1-9500-80599d778099', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC', 'Care, Custody and Control Insurance', 'Lessee shall obtain and maintain, for the duration of this Agreement, care, custody and control insurance covering the Horse while in Lessee''s care, custody, or control, with a death benefit limit of not less than the Horse''s current fair market value of {{HORSE.FAIR_MARKET_VALUE}}, with an effective start date no later than the commencement of this Agreement. Lessee shall provide proof of coverage to Lessor upon request and shall maintain the policy in good standing for the duration of this Agreement; failure to do so constitutes a material breach subject to the Termination for Cause provisions of this Agreement.', 'prose', 400, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c5579235-65b6-4d8d-b279-8165a2a20be5', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.COORDINATION', 'Coordination of Coverage', 'Lessor bears responsibility for loss of, injury to, or death of the Horse, and Lessor''s mortality insurance shall be the first policy noticed and claimed against for any such covered event. Lessee''s care, custody and control insurance is secondary and shall respond only to the extent the loss was caused by Lessee''s gross negligence, reckless conduct, or intentional misconduct. Where a loss was so caused, Lessee shall bear the net cost of any applicable deductible and any uninsured portion of the loss, and the parties shall reimburse one another as necessary to give effect to this allocation regardless of the order in which the policies respond. Each party shall promptly notify its insurer of a covered event and shall cooperate in the submission and adjustment of claims. Absent a determination that Lessee so caused the loss, all deductibles and uninsured amounts remain Lessor''s responsibility.', 'prose', 450, false, NULL, '{"all": [{"equals": ["NO", ""], "field_key": "TXN.MORT_NOT_REQUIRED"}, {"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('ae391f86-4fa6-4d2b-8e19-ef6ce22be646', 'HORSE_LEASE_V2', 'PURPOSE', 'PURPOSE.RECREATION_DEFAULT', 'Purpose of Agreement', '[Pending — select the purpose of this lease. This placeholder is replaced by the applicable purpose language and blocks signing.]', 'input', 12, false, NULL, '{"equals": [""], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('74d08507-6434-470b-8f15-4a119e6d04bf', 'HORSE_LEASE_V2', 'EVALUATION', 'EVALUATION.DATES_INCLUDED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_INCLUDED_LENGTH}} {{TXN.EVAL_INCLUDED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is included at no separate charge, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 20, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["INCLUDED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_INCLUDED_LENGTH"}]}', NULL, '2026-07-28 00:36:43.221618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('05c02d26-d5b2-4631-a4f0-f7119d8bd09d', 'HORSE_SALE_V2', 'PARTIES', 'PARTIES.CO_BUYER', 'Co-Buyer', '{{COBUYER.FULL_NAME}} of {{COBUYER.ADDRESS}} ("Co-Buyer") purchases the Horse jointly with Buyer. Co-Buyer is a Buyer for all purposes of this Agreement, every reference to Buyer includes Co-Buyer, and the representations, covenants, releases, waivers, and payment obligations of Buyer under this Agreement are made by Buyer and Co-Buyer jointly and severally. Buyer and Co-Buyer shall hold title to the Horse as follows: {{TXN.CO_BUYER_TITLE_FORM}}. This Agreement is effective as to Co-Buyer upon Co-Buyer''s execution of it.', 'input', 20, false, NULL, '{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-08-02 14:03:12.586921+00', false);
INSERT INTO public.contract_clause_defs VALUES ('79513f21-2be7-45d6-9183-e9e20e6ed5ef', 'HORSE_SALE_V2', 'PARTIES', 'PARTIES.CO_BUYER_PENDING', NULL, '[Pending — state whether there is a co-buyer. This placeholder is replaced by the applicable terms and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-08-02 14:03:12.634378+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4cc81896-a4f5-4d91-91c2-4bc17010eb37', 'HORSE_SALE_V2', 'PARTIES', 'PARTIES.CO_BUYER_TITLE_DETAIL', NULL, 'Title detail: {{TXN.CO_BUYER_TITLE_DETAIL}}', 'input', 40, false, NULL, '{"any": [{"equals": ["TIC_STATED"], "field_key": "TXN.CO_BUYER_TITLE_FORM"}, {"equals": ["OTHER"], "field_key": "TXN.CO_BUYER_TITLE_FORM"}]}', NULL, '2026-08-02 14:03:12.678354+00', false);
INSERT INTO public.contract_clause_defs VALUES ('cc37eeab-3cef-4722-91a3-85e11f13cdd2', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.SELLER_IND', NULL, '"Seller Parties" means Seller; Seller''s spouse and family and household members, in each case when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Seller''s estate, executors, administrators, legal representatives, successors, and assigns.', 'prose', 10, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:12.721499+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1560a3f4-19df-467b-b0e4-d5c833783f62', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.SELLER_ENT', NULL, '"Seller Parties" means Seller; Seller''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Seller and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:12.764683+00', false);
INSERT INTO public.contract_clause_defs VALUES ('082ae613-2002-48b4-aab2-c144d583ca92', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.SELLER_PENDING', NULL, '[Pending — select whether Seller is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:12.807885+00', false);
INSERT INTO public.contract_clause_defs VALUES ('55bb470e-6bf3-4aa0-9be8-f62922f78d65', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BUYER_IND', NULL, '"Buyer Parties" means Buyer; Buyer''s spouse and family and household members, in each case when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Buyer''s estate, executors, administrators, legal representatives, successors, and assigns.', 'prose', 40, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:12.851524+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0ff17db3-71f5-4378-87cc-6707ff9253a5', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BUYER_ENT', NULL, '"Buyer Parties" means Buyer; Buyer''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Buyer and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'prose', 50, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:12.894434+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b4c57e57-66b7-4bf6-83e4-871d2aa51697', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BUYER_PENDING', NULL, '[Pending — select whether Buyer is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'prose', 60, false, NULL, '{"equals": [""], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:12.948312+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2a295f87-9643-4bea-ad97-d1494ec37cd1', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.CLOSING', NULL, '"Closing" means the moment at which both of the following have occurred: Seller''s receipt of the Purchase Price in full (or, where installment payment applies, receipt of all amounts due at transfer under the installment terms), and delivery of the Horse to Buyer as provided in this Agreement.', 'prose', 70, false, NULL, NULL, NULL, '2026-08-02 14:03:12.996257+00', false);
INSERT INTO public.contract_clause_defs VALUES ('959be128-1c8b-4759-94ee-4446331af514', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BINDING', NULL, 'Each release, waiver, assumption of risk, and covenant made by a party under this Agreement is made by that party on its own behalf and, to the fullest extent permitted by law, binds anyone claiming by, through, or under that party, including that party''s estate, executors, administrators, heirs, legal representatives, successors, assigns, insurers, and subrogees. Each party covenants that it will not permit any person who has not executed this Agreement or a release approved by the other party to ride, handle, or care for the Horse prior to Closing, and each party shall indemnify, defend, and hold harmless the other party''s Seller Parties or Buyer Parties, as applicable, from and against any claim brought by that party''s family members, invitees, or authorized riders arising out of the Horse or the activities contemplated by this Agreement, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'prose', 80, false, NULL, NULL, NULL, '2026-08-02 14:03:13.039483+00', false);
INSERT INTO public.contract_clause_defs VALUES ('f544f15d-ee4c-4f82-a9cf-4cb4e41a0ea5', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BENEFICIARIES', NULL, 'Each Seller Party and each Buyer Party who is not a signatory to this Agreement is an intended third-party beneficiary of the releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement and may enforce them directly.', 'prose', 90, false, NULL, NULL, NULL, '2026-08-02 14:03:13.086982+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6ac27fb6-305f-4cfc-b5aa-1cbc8bc17a54', 'HORSE_SALE_V2', 'HORSE', 'HORSE.IDENTITY', 'Horse', 'This Agreement applies to the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Barn Name: {{HORSE.BARN_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Height: {{HORSE.HEIGHT}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}
Current Location: {{HORSE.CURRENT_LOCATION}}', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:13.143093+00', false);
INSERT INTO public.contract_clause_defs VALUES ('c10179d9-d2ee-451e-866e-aeb4f4cb9213', 'HORSE_SALE_V2', 'HORSE', 'HORSE.OWNERSHIP', 'Title and Ownership', 'Seller warrants that Seller lawfully owns the Horse, holds good and marketable title to the Horse, free and clear of all liens, security interests, leases, breeding contracts, co-ownership interests, and encumbrances except as expressly disclosed in this Agreement, and has all requisite rights, authority, and (where there are co-owners) permission to enter into this Agreement and sell the Horse.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 14:03:13.190637+00', false);
INSERT INTO public.contract_clause_defs VALUES ('df08d130-53f4-4872-be7d-1c99d4366ce7', 'HORSE_SALE_V2', 'HORSE', 'HORSE.ENCUMBRANCES', 'Disclosed Encumbrances and Interests', 'Seller discloses the following liens, leases, co-ownership interests, or other encumbrances affecting the Horse, each of which will be released or satisfied at or before Closing unless expressly stated otherwise: {{TXN.DISCLOSED_ENCUMBRANCES}}', 'input', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_ENCUMBRANCES"}', NULL, '2026-08-02 14:03:13.238079+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e78a7e1c-40b8-4e60-8eb6-a0413ed8510a', 'HORSE_SALE_V2', 'HORSE', 'HORSE.DISCLOSURES', 'Health and Condition Disclosures', 'Seller has disclosed to Buyer all known material information regarding the Horse''s medical conditions, injuries, lameness history, surgeries, allergies, current and past medications, behavioral issues, vices, and prior veterinary concerns, as follows: {{TXN.KNOWN_CONDITIONS}}. Seller warrants that these disclosures are true and complete to Seller''s knowledge as of the Effective Date, and shall promptly disclose any material change arising before Closing.', 'input', 50, false, NULL, NULL, NULL, '2026-08-02 14:03:13.32491+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a68e8828-56d2-4f4d-b37b-77d696771bec', 'HORSE_SALE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_NONE', 'No Serious Injury History', 'Seller represents that, to Seller''s knowledge, no person has suffered serious injury proximately caused by the direct actions of the Horse, including biting, kicking, striking, bucking, rearing, bolting, crushing, or throwing a rider. This representation does not extend to any incident caused primarily by a third party or an external stimulus — such as another horse or rider being at fault, a loose dog, wildlife, a vehicle, or a similar external provocation — where the Horse''s reaction was within the range of normal equine behavior.', 'input', 60, false, NULL, '{"equals": ["NO"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 14:03:13.372006+00', false);
INSERT INTO public.contract_clause_defs VALUES ('6fb44add-768b-4071-9a6f-57eaebaa4b23', 'HORSE_SALE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_DISCLOSED', 'Serious Injury History Disclosed', 'Seller discloses that one or more persons have suffered serious injury involving the direct actions of the Horse, as follows, including for each incident the approximate date, the circumstances, the Horse''s actions, and the nature of the injury: {{TXN.INJURY_HISTORY_DETAILS}}. Buyer acknowledges this disclosure and proceeds with knowledge of it.', 'input', 70, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 14:03:13.415595+00', false);
INSERT INTO public.contract_clause_defs VALUES ('ffd3b8fd-10da-422b-9ce6-256068dc4f76', 'HORSE_SALE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_PENDING', NULL, '[Pending — state whether anyone has been seriously injured by the Horse''s direct actions. This placeholder is replaced by the applicable statement and blocks signing.]', 'input', 80, false, NULL, '{"equals": [""], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 14:03:13.459252+00', false);
INSERT INTO public.contract_clause_defs VALUES ('dd302a61-c66d-413f-8eab-58d9b727b8ed', 'HORSE_SALE_V2', 'HORSE', 'HORSE.BREEDING', 'Breeding Warranty', 'Seller expressly warrants that, to Seller''s knowledge, the Horse is capable of breeding and free of any reproductive condition that would prevent it, as supported by the reproductive examination or records described here: {{TXN.BREEDING_BASIS}}. If a licensed veterinarian determines within {{TXN.BREEDING_CLAIM_WINDOW}} days after Closing that the Horse was incapable of breeding as of Closing due to a condition existing at Closing, Buyer''s exclusive remedy is, at Buyer''s election, return of the Horse in substantially the condition delivered for a refund of the Purchase Price, or a reduction of the Purchase Price agreed by the parties. This is the sole warranty regarding breeding and does not otherwise limit the Disclaimer of Warranties.', 'input', 90, false, NULL, '{"equals": ["INCLUDED"], "field_key": "TXN.BREEDING_ELECTION"}', NULL, '2026-08-02 14:03:13.506345+00', false);
INSERT INTO public.contract_clause_defs VALUES ('212eb8a8-a80f-4941-8c62-5f55aef54eaf', 'HORSE_SALE_V2', 'HORSE', 'HORSE.BREEDING_DECLINED', 'Breeding Warranty Not Elected', 'No warranty of breeding soundness, fertility, or reproductive capacity is given or implied. The parties considered including a breeding warranty and both elected not to include one.', 'prose', 100, false, NULL, '{"equals": ["NOT_INCLUDED"], "field_key": "TXN.BREEDING_ELECTION"}', NULL, '2026-08-02 14:03:13.549137+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2926d83f-95a7-4334-aa68-10436db3363c', 'HORSE_SALE_V2', 'HORSE', 'HORSE.WARRANTY', 'Disclaimer of Warranties', 'Except for the representations and warranties expressly stated in this Agreement, the Horse is sold AS IS, and SELLER MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE, and no warranty is made regarding the Horse''s future soundness, health, temperament, performance, suitability for any discipline or rider, or value. This disclaimer does not limit Buyer''s rights arising from the express representations in this Agreement or from fraud.', 'prose', 110, false, NULL, NULL, NULL, '2026-08-02 14:03:13.592762+00', false);
INSERT INTO public.contract_clause_defs VALUES ('be00874e-a67a-4174-917a-eb0d23d84fd0', 'HORSE_SALE_V2', 'PURPOSE_SALE', 'PURPOSE_SALE.MAIN', 'Purpose of Agreement', 'Seller owns the horse described in this Agreement and desires to sell it, and Buyer desires to purchase it, on the terms and conditions of this Agreement.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:13.635517+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2de69002-b0c6-455b-9a5a-8c22c92d6a25', 'HORSE_SALE_V2', 'PURPOSE_SALE', 'PURPOSE_SALE.SALE', 'Agreement to Sell and Purchase', 'Subject to the terms and conditions of this Agreement, Seller agrees to sell, transfer, and convey the Horse to Buyer, and Buyer agrees to purchase the Horse from Seller, for the Purchase Price and on the terms stated in this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 14:03:13.683212+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b77f51c4-5982-4648-a6f7-4fdee522f848', 'HORSE_SALE_V2', 'PRICE', 'PRICE.AMOUNT', 'Purchase Price', 'The purchase price for the Horse is {{TXN.PURCHASE_PRICE}} (the "Purchase Price").', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:13.726309+00', false);
INSERT INTO public.contract_clause_defs VALUES ('180e2806-976e-4483-975b-12bc14904253', 'HORSE_SALE_V2', 'PRICE', 'PRICE.DEPOSIT', 'Deposit', 'Buyer shall pay a deposit of {{TXN.DEPOSIT_AMOUNT}} (the "Deposit") upon execution of this Agreement. The Deposit is applied against the Purchase Price at Closing. If this Agreement terminates because a condition precedent stated in this Agreement fails (including an unsatisfactory pre-purchase examination where the sale is contingent on one, a financing contingency that fails where one is included, or a trial period return in accordance with this Agreement), the Deposit is refunded to Buyer in full within 5 business days. If Buyer fails to complete the purchase for any other reason, the parties agree that Seller''s actual damages would be impracticable or extremely difficult to determine, that the Deposit is a reasonable estimate of those damages, and that Seller may retain the Deposit as liquidated damages as Seller''s sole monetary remedy for that failure.', 'input', 20, false, NULL, '{"equals": ["YES"], "field_key": "TXN.DEPOSIT_ENABLED"}', NULL, '2026-08-02 14:03:13.773992+00', false);
INSERT INTO public.contract_clause_defs VALUES ('d997336a-caf2-41eb-a8fd-e82e73a65a49', 'HORSE_SALE_V2', 'PRICE', 'PRICE.PAYMENT_METHOD', 'Payment Method', 'The Purchase Price shall be paid by the following method(s): {{TXN.PAYMENT_METHODS}}. Payment is not received until funds are actually and irrevocably credited to Seller.', 'input', 30, false, NULL, NULL, NULL, '2026-08-02 14:03:13.821356+00', false);
INSERT INTO public.contract_clause_defs VALUES ('88f313d7-724e-4636-896f-f97b3ccf7b7d', 'HORSE_SALE_V2', 'PRICE', 'PRICE.FULL_PAYMENT', 'Payment in Full at Transfer', 'The Purchase Price, less any Deposit already paid, is due in full at or before delivery of the Horse. Seller is not obligated to deliver the Horse or any registration or transfer documents until the Purchase Price is received in full.', 'prose', 40, false, NULL, '{"equals": ["NO"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-08-02 14:03:13.865698+00', false);
INSERT INTO public.contract_clause_defs VALUES ('f7e32bcc-5259-4855-969d-c2fb418d7649', 'HORSE_SALE_V2', 'REPS', 'REPS.BUYER_IND', 'Buyer''s Representations', 'Buyer represents and warrants that Buyer is at least 18 years of age and has full authority to enter into this Agreement; that Buyer has had the opportunity to inspect the Horse, to have the Horse examined by a veterinarian of Buyer''s choosing, and to ask questions about the Horse; and that Buyer has the knowledge and experience to evaluate the Horse''s suitability for Buyer''s intended use. By signing this Agreement, Buyer acknowledges that Buyer has read this Agreement, fully understands its terms, and understands that Buyer is giving up substantial legal rights on behalf of Buyer and anyone claiming by, through, or under Buyer, including the right to sue the Seller Parties.', 'prose', 20, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:15.630369+00', false);
INSERT INTO public.contract_clause_defs VALUES ('10096afa-6a49-4219-bcfb-f5f929caec39', 'HORSE_SALE_V2', 'PRICE', 'PRICE.INSTALLMENTS', 'Installment Terms', 'The Purchase Price is payable in installments as follows: {{TXN.INSTALLMENT_SCHEDULE}}. Until the Purchase Price is paid in full: title to the Horse remains with Seller and Buyer holds possession under this Agreement only; Buyer grants Seller a purchase-money security interest in the Horse and its registration papers to secure the unpaid balance, and authorizes Seller to file a financing statement; Buyer shall not sell, lease, encumber, breed, or relocate the Horse from {{TXN.INSTALLMENT_LOCATION}} without Seller''s prior written consent; Buyer shall maintain mortality insurance on the Horse in an amount not less than the unpaid balance, naming Seller as loss payee, and shall provide proof on request; and Buyer bears all costs of the Horse''s care. If Buyer fails to make a payment when due and does not cure within 10 days of written notice, Seller may retake possession of the Horse, and amounts already paid are subject to the default and remedies provisions of this Agreement. Registration and transfer documents are delivered upon payment in full.', 'input', 50, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-08-02 14:03:13.91325+00', false);
INSERT INTO public.contract_clause_defs VALUES ('10b44a2a-8762-4c17-9763-e0d015584b39', 'HORSE_SALE_V2', 'PRICE', 'PRICE.INSTALLMENTS_PENDING', NULL, '[Pending — select whether the Purchase Price is paid in full at transfer or in installments. This placeholder is replaced by the applicable payment terms and blocks signing.]', 'prose', 60, false, NULL, '{"equals": [""], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-08-02 14:03:13.956708+00', false);
INSERT INTO public.contract_clause_defs VALUES ('13d65c8c-88d6-482e-adac-809a01905876', 'HORSE_SALE_V2', 'PRICE', 'PRICE.FINANCING', 'Financing Contingency', 'This sale is contingent on Buyer obtaining financing for not less than {{TXN.FINANCING_AMOUNT}} on terms reasonably acceptable to Buyer on or before {{TXN.FINANCING_DEADLINE}}. Buyer shall pursue financing diligently and in good faith. If Buyer gives Seller written notice on or before that date that financing could not be obtained, this Agreement terminates, the Deposit (if any) is refunded in full, and neither party has further obligation to the other except obligations that expressly survive. If no such notice is given by that date, this contingency is deemed waived.', 'input', 70, false, NULL, '{"equals": ["INCLUDED"], "field_key": "TXN.FINANCING_ELECTION"}', NULL, '2026-08-02 14:03:14.003916+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2700671c-ef8c-474c-814a-648a9dc4aee6', 'HORSE_SALE_V2', 'PRICE', 'PRICE.FINANCING_DECLINED', 'Financing Contingency Not Elected', 'This sale is not contingent on Buyer obtaining financing. The parties considered including a financing contingency and both elected not to include one.', 'prose', 80, false, NULL, '{"equals": ["NOT_INCLUDED"], "field_key": "TXN.FINANCING_ELECTION"}', NULL, '2026-08-02 14:03:14.051477+00', false);
INSERT INTO public.contract_clause_defs VALUES ('9f697a70-5ae0-40b5-949c-ece6f5ca744e', 'HORSE_SALE_V2', 'PRICE', 'PRICE.TAXES', 'Taxes', 'Any sales, use, or similar transfer tax arising from this sale is the responsibility of {{TXN.SALES_TAX_RESPONSIBLE}}. Each party is otherwise responsible for its own tax obligations arising from this transaction.', 'input', 90, false, NULL, NULL, NULL, '2026-08-02 14:03:14.105734+00', false);
INSERT INTO public.contract_clause_defs VALUES ('650cb2ad-de25-4be4-9060-673c398c9fe0', 'HORSE_SALE_V2', 'PPE', 'PPE.CONDUCTED', 'Pre-Purchase Examination', 'Buyer may, at Buyer''s sole cost, have the Horse examined by a licensed veterinarian of Buyer''s choosing on or before {{TXN.PPE_DEADLINE}}. Seller shall make the Horse reasonably available for the examination and shall disclose the Horse''s known medical history to the examining veterinarian on request.', 'input', 10, false, NULL, '{"equals": ["CONDUCTED"], "field_key": "TXN.PPE_CHOICE"}', NULL, '2026-08-02 14:03:14.161612+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7001c7e2-4d3c-4974-b960-629a4627e258', 'HORSE_SALE_V2', 'PPE', 'PPE.CONTINGENCY', 'Sale Contingent on Examination', 'This sale is contingent on a pre-purchase examination whose results are satisfactory to Buyer in Buyer''s reasonable discretion. If Buyer gives Seller written notice on or before {{TXN.PPE_DEADLINE}} that the examination results are not satisfactory, this Agreement terminates, the Deposit (if any) is refunded in full, and neither party has further obligation to the other except obligations that expressly survive. If Buyer gives no such notice by that date, this contingency is deemed waived.', 'input', 20, false, NULL, '{"all": [{"equals": ["CONDUCTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["YES"], "field_key": "TXN.PPE_CONTINGENT"}]}', NULL, '2026-08-02 14:03:14.222098+00', false);
INSERT INTO public.contract_clause_defs VALUES ('eabac1d8-f5b7-424c-8815-75faf25dcccf', 'HORSE_SALE_V2', 'PPE', 'PPE.WAIVED', 'Examination Waived', 'Buyer has been advised to obtain an independent pre-purchase veterinary examination of the Horse and knowingly and voluntarily waives it. Buyer accepts the Horse without such examination and assumes all risk associated with conditions an examination might have revealed. This waiver does not limit Buyer''s rights arising from the express representations in this Agreement or from fraud.', 'prose', 30, false, NULL, '{"equals": ["WAIVED"], "field_key": "TXN.PPE_CHOICE"}', NULL, '2026-08-02 14:03:14.265609+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e24203bd-c163-4c48-9696-bd4d5ba29962', 'HORSE_SALE_V2', 'PPE', 'PPE.PENDING', NULL, '[Pending — select whether a pre-purchase examination will be conducted or is waived. This placeholder is replaced by the applicable examination terms and blocks signing.]', 'prose', 40, false, NULL, '{"equals": [""], "field_key": "TXN.PPE_CHOICE"}', NULL, '2026-08-02 14:03:14.313133+00', false);
INSERT INTO public.contract_clause_defs VALUES ('578afa96-4d58-4166-a76c-f6037bdda7c3', 'HORSE_SALE_V2', 'PPE', 'PPE.DRUG_TESTING', 'Drug and Substance Testing', 'At the pre-purchase examination or at delivery, whichever Buyer elects, Buyer may, at Buyer''s cost, have a licensed veterinarian draw blood or other samples from the Horse. Samples shall be split, sealed, and identified in the presence of both parties or their representatives, with one set retained by the veterinarian or a certified testing laboratory. Buyer may have the samples tested for prohibited, masking, or performance- or behavior-altering substances within {{TXN.DRUG_TEST_WINDOW}} days after collection. If a certified laboratory confirms the presence of such a substance not disclosed in this Agreement and not administered under a disclosed current veterinary prescription, Buyer may rescind this Agreement by written notice within 5 business days of receiving the confirmed result, return the Horse in substantially the condition delivered, and receive a refund of all amounts paid including the Deposit, and Seller shall reimburse Buyer''s reasonable testing and return transport costs.', 'input', 50, false, NULL, '{"equals": ["INCLUDED"], "field_key": "TXN.DRUG_TEST_ELECTION"}', NULL, '2026-08-02 14:03:14.357064+00', false);
INSERT INTO public.contract_clause_defs VALUES ('55fb041d-b93a-4c0a-9ec1-afd128cd0f15', 'HORSE_SALE_V2', 'PPE', 'PPE.DRUG_TESTING_DECLINED', 'Drug and Substance Testing Not Elected', 'Buyer was offered the opportunity to have samples drawn from the Horse and tested for prohibited, masking, or performance- or behavior-altering substances, and the parties elected not to include drug testing. Buyer assumes the risk that the Horse''s condition or behavior at examination, trial, or delivery may have been affected by a substance present at that time.', 'prose', 60, false, NULL, '{"equals": ["NOT_INCLUDED"], "field_key": "TXN.DRUG_TEST_ELECTION"}', NULL, '2026-08-02 14:03:14.404111+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8ee7ca79-4e9f-4903-8129-89743b5bff38', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.TERMS', 'Trial Period', 'Buyer may keep and ride the Horse on trial from {{TXN.TRIAL_START}} to {{TXN.TRIAL_END}} at {{TXN.TRIAL_LOCATION}}. During the trial period: Buyer bears all costs of the Horse''s board, care, and routine maintenance; Buyer shall use the Horse only for ordinary riding and evaluation consistent with the Horse''s training and shall not compete, breed, transport offsite (other than for veterinary care, which is always permitted), or permit third parties to ride the Horse without Seller''s written consent; Buyer assumes all risk of injury to persons arising from the Horse during the trial period as provided in the Risk, Release, and Indemnification section of this Agreement; and Buyer shall maintain, at {{TXN.TRIAL_INSURANCE_RESPONSIBLE}}''s cost, mortality insurance on the Horse in an amount not less than the Purchase Price for the duration of the trial. If the Horse dies or is significantly injured during the trial period due to Buyer''s failure to provide reasonable care, Buyer is responsible for the Purchase Price; otherwise Seller bears the risk of loss of the Horse itself during the trial. Buyer may return the Horse in substantially the condition received, on written notice given on or before {{TXN.TRIAL_END}}, in which case this Agreement terminates and the Deposit (if any) is refunded in full; if no such notice is given by that date, Buyer is deemed to have accepted the Horse and Closing proceeds under this Agreement.', 'input', 10, false, NULL, '{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}', NULL, '2026-08-02 14:03:14.451713+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8a3f1535-e61c-4e0d-8b7a-7c14fc2343c0', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.NONE', NULL, 'No trial period applies to this sale.', 'prose', 20, false, NULL, '{"equals": ["NO"], "field_key": "TXN.TRIAL_ENABLED"}', NULL, '2026-08-02 14:03:14.495695+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b0609c3e-af0c-442f-9437-c371cd4ededb', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.PENDING', NULL, '[Pending — select whether a trial period applies. This placeholder is replaced by the applicable trial terms and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "TXN.TRIAL_ENABLED"}', NULL, '2026-08-02 14:03:14.539205+00', false);
INSERT INTO public.contract_clause_defs VALUES ('73309130-0026-4ab9-93f9-8475f050f4c9', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.TERMS', 'Delivery', 'The Horse shall be delivered to Buyer at {{TXN.DELIVERY_LOCATION}} on or about {{TXN.DELIVERY_DATE}}. Transport is arranged by {{TXN.TRANSPORT_RESPONSIBLE}} and paid for by {{TXN.TRANSPORT_COST_RESPONSIBLE}}. If Buyer fails to take delivery within 7 days of the agreed date other than due to Seller''s delay, Buyer shall pay board and care for the Horse at {{TXN.BOARD_RATE_AFTER}} per day until delivery occurs, and risk of loss passes to Buyer on the 8th day.', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:14.582067+00', false);
INSERT INTO public.contract_clause_defs VALUES ('48344f7b-8edb-48fc-9296-28d5c466f951', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.TITLE_RISK', 'Transfer of Title and Risk', 'Except as otherwise provided in the Installment Terms, title to the Horse passes to Buyer at Closing, and risk of loss of or injury to the Horse passes to Buyer upon delivery. Upon Closing, this executed Agreement, together with the executed Bill of Sale, constitutes the instruments of transfer for the Horse, and Seller shall execute any additional transfer document reasonably required by a breed registry, microchip registry, or passport authority.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 14:03:14.625234+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2d304187-9ccc-4128-9c60-003f90c8ec95', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.PAPERS', 'Registration and Transfer Documents', 'At Closing (or, where installment payment applies, upon payment in full), Seller shall deliver to Buyer the Horse''s registration papers, passport, and any transfer forms required to record the change of ownership, executed by Seller where signature is required. Each party shall cooperate to complete breed registry, microchip registry, and passport transfers promptly, with recording fees paid by {{TXN.TRANSFER_FEES_RESPONSIBLE}}.', 'input', 30, false, NULL, NULL, NULL, '2026-08-02 14:03:14.677869+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e38a9bf1-ca16-4805-a93d-d08acf004d1f', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.NO_SLAUGHTER', 'No-Slaughter Covenant', 'Buyer covenants that Buyer will not sell, transfer, consign, or deliver the Horse, directly or through intermediaries, for slaughter or for human consumption, whether within or outside California, and will not sell or transfer the Horse at auction without commercially reasonable steps to ensure the Horse is not being acquired for slaughter. The parties acknowledge that California Penal Code Section 598c makes it unlawful to possess, import, export, sell, or transfer a horse with the intent that it be killed for human consumption. This covenant survives Closing and binds Buyer''s successors in interest to the extent permitted by law.', 'prose', 40, false, NULL, '{"equals": ["INCLUDED"], "field_key": "TXN.NO_SLAUGHTER_ELECTION"}', NULL, '2026-08-02 14:03:14.725264+00', false);
INSERT INTO public.contract_clause_defs VALUES ('ce40cb54-8f79-4f5a-825b-3c57a4aa6f35', 'HORSE_SALE_V2', 'RISK', 'RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Each party understands that horseback riding and handling horses are inherently dangerous activities, and that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. In connection with any examination, trial, handling, riding, transport, or delivery of the Horse under this Agreement, each party, on behalf of itself and anyone claiming by, through, or under it, expressly and voluntarily assumes all inherent risks of equine activities, and acknowledges that the other party''s Seller Parties or Buyer Parties, as applicable, owe no duty to protect it from those inherent risks.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:14.772214+00', false);
INSERT INTO public.contract_clause_defs VALUES ('87c89925-3cc8-43f1-a306-e1f20839f883', 'HORSE_SALE_V2', 'RISK', 'RISK.RELEASE_BUYER', 'Release by Buyer', 'Buyer, on behalf of Buyer and anyone claiming by, through, or under Buyer, completely releases, forever discharges, and agrees to hold harmless the Seller Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Buyer''s examination, trial, handling, riding, or transport of the Horse before Closing, whether caused by the ordinary negligence of any Seller Party or otherwise, and from any and all claims arising after Closing relating to the Horse''s condition, soundness, behavior, suitability, or value. This release does not apply to gross negligence, reckless conduct, intentional misconduct, fraud, or breach of the express representations and warranties stated in this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 14:03:14.81968+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a13a8998-f99f-4e79-8254-df9955c5ea12', 'HORSE_SALE_V2', 'RISK', 'RISK.RELEASE_SELLER', 'Release by Seller', 'Seller, on behalf of Seller and anyone claiming by, through, or under Seller, completely releases, forever discharges, and agrees to hold harmless the Buyer Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Seller''s riding or handling of the Horse or Seller''s presence at any facility where the Horse is kept in connection with this Agreement, whether caused by the ordinary negligence of any Buyer Party or otherwise. This release does not apply to gross negligence, reckless conduct, intentional misconduct, or fraud.', 'prose', 30, false, NULL, NULL, NULL, '2026-08-02 14:03:14.862907+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1afd1604-549c-4ab3-8d3b-acf1f577eb2f', 'HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.PENDING', NULL, '[Pending — state whether a Horse Sale and Purchase Agreement accompanies this Bill of Sale. This placeholder is replaced by the applicable condition language and blocks signing.]', 'prose', 40, false, NULL, '{"equals": [""], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-02 14:03:16.825255+00', false);
INSERT INTO public.contract_clause_defs VALUES ('a7562d89-bf21-4d32-a6ee-a074653aaff6', 'HORSE_SALE_V2', 'RISK', 'RISK.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Agreement that the waiving party does not know or suspect to exist in its favor at the time of this Agreement. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Agreement. This waiver does not apply to claims arising from fraud or from breach of the express representations and warranties stated in this Agreement.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-02 14:03:14.906136+00', false);
INSERT INTO public.contract_clause_defs VALUES ('91067cc5-e3c5-476a-a922-2fcff004b867', 'HORSE_SALE_V2', 'RISK', 'RISK.POST_CLOSING', 'Post-Closing Responsibility', 'From and after Closing, the Horse and its actions, behavior, care, and condition are the sole responsibility of Buyer, and Buyer shall indemnify, defend, and hold harmless the Seller Parties from and against any claim, damage, loss, liability, cost, or expense arising out of the Horse or its use, handling, care, or possession after Closing, except to the extent caused by the gross negligence, reckless conduct, intentional misconduct, or fraud of a Seller Party or by breach of the express representations and warranties stated in this Agreement.', 'prose', 50, false, NULL, NULL, NULL, '2026-08-02 14:03:14.953764+00', false);
INSERT INTO public.contract_clause_defs VALUES ('10a12475-1071-4f7d-985e-c68f45b16019', 'HORSE_SALE_V2', 'RISK', 'RISK.PRE_CLOSING', 'Pre-Closing Responsibility', 'Before Closing, and except as allocated to Buyer during any trial period, Seller shall indemnify, defend, and hold harmless the Buyer Parties from and against any third-party claim arising out of the Horse''s ownership, care, or condition, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of a Buyer Party.', 'prose', 60, false, NULL, NULL, NULL, '2026-08-02 14:03:14.996756+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7f00aaa9-5c53-4019-bf05-866991d50c58', 'HORSE_SALE_V2', 'DEFAULT', 'DEFAULT.CURE', 'Default and Cure', 'A party in material breach of this Agreement has 10 days after written notice of the breach to cure it, except that no cure period applies to Buyer''s failure to complete the purchase after all conditions precedent are satisfied or waived, which is governed by the Deposit clause where a Deposit applies.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.044293+00', false);
INSERT INTO public.contract_clause_defs VALUES ('69c23dce-9b53-4705-b95b-e275cf078abf', 'HORSE_SALE_V2', 'DEFAULT', 'DEFAULT.SELLER', 'Seller Default', 'If Seller fails to complete the sale after all conditions precedent are satisfied or waived, Buyer is entitled to a full refund of the Deposit and all other amounts paid, and, because the Horse is unique, Buyer may alternatively seek specific performance of this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 14:03:15.087499+00', false);
INSERT INTO public.contract_clause_defs VALUES ('bc73fc75-2e4a-4529-932f-8e7c300b8d31', 'HORSE_SALE_V2', 'DEFAULT', 'DEFAULT.INSTALLMENTS', 'Buyer Default Under Installments', 'If Seller retakes possession of the Horse following Buyer''s uncured installment default, Seller shall, within 60 days, elect either to retain the Horse and refund amounts paid in excess of the greater of the Deposit and 20 percent of the Purchase Price, or to resell the Horse in a commercially reasonable manner and account to Buyer for any amount received in excess of the unpaid balance plus Seller''s reasonable costs of retaking, keeping, and reselling the Horse.', 'prose', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-08-02 14:03:15.135051+00', false);
INSERT INTO public.contract_clause_defs VALUES ('27e259b4-0a05-404d-8423-28c924757e82', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.FORM', 'Form of Notice', 'Any notice required or permitted under this Agreement shall be in writing and delivered by a method that provides evidence of receipt to the party at the contact information below. Notice by email is not effective unless the receiving party acknowledges receipt.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.178193+00', false);
INSERT INTO public.contract_clause_defs VALUES ('2bf8bae8-686d-45ee-8a80-b824db05c1bf', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.SELLER_ADDRESS', 'Seller', 'Name: {{SELLER.FULL_NAME}}
Address: {{SELLER.ADDRESS}}
Phone: {{SELLER.PHONE}}
Email: {{SELLER.EMAIL}}', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 14:03:15.225683+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8041210a-fe06-4cf3-94eb-b502827163c5', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.BUYER_ADDRESS', 'Buyer', 'Name: {{BUYER.FULL_NAME}}
Address: {{BUYER.ADDRESS}}
Phone: {{BUYER.PHONE}}
Email: {{BUYER.EMAIL}}', 'prose', 30, false, NULL, NULL, NULL, '2026-08-02 14:03:15.269649+00', false);
INSERT INTO public.contract_clause_defs VALUES ('7585f0ec-8987-44a0-9990-e42ed52d4b2e', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.CHANGES', 'Changes in Contact Information', 'Each party shall promptly notify the other party in writing of any change in the party''s address or contact information.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-02 14:03:15.313193+00', false);
INSERT INTO public.contract_clause_defs VALUES ('059e6cdb-2126-4833-a6a6-211825a63341', 'HORSE_SALE_V2', 'ASSIGNMENT', 'ASSIGNMENT.NO_ASSIGN', 'Assignment', 'Neither party shall assign this Agreement or any of its rights or obligations under it without the other party''s prior written consent.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.355991+00', false);
INSERT INTO public.contract_clause_defs VALUES ('e8e5682e-9c7e-4302-bb8b-3feade660fac', 'HORSE_SALE_V2', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions, advertisements, and understandings, and Buyer acknowledges that Buyer is not relying on any statement or representation regarding the Horse that is not stated in this Agreement. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.403618+00', false);
INSERT INTO public.contract_clause_defs VALUES ('b1286f8a-ee4f-40a6-993a-889c05751a83', 'HORSE_SALE_V2', 'GOVERNING_LAW', 'GOVERNING_LAW.CHOICE', 'Governing Law and Dispute Resolution', 'This Agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Agreement or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.446805+00', false);
INSERT INTO public.contract_clause_defs VALUES ('1e7282d1-e4e4-4ac3-82d3-813776f7651e', 'HORSE_SALE_V2', 'ATTORNEYS_FEES', 'ATTORNEYS_FEES.PREVAILING', 'Attorneys'' Fees', 'Each party shall cover their own attorney''s fees and costs.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.494336+00', false);
INSERT INTO public.contract_clause_defs VALUES ('49d792a9-ce23-44a4-8d0e-67e3b616b660', 'HORSE_SALE_V2', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.539609+00', false);
INSERT INTO public.contract_clause_defs VALUES ('8a13190a-2b91-4eb3-8aed-328884b53111', 'HORSE_SALE_V2', 'REPS', 'REPS.SELLER', 'Seller''s Representations', 'Seller represents and warrants that Seller has full authority to enter into this Agreement, that the warranties of title and the disclosures stated in this Agreement are true and complete to Seller''s knowledge, and that Seller will promptly disclose any material change in the Horse''s health, soundness, or behavior arising before Closing.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.582913+00', false);
INSERT INTO public.contract_clause_defs VALUES ('41357dbf-f6a8-439a-9b3a-2dd3067a8e2a', 'HORSE_SALE_V2', 'REPS', 'REPS.BUYER_ENT', 'Buyer''s Representations', 'Buyer represents and warrants that it is duly organized and in good standing, that the person signing on its behalf is authorized to bind it, that it has had the opportunity to inspect the Horse, to have the Horse examined by a veterinarian of its choosing, and to ask questions about the Horse, and that it has the knowledge and experience, directly or through its personnel, to evaluate the Horse''s suitability for its intended use. By signing this Agreement, Buyer acknowledges that it has read this Agreement, fully understands its terms, and understands that it is giving up substantial legal rights on behalf of Buyer and anyone claiming by, through, or under Buyer, including the right to sue the Seller Parties.', 'prose', 30, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:15.674697+00', false);
INSERT INTO public.contract_clause_defs VALUES ('0caea3e1-40a8-47c7-b757-173d85ac3131', 'HORSE_SALE_V2', 'REPS', 'REPS.BUYER_PENDING', 'Buyer''s Representations', '[Pending — select whether Buyer is an individual or an entity. This placeholder is replaced by the applicable representations and blocks signing.]', 'prose', 40, false, NULL, '{"equals": [""], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:15.721806+00', false);
INSERT INTO public.contract_clause_defs VALUES ('4a007f33-6528-4e76-a260-cab319e4ab29', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

BUYER
Signature: {{SIG.BUYER.NAME}}
Printed Name: {{BUYER.PRINTED_NAME}}
Date: {{SIG.BUYER.DATE}}', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 14:03:15.765016+00', false);
INSERT INTO public.contract_clause_defs VALUES ('aa20e851-43bc-41cd-8449-9e21e9f3afec', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.BUYER_CAPACITY', NULL, 'By: {{BUYER.ENTITY_SIGNER_NAME}}
Title: {{BUYER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{BUYER.FULL_NAME}}', 'input', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 14:03:15.808204+00', false);
INSERT INTO public.contract_clause_defs VALUES ('814f61b0-9517-49d1-bba1-7439079caa88', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.COBUYER_BLOCK', NULL, 'CO-BUYER
Signature: {{SIG.COBUYER.NAME}}
Printed Name: {{COBUYER.PRINTED_NAME}}
Date: {{SIG.COBUYER.DATE}}', 'input', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-08-02 14:03:15.851672+00', false);
INSERT INTO public.contract_clause_defs VALUES ('db725ec3-f106-4d7c-bb6d-9c6cf7fda2e0', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.COBUYER_CAPACITY', NULL, 'By: {{COBUYER.ENTITY_SIGNER_NAME}}
Title: {{COBUYER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{COBUYER.FULL_NAME}}', 'input', 40, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}, {"equals": ["ENTITY"], "field_key": "COBUYER.PARTY_TYPE"}]}', NULL, '2026-08-02 14:03:15.895305+00', false);
