INSERT INTO public.service_types VALUES ('INDEPENDENT_CONTRACTOR', 'Independent Contractor', 'Engagement of an independent contractor providing services to FHE.', 'internal', false, true, 13, NULL, 1, NULL);
INSERT INTO public.service_types VALUES ('ONBOARDING', 'Account Onboarding', 'Administrative engagement carrying the first-login paperwork assigned to a new client.', 'acquisition', false, true, 99, NULL, 1, NULL);
INSERT INTO public.service_types VALUES ('HORSE_SALE_ASSISTANCE', 'Horse Sale Assistance', 'Representation of a seller through a horse sale transaction.', 'acquisition', true, true, 4, NULL, 1, NULL);
INSERT INTO public.service_types VALUES ('HORSE_LEASE_IN_ASSISTANCE', 'Horse Lease-In Assistance', 'Representation of a lessee arranging a horse lease.', 'acquisition', true, true, 5, NULL, 1, NULL);
INSERT INTO public.service_types VALUES ('HORSE_LEASE_OUT_ASSISTANCE', 'Horse Lease-Out Assistance', 'Representation of a lessor leasing a horse out.', 'acquisition', true, true, 6, NULL, 1, NULL);
INSERT INTO public.service_types VALUES ('JUMPER_TRAINING', 'Jumper Training', 'Jumping-specific instruction: grids, courses, and competition preparation.', 'rider', false, true, 11, NULL, 1, NULL);
INSERT INTO public.service_types VALUES ('HORSE_FINDER', 'Horse Finder', 'Search and sourcing on either side of a deal: shortlisting horses matched to a buyer''s or lessee''s goals, budget, and experience — or finding a buyer or lessee for a horse the client owns.', 'acquisition', false, true, 1, NULL, 2, 3);
INSERT INTO public.service_types VALUES ('HORSE_EVALUATION', 'Horse Evaluation', 'On-site evaluation of a horse under consideration: movement, temperament, training, soundness.', 'acquisition', true, true, 2, NULL, 1, 4);
INSERT INTO public.service_types VALUES ('HORSE_PURCHASE_ASSISTANCE', 'Transaction Assistance', 'Full service assistance for purchase and lease transactions.', 'acquisition', true, true, 3, NULL, 1, 8);
INSERT INTO public.service_types VALUES ('HORSE_TRAINING', 'Horse Training', 'Horse-specific training performed by FHE: training rides, development, behavioural and performance work.', 'horse', true, true, 7, NULL, 2, 5);
INSERT INTO public.service_types VALUES ('HORSE_EXERCISE', 'Horse Exercise', 'Riding, exercising, and turning out a client''s horse on their behalf.', 'horse', true, true, 8, NULL, 2, 6);
INSERT INTO public.service_types VALUES ('HORSE_CLIPPING', 'Horse Clipping', 'Specialized coat clipping: full body, trace, blanket, hunter, and custom clips.', 'horse', true, true, 9, '/reference-images/cover-hair-clipping.png', 1, 7);
INSERT INTO public.service_types VALUES ('RIDING_LESSON', 'Riding Lesson', 'Mounted instruction: position, flatwork, and riding skills.', 'rider', false, true, 10, '/reference-images/cover-horse-riding-lesson.jpg', 2, 1);
INSERT INTO public.service_types VALUES ('HORSEMANSHIP_TRAINING', 'Horsemanship Training', 'Participant education in safely understanding and handling horses: handling, safety, grooming, tacking, stable practice.', 'rider', false, true, 12, '/reference-images/cover-horsemanship.png', 2, 2);


