INSERT INTO public.contract_templates VALUES ('0c4c8d1c-310d-406e-8404-4b6cf9fa8e36', 'RIDER_LESSON', 'Riding Lesson Order Form', NULL, '{CLIENT}', 'RIDING LESSON ORDER

Order ID: {{ORD.UUID}}
